// Package index is the secondary index every realm with a store was writing by
// hand: a lookup from a key a human typed to the [store.ID]s that carry it.
//
// A realm keeps its records in a [gno.land/p/moul/kit/store] and answers
// "entry 7". The moment it also has to answer "every entry tagged gno" it needs
// a second container, and the correctness of the pair is entirely in the
// discipline of writing both in the same function. This package owns the second
// container and as much of that discipline as a package can.
//
//	var notes = store.Named("note")
//	var byTag index.Index // the zero value is an empty, usable index
//
//	func Post(cur realm, tag, body string) int64 {
//		id := notes.Add(&note{Tag: tag, Body: body})
//		if err := byTag.Add(tag, id); err != nil {
//			panic(err) // the store write is not committed either: same frame
//		}
//		return int64(id)
//	}
//
// It is NOT a multi-index record store. [gno.land/p/moul/collection] is that,
// and at n = 1,000 an update there costs 964,833 gas against the 508,977 that
// created the record, because it re-indexes every index whether or not the
// indexed value changed. Two containers written side by side cost a third of
// that and the realm can see what it is paying for.
//
// Live demo: r/moul/x/kitindexdemo.
package index

import (
	"errors"

	"gno.land/p/moul/kit/store/v0"
	"gno.land/p/nt/bptree/v0"
)

// Fanout is the B+ tree fanout this package uses: 32, because an index's keys
// are removed as its records move.
//
// A removal shifts every later value in its leaf and rewrites each one, and an
// index's values are pointers: measured on a real node against gno master
// 3cc494ec4 on 2026-10-02, removing the first key of a fanout-128 leaf holding
// 120 cost 35.3M gas against 8.0M for the last, about 230k per value shifted.
// Fanout 32 bounds what one removal rewrites to about 45 values: its own
// leaf, and a neighbour's when the leaf underflows and borrows. What it costs, measured against gno master
// 1fc4c140e on 2026-09-29 at n = 1,000 with string values: 671 bytes per entry
// and 162,161 gas per insert, against 592 and 152,975 at fanout 128, and avl's
// 2,029 and 417,811.
const Fanout = 32

// Errors an Add can return. A /p/ package returns errors and lets the realm
// decide whether they are fatal; every one of these is a programming error in
// the realm rather than a value a user chose, so panicking on them is the
// normal handling.
var (
	// ErrEmptyKey is returned for "". An empty key sorts before every real one
	// and is almost always an unset field rather than a deliberate bucket, so
	// it is refused rather than silently indexed.
	ErrEmptyKey = errors.New("index: the key is empty")

	// ErrZeroID is returned for store.ID(0), which [store.Store] never assigns,
	// so indexing it can only produce a lookup that cannot hit.
	ErrZeroID = errors.New("index: the id is zero")

	// ErrDuplicateKey is returned by a [Unique] index asked to attach a second
	// id to a key that already has one.
	ErrDuplicateKey = errors.New("index: the key is already taken")
)

// Index maps a key to the ids carrying it, ordered by key.
//
// The zero value is an empty, usable, non-unique index: a realm declares
// `var byTag index.Index` and writes to it, exactly as it does with a
// [store.Store]. Use [Unique] when at most one id may carry a key.
//
// An Index is a handle, like the [store.Store] it sits next to: copies taken
// after the first write, or of anything [Unique] returned, are the same index,
// and a write through one is seen through all of them. A copy of a zero value
// that was never written is a separate empty index.
type Index struct {
	s *state
}

// state is everything an Index holds, behind one pointer so that a copy of the
// handle cannot split the tree from the counter that describes it.
type state struct {
	tree   *bptree.BPTree
	unique bool
	pairs  int
}

// New returns an empty index where a key may carry many ids. It is the zero
// value, spelled out for a caller who prefers a constructor.
func New() *Index { return &Index{} }

// Unique returns an empty index where a key carries at most one id, and a
// second [Index.Add] to the same key fails with [ErrDuplicateKey] instead of
// appending.
//
// Unique is a constructor rather than a field or a setter because flipping it
// on a populated index would have to either reject the duplicates already in it
// or silently keep them, and both are worse than not offering the operation.
func Unique() *Index {
	return &Index{s: &state{tree: bptree.NewBPTreeN(Fanout), unique: true}}
}

// entry is the value stored at a key: the ids carrying it, ascending.
//
// A struct rather than a bare []store.ID so that a later field (a count, a
// timestamp) does not change the stored shape, and so the slice itself is never
// handed out by accident.
type entry struct {
	ids []store.ID
}

// init materialises the state. Called by every mutating method, so the zero
// value works without a constructor. The tree is created with the state, so a
// non-nil state always has one.
func (ix *Index) init() {
	if ix.s == nil {
		ix.s = &state{tree: bptree.NewBPTreeN(Fanout)}
	}
}

// Add attaches id to key.
//
// Adding a pair that is already present is a no-op and returns nil, so a realm
// re-running a write is not punished for it. The ids under a key are kept
// ascending, which makes [Index.Lookup] depend on the set of ids and not on the
// order they arrived in: two realms that indexed the same records in a
// different order render identically, and a Render whose output depends on
// insertion history is the determinism bug this avoids.
func (ix *Index) Add(key string, id store.ID) error {
	if key == "" {
		return ErrEmptyKey
	}
	if id == 0 {
		return ErrZeroID
	}
	ix.init()

	e, _ := ix.s.tree.Get(key).(*entry)
	if e == nil {
		ix.s.tree.Set(key, &entry{ids: []store.ID{id}})
		ix.s.pairs++
		return nil
	}
	pos, found := e.find(id)
	if found {
		return nil
	}
	if ix.s.unique {
		return ErrDuplicateKey
	}
	e.ids = append(e.ids, 0)
	copy(e.ids[pos+1:], e.ids[pos:])
	e.ids[pos] = id
	ix.s.tree.Set(key, e)
	ix.s.pairs++
	return nil
}

// Remove detaches id from key and reports whether the pair was there. A key
// whose last id is removed is removed with it, so [Index.Keys] never counts an
// empty bucket.
func (ix *Index) Remove(key string, id store.ID) bool {
	if ix.s == nil {
		return false
	}
	e, _ := ix.s.tree.Get(key).(*entry)
	if e == nil {
		return false
	}
	pos, found := e.find(id)
	if !found {
		return false
	}
	ix.s.pairs--
	if len(e.ids) == 1 {
		ix.s.tree.Remove(key)
		return true
	}
	// A fresh slice, not append(ids[:pos], ids[pos+1:]...).
	//
	// In gno a slice is ONE persisted object and the storage deposit comes back
	// when that object is dropped, at no other time: shortening in place keeps
	// the peak allocation charged until the whole key goes, so a key that grew
	// to 1,000 ids and shrank to 1 would still be paying for 1,000. Allocating
	// the exact size drops the old array and refunds the difference. Same O(n)
	// as the memmove it replaces.
	trimmed := make([]store.ID, 0, len(e.ids)-1)
	trimmed = append(trimmed, e.ids[:pos]...)
	trimmed = append(trimmed, e.ids[pos+1:]...)
	e.ids = trimmed
	ix.s.tree.Set(key, e)
	return true
}

// RemoveKey detaches every id from key and reports how many it detached.
func (ix *Index) RemoveKey(key string) int {
	if ix.s == nil {
		return 0
	}
	v, removed := ix.s.tree.Remove(key)
	if !removed {
		return 0
	}
	n := len(v.(*entry).ids)
	ix.s.pairs -= n
	return n
}

// Lookup returns the ids carrying key, ascending, or nil.
//
// The slice is a COPY. Handing out the stored one would make every caller a
// writer: an append past its length would be invisible to the index, and an
// assignment into it would corrupt the index with no write path having been
// called. A realm that returns this value onward is returning its own data,
// not a handle to ours.
func (ix *Index) Lookup(key string) []store.ID {
	if ix.s == nil {
		return nil
	}
	e, _ := ix.s.tree.Get(key).(*entry)
	if e == nil {
		return nil
	}
	out := make([]store.ID, len(e.ids))
	copy(out, e.ids)
	return out
}

// First returns the lowest id carrying key. On a [Unique] index it is the only
// one, which is the usual reason to call it.
func (ix *Index) First(key string) (store.ID, bool) {
	if ix.s == nil {
		return 0, false
	}
	e, _ := ix.s.tree.Get(key).(*entry)
	if e == nil || len(e.ids) == 0 {
		return 0, false
	}
	return e.ids[0], true
}

// Has reports whether any id carries key.
func (ix *Index) Has(key string) bool {
	if ix.s == nil {
		return false
	}
	return ix.s.tree.Has(key)
}

// Count returns how many ids carry key.
func (ix *Index) Count(key string) int {
	if ix.s == nil {
		return 0
	}
	e, _ := ix.s.tree.Get(key).(*entry)
	if e == nil {
		return 0
	}
	return len(e.ids)
}

// Keys returns the number of distinct keys.
func (ix *Index) Keys() int {
	if ix.s == nil {
		return 0
	}
	return ix.s.tree.Size()
}

// Len returns the number of (key, id) pairs, which is what the index actually
// costs. It is NOT [Index.Keys], and the two differ by exactly the amount of
// fan-out a realm has.
func (ix *Index) Len() int {
	if ix.s == nil {
		return 0
	}
	return ix.s.pairs
}

// IsUnique reports whether this index was built by [Unique].
func (ix *Index) IsUnique() bool { return ix.s != nil && ix.s.unique }

// Each visits every key in ascending order with a copy of its ids, and stops
// when fn returns true. It reports whether it stopped early.
//
// True means stop, matching bptree.IterCbFn and kit/store's EachUntil exactly,
// so a callback moved between them keeps its meaning.
//
// fn must not call [Index.Add], [Index.Remove] or [Index.RemoveKey] on this
// index. The walk is the B+ tree's own, which holds a position inside a leaf:
// removing the key being visited shifts the next one into that slot and the
// walk steps over it, and inserting one ahead of it is visited twice. Collect
// what to change, then change it after Each returns.
func (ix *Index) Each(fn func(key string, ids []store.ID) bool) bool {
	if ix.s == nil {
		return false
	}
	return ix.s.tree.Iterate("", "", func(k string, v any) bool {
		e := v.(*entry)
		ids := make([]store.ID, len(e.ids))
		copy(ids, e.ids)
		return fn(k, ids)
	})
}

// Page returns page number page of size keys, ascending, each with a copy of
// its ids.
//
// Pages are 1-based, and every out-of-range page (zero, negative, past the end,
// any page of an empty index) returns nil rather than panicking, because the
// page number usually arrives from a Render path and is user input. This is
// NOT [store.Store.Page], which returns an empty non-nil slice past the end;
// test with len, not with nil, when code handles both.
func (ix *Index) Page(page, size int) []Entry {
	if ix.s == nil || page < 1 || size < 1 {
		return nil
	}
	// The offset is computed in a way that cannot wrap, because
	// bptree.IterateByOffset normalises a NEGATIVE offset to 0: an overflowed
	// (page-1)*size would silently hand back page 1 for a page past the end,
	// which is the opposite of this method's contract.
	//
	// page <= 1+(keys-1)/size bounds (page-1)*size by keys-1, so the product
	// cannot overflow, and it also rejects the page that starts exactly at the
	// end, which would otherwise come back as an empty non-nil slice while
	// every later page is nil.
	keys := ix.s.tree.Size()
	if keys == 0 || page > 1+(keys-1)/size {
		return nil
	}
	//gnovet:ignore page-offset-overflow bounded by keys-1 on the line above
	offset := (page - 1) * size

	// The capacity follows what exists, not what was asked for, so Page(1,
	// maxInt) over three keys reserves three slots and not two billion.
	room := keys - offset
	if room > size {
		room = size
	}
	out := make([]Entry, 0, room)
	ix.s.tree.IterateByOffset(offset, size, func(k string, v any) bool {
		e := v.(*entry)
		ids := make([]store.ID, len(e.ids))
		copy(ids, e.ids)
		out = append(out, Entry{Key: k, IDs: ids})
		return false
	})
	return out
}

// Pages returns how many pages of the given size the keys fill, at least 1 so
// a page picker always has something to render.
func (ix *Index) Pages(size int) int {
	if size < 1 {
		return 1
	}
	n := ix.Keys()
	if n == 0 {
		return 1
	}
	// 1 + (n-1)/size rather than (n+size-1)/size: the second overflows when
	// size is near the integer limit, wraps negative, and divides to 0, which
	// contradicts the "at least 1" this method promises and divides a page
	// picker by zero.
	return 1 + (n-1)/size
}

// Entry is one key and the ids carrying it, as returned by [Index.Page].
type Entry struct {
	Key string
	IDs []store.ID
}

// find returns the position id occupies, or would occupy, in the ascending ids,
// and whether it is already there. Binary search: a key with many ids is the
// case this package exists for.
func (e *entry) find(id store.ID) (int, bool) {
	lo, hi := 0, len(e.ids)
	for lo < hi {
		mid := int(uint(lo+hi) >> 1)
		switch {
		case e.ids[mid] == id:
			return mid, true
		case e.ids[mid] < id:
			lo = mid + 1
		default:
			hi = mid
		}
	}
	return lo, false
}

package index

import (
	"testing"

	"gno.land/p/moul/kit/store/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

func ids(ns ...uint64) []store.ID {
	out := make([]store.ID, len(ns))
	for i, n := range ns {
		out[i] = store.ID(n)
	}
	return out
}

func equalIDs(t *testing.T, want, got []store.ID) {
	t.Helper()
	urequire.Equal(t, len(want), len(got))
	for i := range want {
		uassert.Equal(t, want[i].String(), got[i].String())
	}
}

func TestZeroValueIsUsable(t *testing.T) {
	var ix Index
	uassert.Equal(t, 0, ix.Keys())
	uassert.Equal(t, 0, ix.Len())
	uassert.False(t, ix.Has("gno"))
	uassert.Equal(t, 0, ix.Count("gno"))
	uassert.Equal(t, 0, len(ix.Lookup("gno")))
	_, ok := ix.First("gno")
	uassert.False(t, ok)
	uassert.False(t, ix.Remove("gno", 1))
	uassert.Equal(t, 0, ix.RemoveKey("gno"))
	uassert.False(t, ix.Each(func(string, []store.ID) bool { return true }))

	urequire.NoError(t, ix.Add("gno", 1))
	uassert.Equal(t, 1, ix.Keys())
}

// The whole point of sorting the ids: Lookup must depend on the SET of ids, not
// on the order they arrived in, or two realms that indexed the same records in
// a different order render differently.
func TestLookupDoesNotDependOnInsertionOrder(t *testing.T) {
	forward, reverse := New(), New()
	for _, n := range []uint64{3, 1, 2} {
		urequire.NoError(t, forward.Add("gno", store.ID(n)))
	}
	for _, n := range []uint64{2, 1, 3} {
		urequire.NoError(t, reverse.Add("gno", store.ID(n)))
	}
	equalIDs(t, ids(1, 2, 3), forward.Lookup("gno"))
	equalIDs(t, ids(1, 2, 3), reverse.Lookup("gno"))
}

func TestAddIsIdempotentForTheSamePair(t *testing.T) {
	ix := New()
	urequire.NoError(t, ix.Add("gno", 7))
	urequire.NoError(t, ix.Add("gno", 7))
	equalIDs(t, ids(7), ix.Lookup("gno"))
	uassert.Equal(t, 1, ix.Len())
	uassert.Equal(t, 1, ix.Keys())
}

func TestAddRefusals(t *testing.T) {
	for _, tc := range []struct {
		name string
		key  string
		id   store.ID
		want error
	}{
		{"empty key", "", 1, ErrEmptyKey},
		{"zero id", "gno", 0, ErrZeroID},
	} {
		t.Run(tc.name, func(t *testing.T) {
			ix := New()
			err := ix.Add(tc.key, tc.id)
			urequire.ErrorIs(t, err, tc.want)
			uassert.Equal(t, 0, ix.Len())
		})
	}
}

func TestUniqueRefusesASecondID(t *testing.T) {
	ix := Unique()
	uassert.True(t, ix.IsUnique())
	urequire.NoError(t, ix.Add("moul", 1))

	err := ix.Add("moul", 2)
	urequire.ErrorIs(t, err, ErrDuplicateKey)
	equalIDs(t, ids(1), ix.Lookup("moul"))
	uassert.Equal(t, 1, ix.Len())

	// Re-adding the SAME pair is still a no-op, not a duplicate: a realm
	// re-running a write must not be punished for it.
	urequire.NoError(t, ix.Add("moul", 1))
	uassert.Equal(t, 1, ix.Len())
}

// Keys and Len answer different questions and the difference is the fan-out,
// which is what the index actually costs.
func TestKeysAndLenDiffer(t *testing.T) {
	ix := New()
	urequire.NoError(t, ix.Add("gno", 1))
	urequire.NoError(t, ix.Add("gno", 2))
	urequire.NoError(t, ix.Add("go", 3))
	uassert.Equal(t, 2, ix.Keys())
	uassert.Equal(t, 3, ix.Len())
	uassert.Equal(t, 2, ix.Count("gno"))
	uassert.Equal(t, 1, ix.Count("go"))
	uassert.Equal(t, 0, ix.Count("rust"))
}

func TestRemoveDropsTheKeyWithItsLastID(t *testing.T) {
	ix := New()
	urequire.NoError(t, ix.Add("gno", 1))
	urequire.NoError(t, ix.Add("gno", 2))

	uassert.True(t, ix.Remove("gno", 1))
	uassert.True(t, ix.Has("gno"))
	equalIDs(t, ids(2), ix.Lookup("gno"))

	uassert.True(t, ix.Remove("gno", 2))
	uassert.False(t, ix.Has("gno"))
	uassert.Equal(t, 0, ix.Keys())
	uassert.Equal(t, 0, ix.Len())

	uassert.False(t, ix.Remove("gno", 2))
}

func TestRemoveKey(t *testing.T) {
	ix := New()
	urequire.NoError(t, ix.Add("gno", 1))
	urequire.NoError(t, ix.Add("gno", 2))
	urequire.NoError(t, ix.Add("go", 3))

	uassert.Equal(t, 2, ix.RemoveKey("gno"))
	uassert.Equal(t, 1, ix.Keys())
	uassert.Equal(t, 1, ix.Len())
	uassert.Equal(t, 0, ix.RemoveKey("gno"))
}

// A returned slice that is the stored one makes every caller a writer: an
// assignment into it corrupts the index with no write path having been called.
func TestLookupHandsOutACopy(t *testing.T) {
	ix := New()
	urequire.NoError(t, ix.Add("gno", 1))
	urequire.NoError(t, ix.Add("gno", 2))

	got := ix.Lookup("gno")
	got[0] = store.ID(999)
	equalIDs(t, ids(1, 2), ix.Lookup("gno"))
}

func TestEachIsAscendingAndStops(t *testing.T) {
	ix := New()
	for _, k := range []string{"go", "gno", "rust"} {
		urequire.NoError(t, ix.Add(k, 1))
	}

	var seen []string
	uassert.False(t, ix.Each(func(k string, _ []store.ID) bool {
		seen = append(seen, k)
		return false
	}))
	urequire.Equal(t, 3, len(seen))
	uassert.Equal(t, "gno", seen[0])
	uassert.Equal(t, "go", seen[1])
	uassert.Equal(t, "rust", seen[2])

	var first string
	uassert.True(t, ix.Each(func(k string, _ []store.ID) bool {
		first = k
		return true
	}))
	uassert.Equal(t, "gno", first)
}

func TestEachHandsOutACopy(t *testing.T) {
	ix := New()
	urequire.NoError(t, ix.Add("gno", 1))
	ix.Each(func(_ string, got []store.ID) bool {
		got[0] = store.ID(999)
		return true
	})
	equalIDs(t, ids(1), ix.Lookup("gno"))
}

func TestPage(t *testing.T) {
	ix := New()
	for _, k := range []string{"a", "b", "c", "d", "e"} {
		urequire.NoError(t, ix.Add(k, 1))
	}
	for _, tc := range []struct {
		name string
		page int
		size int
		want []string
	}{
		{"first", 1, 2, []string{"a", "b"}},
		{"second", 2, 2, []string{"c", "d"}},
		{"last, short", 3, 2, []string{"e"}},
		{"past the end", 4, 2, nil},
		{"page zero", 0, 2, nil},
		{"size zero", 1, 0, nil},
		{"negative page", -1, 2, nil},
	} {
		t.Run(tc.name, func(t *testing.T) {
			got := ix.Page(tc.page, tc.size)
			urequire.Equal(t, len(tc.want), len(got))
			for i := range tc.want {
				uassert.Equal(t, tc.want[i], got[i].Key)
			}
		})
	}
}

// Pages is what a page picker divides by, so it is never 0.
func TestPagesIsNeverZero(t *testing.T) {
	ix := New()
	uassert.Equal(t, 1, ix.Pages(10))
	uassert.Equal(t, 1, ix.Pages(0))
	uassert.Equal(t, 1, ix.Pages(-1))

	for _, k := range []string{"a", "b", "c"} {
		urequire.NoError(t, ix.Add(k, 1))
	}
	uassert.Equal(t, 2, ix.Pages(2))
	uassert.Equal(t, 1, ix.Pages(3))
	uassert.Equal(t, 3, ix.Pages(1))
}

func TestFirst(t *testing.T) {
	ix := New()
	urequire.NoError(t, ix.Add("gno", 9))
	urequire.NoError(t, ix.Add("gno", 4))

	got, ok := ix.First("gno")
	urequire.True(t, ok)
	uassert.Equal(t, "4", got.String())

	_, ok = ix.First("missing")
	uassert.False(t, ok)
}

// Many ids under one key is the case this package exists for, so the binary
// search has to hold at a size where a linear scan would still look fine.
func TestManyIDsUnderOneKey(t *testing.T) {
	ix := New()
	for n := uint64(64); n >= 1; n-- {
		urequire.NoError(t, ix.Add("gno", store.ID(n)))
	}
	uassert.Equal(t, 64, ix.Count("gno"))
	uassert.Equal(t, 1, ix.Keys())

	got := ix.Lookup("gno")
	urequire.Equal(t, 64, len(got))
	for i, id := range got {
		uassert.Equal(t, store.ID(i+1).String(), id.String())
	}
}

// maxInt is the largest int, which is where unchecked arithmetic in Page and
// Pages goes wrong.
const maxInt = int(^uint(0) >> 1)

// A removed id must drop the old backing array, not merely shorten it.
//
// In gno a slice is ONE persisted object, and the deposit comes back when the
// object is dropped and at no other time (EFFECTIVE_GNO.md section 2.12).
// Shortening in place keeps the peak allocation charged until the whole key
// goes, so a key that grew to 1,000 ids and shrank to 1 would still be paying
// for 1,000.
//
// Not observable through the API, so this reads the entry directly: same
// package, and the invariant is worth more than the encapsulation.
func TestRemoveReleasesTheBackingArray(t *testing.T) {
	ix := New()
	for n := uint64(1); n <= 16; n++ {
		urequire.NoError(t, ix.Add("gno", store.ID(n)))
	}
	for n := uint64(1); n <= 15; n++ {
		uassert.True(t, ix.Remove("gno", store.ID(n)))
	}

	e, _ := ix.s.tree.Get("gno").(*entry)
	urequire.True(t, e != nil)
	uassert.Equal(t, 1, len(e.ids))
	uassert.Equal(t, 1, cap(e.ids),
		"the shrunk bucket still owns its peak allocation, so the deposit never comes back")
}

// Page's contract is that a page past the end is nil. Unchecked
// (page-1)*size wraps negative at the limit, and bptree.IterateByOffset
// normalises a negative offset to 0, so the caller silently gets page 1.
func TestPageDoesNotWrapAtTheIntegerLimit(t *testing.T) {
	ix := New()
	for _, k := range []string{"a", "b", "c"} {
		urequire.NoError(t, ix.Add(k, 1))
	}
	uassert.Equal(t, 0, len(ix.Page(maxInt, 2)),
		"a page past the end is nil, including when the offset would overflow")
	uassert.Equal(t, 0, len(ix.Page(maxInt/2+2, 2)))
}

// A huge size must not reserve a huge slice for three keys.
func TestPageCapsItsAllocationToWhatExists(t *testing.T) {
	ix := New()
	for _, k := range []string{"a", "b", "c"} {
		urequire.NoError(t, ix.Add(k, 1))
	}
	got := ix.Page(1, maxInt)
	urequire.Equal(t, 3, len(got))
	uassert.True(t, cap(got) <= 3, "the capacity follows the keys, not the requested size")
}

// Pages documents "at least 1". The ceiling n+size-1 wraps when size is the
// limit, and the division then returns 0.
func TestPagesNeverReturnsZeroAtTheIntegerLimit(t *testing.T) {
	ix := New()
	urequire.NoError(t, ix.Add("a", 1))
	urequire.NoError(t, ix.Add("b", 1))
	uassert.Equal(t, 1, ix.Pages(maxInt))
}

// An Index is a handle. A copy taken after the first write must see every
// later write through either copy, or Len (a counter) and Keys (the tree)
// disagree about what the index holds.
func TestCopiesAfterTheFirstWriteShareOneIndex(t *testing.T) {
	var a Index
	urequire.NoError(t, a.Add("a", 1))
	b := a
	urequire.NoError(t, b.Add("b", 2))
	uassert.Equal(t, 2, a.Keys())
	uassert.Equal(t, 2, a.Len(), "the copy wrote a pair the original does not count")
	uassert.True(t, b.Remove("a", 1))
	uassert.Equal(t, 1, a.Len())

	u := *Unique()
	v := u
	urequire.NoError(t, v.Add("k", 1))
	uassert.ErrorIs(t, u.Add("k", 2), ErrDuplicateKey)
	uassert.Equal(t, 1, u.Len())
}

// Every out-of-range page is nil, including the one that starts exactly at
// the end and the first page of an index that has been emptied.
func TestPagePastTheEndIsAlwaysNil(t *testing.T) {
	ix := New()
	for _, k := range []string{"a", "b", "c", "d"} {
		urequire.NoError(t, ix.Add(k, 1))
	}
	uassert.True(t, ix.Page(2, 2) != nil)
	uassert.True(t, ix.Page(3, 2) == nil, "a page starting exactly at the end is past the end")
	uassert.True(t, ix.Page(4, 2) == nil)

	for _, k := range []string{"a", "b", "c", "d"} {
		uassert.Equal(t, 1, ix.RemoveKey(k))
	}
	uassert.True(t, ix.Page(1, 2) == nil, "an emptied index has no first page")

	var zero Index
	uassert.True(t, zero.Page(1, 2) == nil)
}

// Package ufmt is a preview of gno.land/p/nt/ufmt/v2, published here before
// that path exists.
//
// This is v2 of ufmt. It is not yet published at its expected path,
// gno.land/p/nt/ufmt/v2. Until it is, import it from
// gno.land/p/moul/vendor/nt/ufmt/v2; once gno.land/p/nt/ufmt/v2 is live,
// switch the import and nothing else, because the API is meant to be the same.
// This path is then frozen and never updated again.
//
// v0 (gno.land/p/nt/ufmt/v0) supports a handful of verbs and no flags, so
// "%08x", "%X" and "%-10s" print "(unhandled)" or drop their padding without a
// word. v2 follows Go's fmt instead: the same flags, widths, precisions and
// verbs, and the same error strings in place of panics. Where it cannot follow
// Go, because gno has no reflect, it says so below.
//
// Supported, as in Go's fmt:
//
//	flags      '+' '-' '#' ' ' '0'
//	width      %8d, %*d, and a negative * width left-justifies
//	precision  %.2f, %.*f, %.3s (in runes)
//	indexes    %[2]d %[1]s, %[1]*[2]d
//	general    %v %+v %#v %T %%
//	bool       %t
//	integer    %b %c %d %o %O %q %x %X %U, every int and uint type
//	float      %b %e %E %f %F %g %G %x %X, float32 and float64
//	string     %s %q %x %X, and []byte the same way
//	errors     %w in Errorf, unwrapped by errors.Unwrap and errors.Is
//	methods    Formatter, GoStringer, error, Stringer, in Go's order
//	composite  []T of the basic types, []any, []error, and map[string]T
//	           with its keys sorted, as Go prints them
//
// Errors are written into the output, never panicked: "%!d(string=hi)" for a
// wrong type, "%!d(MISSING)" for a missing argument, "%!(EXTRA int=1)" for an
// unused one, "%!(NOVERB)" for a trailing '%'.
//
// What gno cannot do, and what v2 prints instead:
//
//   - no reflect, so a struct, a pointer, a named type without a String
//     method, or a slice or map of anything other than the types listed above
//     prints "(unhandled)", and %T names only the types it knows ("unknown"
//     otherwise). Give the type a String method.
//   - %p is not supported.
//
// What changed from v0, so a migration is a review and not a find-and-replace:
//
//   - Sprint adds a space only between two operands when neither is a string,
//     as Go does; v0 put a space between every pair.
//   - %v of a float, and Sprint of one, is the shortest representation ("3.14"),
//     as Go does; v0 printed "%f" ("3.140000") from Sprint.
//   - %e defaults to 6 digits after the point, as Go does; v0 used 2.
//   - %v of a []byte prints "[104 105]", as Go does; v0 wrote the raw bytes.
//     Use %s for the string.
//   - a missing or extra argument, or a trailing '%', is written into the
//     output instead of panicking.
//   - an error is preferred to a String method when a value has both.
package ufmt

package ufmt

import (
	"strconv"
	"unicode/utf8"
)

// This file is the low level: padding, integers, floats, strings. It is a port
// of format.go in Go's fmt, kept close enough to read side by side.

const (
	ldigits = "0123456789abcdefx"
	udigits = "0123456789ABCDEFX"
)

// clearFlags resets everything a verb's specifier sets.
func (p *printer) clearFlags() {
	p.plus, p.minus, p.sharp, p.space, p.zero = false, false, false, false, false
	p.plusV, p.sharpV = false, false
	p.wid, p.prec = 0, 0
	p.widPresent, p.precPresent = false, false
}

// writePadding writes n pad bytes: zeros when the 0 flag is set, else spaces.
func (p *printer) writePadding(n int) {
	if n <= 0 {
		return
	}
	c := byte(' ')
	if p.zero {
		c = '0'
	}
	for i := 0; i < n; i++ {
		p.buf = append(p.buf, c)
	}
}

// pad writes b, padded to the width in runes, on the side the - flag says.
func (p *printer) pad(b []byte) {
	if !p.widPresent || p.wid == 0 {
		p.buf = append(p.buf, b...)
		return
	}
	width := p.wid - utf8.RuneCount(b)
	if !p.minus {
		p.writePadding(width)
		p.buf = append(p.buf, b...)
	} else {
		p.buf = append(p.buf, b...)
		p.writePadding(width)
	}
}

// padString is pad for a string.
func (p *printer) padString(s string) {
	if !p.widPresent || p.wid == 0 {
		p.buf = append(p.buf, s...)
		return
	}
	width := p.wid - utf8.RuneCountInString(s)
	if !p.minus {
		p.writePadding(width)
		p.buf = append(p.buf, s...)
	} else {
		p.buf = append(p.buf, s...)
		p.writePadding(width)
	}
}

// padNoZero pads with spaces whatever the 0 flag says.
func (p *printer) padNoZero(b []byte) {
	oldZero := p.zero
	p.zero = false
	p.pad(b)
	p.zero = oldZero
}

func (p *printer) fmtBoolean(v bool) {
	if v {
		p.padString("true")
	} else {
		p.padString("false")
	}
}

// fmtInteger formats u, the magnitude, in base, with a '-' when negative.
func (p *printer) fmtInteger(u uint64, negative bool, base int, verb rune, digits string) {
	// Fast path: no flags, width or precision, lowercase digits.
	if !p.widPresent && !p.precPresent && !p.plus && !p.space && !p.sharp &&
		verb != 'O' && (base != 16 || digits[10] == 'a') {
		if negative {
			p.buf = append(p.buf, '-')
		}
		p.buf = strconv.AppendUint(p.buf, u, base)
		return
	}

	prec := 0
	if p.precPresent {
		prec = p.prec
		// %.0d of zero prints nothing but its padding.
		if prec == 0 && u == 0 {
			oldZero := p.zero
			p.zero = false
			p.writePadding(p.wid)
			p.zero = oldZero
			return
		}
	} else if p.zero && !p.minus && p.widPresent {
		// Zero padding is a precision in disguise, minus room for the sign.
		prec = p.wid
		if negative || p.plus || p.space {
			prec--
		}
	}

	size := 68 // 64 binary digits, a sign and a 0b/0x/0o prefix
	if prec+4 > size {
		size = prec + 4
	}
	buf := make([]byte, size)
	i := size

	switch base {
	case 10:
		for u >= 10 {
			i--
			next := u / 10
			buf[i] = byte('0' + u - next*10)
			u = next
		}
	case 16:
		for u >= 16 {
			i--
			buf[i] = digits[u&0xF]
			u >>= 4
		}
	case 8:
		for u >= 8 {
			i--
			buf[i] = byte('0' + u&7)
			u >>= 3
		}
	case 2:
		for u >= 2 {
			i--
			buf[i] = byte('0' + u&1)
			u >>= 1
		}
	}
	i--
	buf[i] = digits[u]
	for i > 0 && prec > size-i {
		i--
		buf[i] = '0'
	}

	if p.sharp {
		switch base {
		case 2:
			i--
			buf[i] = 'b'
			i--
			buf[i] = '0'
		case 8:
			if buf[i] != '0' {
				i--
				buf[i] = '0'
			}
		case 16:
			i--
			buf[i] = digits[16]
			i--
			buf[i] = '0'
		}
	}
	if verb == 'O' {
		i--
		buf[i] = 'o'
		i--
		buf[i] = '0'
	}

	if negative {
		i--
		buf[i] = '-'
	} else if p.plus {
		i--
		buf[i] = '+'
	} else if p.space {
		i--
		buf[i] = ' '
	}

	// The zeros, if any, are already in buf: pad the rest with spaces.
	p.padNoZero(buf[i:])
}

// fmtUnicode formats u as "U+0078", or "U+0078 'x'" with the # flag.
func (p *printer) fmtUnicode(u uint64) {
	prec := 4
	if p.precPresent && p.prec > 4 {
		prec = p.prec
	}
	hex := strconv.FormatUint(u, 16)
	b := []byte("U+")
	for n := len(hex); n < prec; n++ {
		b = append(b, '0')
	}
	for i := 0; i < len(hex); i++ {
		c := hex[i]
		if c >= 'a' {
			c -= 'a' - 'A'
		}
		b = append(b, c)
	}
	if p.sharp && u <= utf8.MaxRune && strconv.IsPrint(rune(u)) {
		b = append(b, ' ', '\'')
		b = utf8.AppendRune(b, rune(u))
		b = append(b, '\'')
	}
	p.padNoZero(b)
}

// fmtC formats u as the rune it encodes, or U+FFFD when it encodes none.
func (p *printer) fmtC(u uint64) {
	r := rune(utf8.RuneError)
	if u <= utf8.MaxRune {
		r = rune(u)
	}
	p.pad(utf8.AppendRune(nil, r))
}

// fmtQc formats u as a single-quoted rune literal.
func (p *printer) fmtQc(u uint64) {
	r := rune(utf8.RuneError)
	if u <= utf8.MaxRune {
		r = rune(u)
	}
	if p.plus {
		p.pad(strconv.AppendQuoteRuneToASCII(nil, r))
	} else {
		p.pad(strconv.AppendQuoteRune(nil, r))
	}
}

// fmtFloat formats v, with prec digits (-1 for the shortest) unless the verb
// set its own precision.
func (p *printer) fmtFloat(v float64, size int, verb rune, prec int) {
	if p.precPresent {
		prec = p.prec
	}
	// num[0] is reserved for the sign.
	num := strconv.AppendFloat([]byte{0}, v, byte(verb), prec, size)
	if num[1] == '-' || num[1] == '+' {
		num = num[1:]
	} else {
		num[0] = '+'
	}
	if p.space && num[0] == '+' && !p.plus {
		num[0] = ' '
	}
	// Infinities and NaN do not look like numbers, so they are never zero padded.
	if num[1] == 'I' || num[1] == 'N' {
		oldZero := p.zero
		p.zero = false
		if num[1] == 'N' && !p.space && !p.plus {
			num = num[1:]
		}
		p.pad(num)
		p.zero = oldZero
		return
	}

	// The # flag keeps the decimal point, and for %g the trailing zeros.
	if p.sharp && verb != 'b' {
		digits := 0
		if verb == 'v' || verb == 'g' || verb == 'G' || verb == 'x' {
			digits = prec
			if digits == -1 {
				digits = 6
			}
		}
		var tail []byte
		hasDecimalPoint := false
		sawNonzeroDigit := false
		for i := 1; i < len(num); i++ {
			c := num[i]
			if c == '.' {
				hasDecimalPoint = true
				continue
			}
			if c == 'p' || c == 'P' || ((c == 'e' || c == 'E') && verb != 'x' && verb != 'X') {
				tail = append(tail, num[i:]...)
				num = num[:i]
				break
			}
			if c != '0' {
				sawNonzeroDigit = true
			}
			if sawNonzeroDigit {
				digits--
			}
		}
		if !hasDecimalPoint {
			// A lone leading zero counts as one significant digit.
			if len(num) == 2 && num[1] == '0' {
				digits--
			}
			num = append(num, '.')
		}
		for digits > 0 {
			num = append(num, '0')
			digits--
		}
		num = append(num, tail...)
	}

	if p.plus || num[0] != '+' {
		// Zero padding goes after the sign.
		if p.zero && !p.minus && p.widPresent && p.wid > len(num) {
			p.buf = append(p.buf, num[0])
			p.writePadding(p.wid - len(num))
			p.buf = append(p.buf, num[1:]...)
			return
		}
		p.pad(num)
		return
	}
	p.pad(num[1:])
}

// truncate cuts s to the precision, counted in runes.
func (p *printer) truncate(s string) string {
	if p.precPresent {
		n := p.prec
		for i := range s {
			n--
			if n < 0 {
				return s[:i]
			}
		}
	}
	return s
}

func (p *printer) fmtS(s string) {
	p.padString(p.truncate(s))
}

// fmtSx formats s as hex, two digits a byte. The space flag separates bytes,
// and # prefixes 0x, once or before each byte when spaced.
func (p *printer) fmtSx(s string, digits string) {
	length := len(s)
	if p.precPresent && p.prec < length {
		length = p.prec
	}
	width := 2 * length
	if width > 0 {
		if p.space {
			if p.sharp {
				width *= 2
			}
			width += length - 1
		} else if p.sharp {
			width += 2
		}
	} else {
		if p.widPresent {
			p.writePadding(p.wid)
		}
		return
	}
	if p.widPresent && p.wid > width && !p.minus {
		p.writePadding(p.wid - width)
	}
	if p.sharp {
		p.buf = append(p.buf, '0', digits[16])
	}
	for i := 0; i < length; i++ {
		if p.space && i > 0 {
			p.buf = append(p.buf, ' ')
			if p.sharp {
				p.buf = append(p.buf, '0', digits[16])
			}
		}
		c := s[i]
		p.buf = append(p.buf, digits[c>>4], digits[c&0xF])
	}
	if p.widPresent && p.wid > width && p.minus {
		p.writePadding(p.wid - width)
	}
}

// fmtQ formats s as a double-quoted Go string, backquoted with the # flag when
// it can be, and ASCII only with the + flag.
func (p *printer) fmtQ(s string) {
	s = p.truncate(s)
	if p.sharp && strconv.CanBackquote(s) {
		p.padString("`" + s + "`")
		return
	}
	if p.plus {
		p.pad(strconv.AppendQuoteToASCII(nil, s))
	} else {
		p.pad(strconv.AppendQuote(nil, s))
	}
}

package ufmt

import (
	"errors"
	"strings"
	"testing"
)

type str struct{ s string }

func (v str) String() string { return v.s }

type errT struct{}

func (errT) Error() string  { return "boom" }
func (errT) String() string { return "stringer" }

type goStr struct{}

func (goStr) GoString() string { return "goStr{}" }
func (goStr) String() string   { return "plain" }

type formatter struct{}

func (formatter) Format(f State, verb rune) {
	w, wok := f.Width()
	p, pok := f.Precision()
	Fprintf(f, "F[%c w=%d/%t p=%d/%t minus=%t plus=%t sharp=%t]",
		verb, w, wok, p, pok, f.Flag('-'), f.Flag('+'), f.Flag('#'))
}

type panicky struct{}

func (panicky) String() string { panic("nope") }

type opaque struct{ n int }

// Every want below is what Go's fmt prints for the same call (go1.27.1),
// except where a comment says gno cannot see what Go sees.
func TestMethods(t *testing.T) {
	cases := []struct{ got, want string }{
		{Sprintf("%v|%s|%q|%x|%10s|%-6v|", str{"hi"}, str{"hi"}, str{"hi"}, str{"hi"}, str{"hi"}, str{"hi"}),
			`hi|hi|"hi"|6869|        hi|hi    |`},
		{Sprintf("%v %s", errT{}, errT{}), "boom boom"}, // Error wins over String
		{Sprintf("%#v %v", goStr{}, goStr{}), "goStr{} plain"},
		{Sprintf("%v|%-8.3s|%+#x", formatter{}, formatter{}, formatter{}),
			"F[v w=0/false p=0/false minus=false plus=false sharp=false]|" +
				"F[s w=8/true p=3/true minus=true plus=false sharp=false]|" +
				"F[x w=0/false p=0/false minus=false plus=true sharp=true]"},
		{Sprintf("%v", panicky{}), "%!v(PANIC=String method: nope)"},
		{Sprintf("%v", []any{str{"a"}, errT{}}), "[a boom]"},
		{Sprintf("%s", []error{errors.New("base"), errT{}}), "[base boom]"},
		{Sprint("a", 1, 2, "b", "c", 3.5, true, nil), "a1 2bc3.5 true <nil>"},
		{Sprint(str{"x"}, str{"y"}), "x y"},
		{Sprintln("a", 1, 2, "b"), "a 1 2 b\n"},

		// Go reflects into the struct and prints "{%!d(string=hi)}" and
		// "{7}"; gno has no reflect, so v2 says so instead of guessing.
		{Sprintf("%d", str{"hi"}), "%!d(unhandled)"},
		{Sprintf("%v", opaque{7}), "(unhandled)"},
		{Sprintf("%T", opaque{7}), "unknown"},
		// Go prints "%!w(*errors.errorString=&{base})": the type is not
		// nameable here either.
		{Sprintf("%w", errors.New("base")), "%!w(unhandled)"},
	}
	for i, c := range cases {
		if c.got != c.want {
			t.Errorf("case %d: got %q, want %q", i, c.got, c.want)
		}
	}
}

func TestErrorf(t *testing.T) {
	base := errors.New("base")

	e := Errorf("wrap: %w", base)
	if e.Error() != "wrap: base" || !errors.Is(e, base) || errors.Unwrap(e) != base {
		t.Errorf("single %%w: %q, Is=%t", e.Error(), errors.Is(e, base))
	}

	e2 := Errorf("two: %w and %w", base, errT{})
	if e2.Error() != "two: base and boom" || !errors.Is(e2, base) || errors.Unwrap(e2) != nil {
		t.Errorf("two %%w: %q, Is=%t", e2.Error(), errors.Is(e2, base))
	}

	if got := Errorf("%w", "notanerror").Error(); got != "%!w(string=notanerror)" {
		t.Errorf("non-error %%w: %q", got)
	}

	plain := Errorf("plain %d", 1)
	if plain.Error() != "plain 1" || errors.Unwrap(plain) != nil {
		t.Errorf("plain: %q", plain.Error())
	}
}

func TestWriters(t *testing.T) {
	var sb strings.Builder
	n, err := Fprintf(&sb, "%04d|", 7)
	Fprint(&sb, "a", 1)
	Fprintln(&sb, "!", 2)
	if sb.String() != "0007|a1! 2\n" || n != 5 || err != nil {
		t.Errorf("Fprint*: %q n=%d err=%v", sb.String(), n, err)
	}

	b := Appendf([]byte("x="), "%x", 255)
	b = Append(b, " ", true)
	b = Appendln(b, "", 1)
	if string(b) != "x=ff true 1\n" {
		t.Errorf("Append*: %q", string(b))
	}
}

// The register dump that v0 could not print: "0x(unhandled verb: %X)".
func TestRegisterDump(t *testing.T) {
	got := Sprintf("0x%08X %08x", uint32(0x1004), uint32(0xa00513))
	if got != "0x00001004 00a00513" {
		t.Errorf("got %q", got)
	}
}

package ufmt

import (
	"sort"
	"unicode/utf8"
)

// This file is the high level: parsing the format, and choosing how each
// operand prints. It is a port of print.go in Go's fmt, minus reflect.

const (
	commaSpace  = ", "
	nilAngle    = "<nil>"
	nilParen    = "(nil)"
	unhandled   = "(unhandled)"
	percentBang = "%!"
	missing     = "(MISSING)"
	badIndex    = "(BADINDEX)"
	extra       = "%!(EXTRA "
	badWidth    = "%!(BADWIDTH)"
	badPrec     = "%!(BADPREC)"
	noVerb      = "%!(NOVERB)"
)

// printer holds the output and the state of the verb being printed.
type printer struct {
	buf []byte

	// The flags, width and precision of the current verb.
	plus, minus, sharp, space, zero bool
	plusV, sharpV                   bool // %+v and %#v
	wid, prec                       int
	widPresent, precPresent         bool

	arg        any  // the operand being printed, for error messages
	erroring   bool // printing an error message: do not call methods
	reordered  bool // an explicit index was used
	goodArgNum bool // the last index was valid
	wrapErrs   bool // Errorf: %w is allowed
	wrapped    []int
}

func newPrinter() *printer {
	return &printer{}
}

// Write implements State, so a Formatter can write.
func (p *printer) Write(b []byte) (int, error) {
	p.buf = append(p.buf, b...)
	return len(b), nil
}

// WriteString lets a Formatter write a string without a conversion.
func (p *printer) WriteString(s string) (int, error) {
	p.buf = append(p.buf, s...)
	return len(s), nil
}

// Width implements State.
func (p *printer) Width() (int, bool) { return p.wid, p.widPresent }

// Precision implements State.
func (p *printer) Precision() (int, bool) { return p.prec, p.precPresent }

// Flag implements State.
func (p *printer) Flag(c int) bool {
	switch c {
	case '-':
		return p.minus
	case '+':
		return p.plus || p.plusV
	case '#':
		return p.sharp || p.sharpV
	case ' ':
		return p.space
	case '0':
		return p.zero
	}
	return false
}

func (p *printer) writeString(s string) { p.buf = append(p.buf, s...) }
func (p *printer) writeByte(c byte)     { p.buf = append(p.buf, c) }
func (p *printer) writeRune(r rune)     { p.buf = utf8.AppendRune(p.buf, r) }

// doPrint is Sprint: %v, with a space between two operands neither of which is
// a string.
func (p *printer) doPrint(a []any) {
	prevString := false
	for argNum, arg := range a {
		_, isString := arg.(string)
		if argNum > 0 && !isString && !prevString {
			p.writeByte(' ')
		}
		p.printArg(arg, 'v')
		prevString = isString
	}
}

// doPrintln is Sprintln: %v, always a space between operands, then a newline.
func (p *printer) doPrintln(a []any) {
	for argNum, arg := range a {
		if argNum > 0 {
			p.writeByte(' ')
		}
		p.printArg(arg, 'v')
	}
	p.writeByte('\n')
}

// parsenum reads a decimal number at s[start:end].
func parsenum(s string, start, end int) (num int, isnum bool, newi int) {
	if start >= end {
		return 0, false, end
	}
	for newi = start; newi < end && '0' <= s[newi] && s[newi] <= '9'; newi++ {
		if num > 1e6 {
			return 0, false, end // absurdly large: refuse rather than allocate
		}
		num = num*10 + int(s[newi]-'0')
		isnum = true
	}
	return
}

// intFromArg reads a * width or precision from a[argNum].
func intFromArg(a []any, argNum int) (num int, isInt bool, newArgNum int) {
	newArgNum = argNum
	if argNum >= len(a) {
		return
	}
	isInt = true
	switch v := a[argNum].(type) {
	case int:
		num = v
	case int8:
		num = int(v)
	case int16:
		num = int(v)
	case int32:
		num = int(v)
	case int64:
		num = int(v)
	case uint:
		num = int(v)
	case uint8:
		num = int(v)
	case uint16:
		num = int(v)
	case uint32:
		num = int(v)
	case uint64:
		num = int(v)
	default:
		isInt = false
	}
	newArgNum = argNum + 1
	if num > 1e6 || num < -1e6 {
		num = 0
		isInt = false
	}
	return
}

// argNumber reads an explicit index, "[3]", at format[i:].
func (p *printer) argNumber(argNum int, format string, i int, numArgs int) (newArgNum, newi int, found bool) {
	if len(format) <= i || format[i] != '[' {
		return argNum, i, false
	}
	p.reordered = true
	for j := 1; j < len(format)-i; j++ {
		if format[i+j] == ']' {
			width, ok, newi := parsenum(format, i+1, i+j)
			if !ok || newi != i+j {
				p.goodArgNum = false
				return argNum, i + j + 1, true
			}
			index := width - 1
			if index >= 0 && index < numArgs {
				return index, i + j + 1, true
			}
			p.goodArgNum = false
			return argNum, i + j + 1, true
		}
	}
	p.goodArgNum = false
	return argNum, i + 1, false
}

// doPrintf is Sprintf.
func (p *printer) doPrintf(format string, a []any) {
	end := len(format)
	argNum := 0
	afterIndex := false // the previous item was an index like [3]
	p.reordered = false

	for i := 0; i < end; {
		p.goodArgNum = true
		lasti := i
		for i < end && format[i] != '%' {
			i++
		}
		if i > lasti {
			p.writeString(format[lasti:i])
		}
		if i >= end {
			break
		}
		i++ // skip '%'

		p.clearFlags()

		// Fast path: a bare lowercase verb, "%d" or "%s", is most of what any
		// realm prints, and skips the specifier parsing entirely.
		if i < end && 'a' <= format[i] && format[i] <= 'z' && argNum < len(a) {
			verb := rune(format[i])
			if verb == 'w' {
				p.wrapped = append(p.wrapped, argNum)
			}
			p.printArg(a[argNum], verb)
			argNum++
			i++
			continue
		}

	flags:
		for ; i < end; i++ {
			switch format[i] {
			case '#':
				p.sharp = true
			case '0':
				p.zero = !p.minus // zero padding only ever goes on the left
			case '+':
				p.plus = true
			case '-':
				p.minus = true
				p.zero = false
			case ' ':
				p.space = true
			default:
				break flags
			}
		}

		argNum, i, afterIndex = p.argNumber(argNum, format, i, len(a))

		// Width.
		if i < end && format[i] == '*' {
			i++
			p.wid, p.widPresent, argNum = intFromArg(a, argNum)
			if !p.widPresent {
				p.writeString(badWidth)
			}
			if p.wid < 0 {
				p.wid = -p.wid
				p.minus = true
				p.zero = false
			}
			afterIndex = false
		} else {
			p.wid, p.widPresent, i = parsenum(format, i, end)
			if afterIndex && p.widPresent { // "%[3]2d"
				p.goodArgNum = false
			}
		}

		// Precision.
		if i+1 < end && format[i] == '.' {
			i++
			if afterIndex { // "%[3].2d"
				p.goodArgNum = false
			}
			argNum, i, afterIndex = p.argNumber(argNum, format, i, len(a))
			if i < end && format[i] == '*' {
				i++
				p.prec, p.precPresent, argNum = intFromArg(a, argNum)
				if p.prec < 0 {
					p.prec = 0
					p.precPresent = false
				}
				if !p.precPresent {
					p.writeString(badPrec)
				}
				afterIndex = false
			} else {
				p.prec, p.precPresent, i = parsenum(format, i, end)
				if !p.precPresent {
					p.prec = 0
					p.precPresent = true
				}
			}
		}

		if !afterIndex {
			argNum, i, afterIndex = p.argNumber(argNum, format, i, len(a))
		}

		if i >= end {
			p.writeString(noVerb)
			break
		}

		verb, size := rune(format[i]), 1
		if verb >= utf8.RuneSelf {
			verb, size = utf8.DecodeRuneInString(format[i:])
		}
		i += size

		switch {
		case verb == '%': // takes no operand, ignores width and precision
			p.writeByte('%')
		case !p.goodArgNum:
			p.badArgNum(verb)
		case argNum >= len(a):
			p.missingArg(verb)
		default:
			if verb == 'w' {
				p.wrapped = append(p.wrapped, argNum)
			}
			if verb == 'v' || verb == 'w' {
				p.sharpV, p.sharp = p.sharp, false
				p.plusV, p.plus = p.plus, false
			}
			p.printArg(a[argNum], verb)
			argNum++
		}
	}

	// Report unused operands, unless an index made the count meaningless.
	if !p.reordered && argNum < len(a) {
		p.clearFlags()
		p.writeString(extra)
		for i, arg := range a[argNum:] {
			if i > 0 {
				p.writeString(commaSpace)
			}
			if arg == nil {
				p.writeString(nilAngle)
				continue
			}
			p.writeString(typeName(arg))
			p.writeByte('=')
			p.printArg(arg, 'v')
		}
		p.writeByte(')')
	}
}

func (p *printer) badArgNum(verb rune) {
	p.writeString(percentBang)
	p.writeRune(verb)
	p.writeString(badIndex)
}

func (p *printer) missingArg(verb rune) {
	p.writeString(percentBang)
	p.writeRune(verb)
	p.writeString(missing)
}

// badVerb writes "%!d(string=hi)": the verb, the operand's type and its value.
func (p *printer) badVerb(verb rune) {
	p.erroring = true
	p.writeString(percentBang)
	p.writeRune(verb)
	p.writeByte('(')
	switch {
	case p.arg == nil:
		p.writeString(nilAngle)
	default:
		if t := typeName(p.arg); t != "unknown" {
			p.writeString(t)
			p.writeByte('=')
			p.printArg(p.arg, 'v')
		} else {
			p.writeString("unhandled")
		}
	}
	p.writeByte(')')
	p.erroring = false
}

// printArg prints one operand.
func (p *printer) printArg(arg any, verb rune) {
	p.arg = arg

	if arg == nil {
		switch verb {
		case 'T', 'v':
			p.padString(nilAngle)
		default:
			p.badVerb(verb)
		}
		return
	}

	switch verb {
	case 'T':
		p.fmtS(typeName(arg))
		return
	case 'p':
		p.badVerb(verb)
		return
	}

	// The basic types first, exactly as Go: a named type never matches these,
	// so its methods are still found below.
	switch f := arg.(type) {
	case bool:
		p.fmtBool(f, verb)
	case float32:
		p.fmtFloatVerb(float64(f), 32, verb)
	case float64:
		p.fmtFloatVerb(f, 64, verb)
	case int:
		p.fmtSigned(int64(f), verb)
	case int8:
		p.fmtSigned(int64(f), verb)
	case int16:
		p.fmtSigned(int64(f), verb)
	case int32:
		p.fmtSigned(int64(f), verb)
	case int64:
		p.fmtSigned(f, verb)
	case uint:
		p.fmtUnsigned(uint64(f), verb)
	case uint8:
		p.fmtUnsigned(uint64(f), verb)
	case uint16:
		p.fmtUnsigned(uint64(f), verb)
	case uint32:
		p.fmtUnsigned(uint64(f), verb)
	case uint64:
		p.fmtUnsigned(f, verb)
	case string:
		p.fmtString(f, verb)
	case []byte:
		p.fmtBytes(f, verb)
	default:
		if !p.handleMethods(verb) {
			p.printComposite(arg, verb)
		}
	}
}

// handleMethods prints arg with its own Format, GoString, Error or String
// method, in Go's order, and reports whether it did.
func (p *printer) handleMethods(verb rune) (handled bool) {
	if p.erroring {
		return false
	}
	if verb == 'w' {
		// %w is for Errorf, and for an error.
		if _, ok := p.arg.(error); !ok || !p.wrapErrs {
			p.badVerb(verb)
			return true
		}
		verb = 'v'
	}

	if f, ok := p.arg.(Formatter); ok {
		handled = true // stays true if the method panics
		defer p.catchPanic(p.arg, verb, "Format")
		f.Format(p, verb)
		return
	}

	if p.sharpV {
		if g, ok := p.arg.(GoStringer); ok {
			handled = true
			defer p.catchPanic(p.arg, verb, "GoString")
			p.fmtS(g.GoString())
			return
		}
		return false
	}

	switch verb {
	case 'v', 's', 'x', 'X', 'q':
		switch v := p.arg.(type) {
		case error:
			handled = true
			defer p.catchPanic(p.arg, verb, "Error")
			p.fmtString(v.Error(), verb)
			return
		case Stringer:
			handled = true
			defer p.catchPanic(p.arg, verb, "String")
			p.fmtString(v.String(), verb)
			return
		}
	}
	return false
}

// catchPanic turns a panicking method into "%!v(PANIC=String method: msg)".
func (p *printer) catchPanic(arg any, verb rune, method string) {
	r := recover()
	if r == nil {
		return
	}
	if p.erroring {
		panic(r) // the method panicked again while printing its own panic
	}
	p.clearFlags()
	p.writeString(percentBang)
	p.writeRune(verb)
	p.writeString("(PANIC=")
	p.writeString(method)
	p.writeString(" method: ")
	p.erroring = true
	p.printArg(r, 'v')
	p.erroring = false
	p.writeByte(')')
}

func (p *printer) fmtBool(v bool, verb rune) {
	switch verb {
	case 't', 'v':
		p.fmtBoolean(v)
	default:
		p.badVerb(verb)
	}
}

// fmtSigned prints a signed integer. The magnitude of math.MinInt64 does not
// fit an int64, so it is computed without ever negating v itself.
func (p *printer) fmtSigned(v int64, verb rune) {
	if v >= 0 {
		p.fmtIntegerVerb(uint64(v), false, true, verb)
		return
	}
	mag := uint64(-(v + 1)) + 1
	p.fmtIntegerVerb(mag, true, true, verb)
}

func (p *printer) fmtUnsigned(u uint64, verb rune) {
	p.fmtIntegerVerb(u, false, false, verb)
}

func (p *printer) fmtIntegerVerb(u uint64, negative, isSigned bool, verb rune) {
	switch verb {
	case 'v':
		if p.sharpV && !isSigned {
			p.fmt0x64(u, true)
		} else {
			p.fmtInteger(u, negative, 10, verb, ldigits)
		}
	case 'd':
		p.fmtInteger(u, negative, 10, verb, ldigits)
	case 'b':
		p.fmtInteger(u, negative, 2, verb, ldigits)
	case 'o', 'O':
		p.fmtInteger(u, negative, 8, verb, ldigits)
	case 'x':
		p.fmtInteger(u, negative, 16, verb, ldigits)
	case 'X':
		p.fmtInteger(u, negative, 16, verb, udigits)
	case 'c', 'q', 'U':
		if negative {
			u = ^u + 1 // back to two's complement, as Go sees it: never a rune
		}
		switch verb {
		case 'c':
			p.fmtC(u)
		case 'q':
			p.fmtQc(u)
		default:
			p.fmtUnicode(u)
		}
	default:
		p.badVerb(verb)
	}
}

// fmt0x64 prints u in hex with a 0x prefix (leading0x) or without one.
func (p *printer) fmt0x64(u uint64, leading0x bool) {
	sharp := p.sharp
	p.sharp = leading0x
	p.fmtInteger(u, false, 16, 'v', ldigits)
	p.sharp = sharp
}

func (p *printer) fmtFloatVerb(v float64, size int, verb rune) {
	switch verb {
	case 'v':
		p.fmtFloat(v, size, 'g', -1)
	case 'b', 'g', 'G', 'x', 'X':
		p.fmtFloat(v, size, verb, -1)
	case 'f', 'e', 'E':
		p.fmtFloat(v, size, verb, 6)
	case 'F':
		p.fmtFloat(v, size, 'f', 6)
	default:
		p.badVerb(verb)
	}
}

func (p *printer) fmtString(v string, verb rune) {
	switch verb {
	case 'v':
		if p.sharpV {
			p.fmtQ(v)
		} else {
			p.fmtS(v)
		}
	case 's':
		p.fmtS(v)
	case 'x':
		p.fmtSx(v, ldigits)
	case 'X':
		p.fmtSx(v, udigits)
	case 'q':
		p.fmtQ(v)
	default:
		p.badVerb(verb)
	}
}

func (p *printer) fmtBytes(v []byte, verb rune) {
	switch verb {
	case 'v', 'd':
		if p.sharpV {
			p.writeString("[]byte")
			if v == nil {
				p.writeString(nilParen)
				return
			}
			p.writeByte('{')
			for i, c := range v {
				if i > 0 {
					p.writeString(commaSpace)
				}
				p.fmt0x64(uint64(c), true)
			}
			p.writeByte('}')
			return
		}
		p.writeByte('[')
		for i, c := range v {
			if i > 0 {
				p.writeByte(' ')
			}
			p.fmtInteger(uint64(c), false, 10, verb, ldigits)
		}
		p.writeByte(']')
	case 's':
		p.fmtS(string(v))
	case 'x':
		p.fmtSx(string(v), ldigits)
	case 'X':
		p.fmtSx(string(v), udigits)
	case 'q':
		p.fmtQ(string(v))
	default:
		// Every other verb applies to each byte, as for any slice.
		p.writeByte('[')
		for i, c := range v {
			if i > 0 {
				p.writeByte(' ')
			}
			p.fmtUnsigned(uint64(c), verb)
		}
		p.writeByte(']')
	}
}

// printComposite prints the slices and maps gno can see without reflect.
func (p *printer) printComposite(arg any, verb rune) {
	switch v := arg.(type) {
	case []any:
		p.printSlice("[]interface {}", v == nil, len(v), func(i int) any { return v[i] }, verb)
	case []string:
		p.printSlice("[]string", v == nil, len(v), func(i int) any { return v[i] }, verb)
	case []error:
		p.printSlice("[]error", v == nil, len(v), func(i int) any { return v[i] }, verb)
	case []bool:
		p.printSlice("[]bool", v == nil, len(v), func(i int) any { return v[i] }, verb)
	case []int:
		p.printSlice("[]int", v == nil, len(v), func(i int) any { return v[i] }, verb)
	case []int8:
		p.printSlice("[]int8", v == nil, len(v), func(i int) any { return v[i] }, verb)
	case []int16:
		p.printSlice("[]int16", v == nil, len(v), func(i int) any { return v[i] }, verb)
	case []int32:
		p.printSlice("[]int32", v == nil, len(v), func(i int) any { return v[i] }, verb)
	case []int64:
		p.printSlice("[]int64", v == nil, len(v), func(i int) any { return v[i] }, verb)
	case []uint:
		p.printSlice("[]uint", v == nil, len(v), func(i int) any { return v[i] }, verb)
	case []uint16:
		p.printSlice("[]uint16", v == nil, len(v), func(i int) any { return v[i] }, verb)
	case []uint32:
		p.printSlice("[]uint32", v == nil, len(v), func(i int) any { return v[i] }, verb)
	case []uint64:
		p.printSlice("[]uint64", v == nil, len(v), func(i int) any { return v[i] }, verb)
	case []float32:
		p.printSlice("[]float32", v == nil, len(v), func(i int) any { return v[i] }, verb)
	case []float64:
		p.printSlice("[]float64", v == nil, len(v), func(i int) any { return v[i] }, verb)
	case map[string]string:
		keys := sortedKeys(len(v), func(add func(string)) {
			for k := range v {
				add(k)
			}
		})
		p.printMap("map[string]string", v == nil, keys, func(k string) any { return v[k] }, verb)
	case map[string]any:
		keys := sortedKeys(len(v), func(add func(string)) {
			for k := range v {
				add(k)
			}
		})
		p.printMap("map[string]interface {}", v == nil, keys, func(k string) any { return v[k] }, verb)
	case map[string]int:
		keys := sortedKeys(len(v), func(add func(string)) {
			for k := range v {
				add(k)
			}
		})
		p.printMap("map[string]int", v == nil, keys, func(k string) any { return v[k] }, verb)
	case map[string]bool:
		keys := sortedKeys(len(v), func(add func(string)) {
			for k := range v {
				add(k)
			}
		})
		p.printMap("map[string]bool", v == nil, keys, func(k string) any { return v[k] }, verb)
	default:
		if verb == 'v' {
			p.padString(unhandled)
		} else {
			p.badVerb(verb)
		}
	}
}

// printSlice prints "[a b]", or "[]T{a, b}" for %#v, each element with verb.
func (p *printer) printSlice(typ string, isNil bool, n int, at func(int) any, verb rune) {
	if p.sharpV {
		p.writeString(typ)
		if isNil {
			p.writeString(nilParen)
			return
		}
		p.writeByte('{')
		for i := 0; i < n; i++ {
			if i > 0 {
				p.writeString(commaSpace)
			}
			p.printElem(at(i), verb)
		}
		p.writeByte('}')
		return
	}
	p.writeByte('[')
	for i := 0; i < n; i++ {
		if i > 0 {
			p.writeByte(' ')
		}
		p.printElem(at(i), verb)
	}
	p.writeByte(']')
}

// printMap prints "map[a:1 b:2]", or "map[string]int{"a":1, "b":2}" for %#v,
// keys sorted as Go sorts them.
func (p *printer) printMap(typ string, isNil bool, keys []string, at func(string) any, verb rune) {
	if p.sharpV {
		p.writeString(typ)
		if isNil {
			p.writeString(nilParen)
			return
		}
		p.writeByte('{')
	} else {
		p.writeString("map[")
	}
	for i, k := range keys {
		if i > 0 {
			if p.sharpV {
				p.writeString(commaSpace)
			} else {
				p.writeByte(' ')
			}
		}
		p.printElem(k, verb)
		p.writeByte(':')
		p.printElem(at(k), verb)
	}
	if p.sharpV {
		p.writeByte('}')
	} else {
		p.writeByte(']')
	}
}

// printElem prints one element of a composite, keeping the outer operand for
// error messages. A nil element prints "<nil>" whatever the verb, as in Go.
func (p *printer) printElem(v any, verb rune) {
	outer := p.arg
	if v == nil {
		if p.sharpV {
			p.writeString("interface {}(nil)")
		} else {
			p.padString(nilAngle)
		}
	} else {
		p.printArg(v, verb)
	}
	p.arg = outer
}

func sortedKeys(n int, each func(add func(string))) []string {
	keys := make([]string, 0, n)
	each(func(k string) { keys = append(keys, k) })
	sort.Strings(keys)
	return keys
}

