package ufmt

import (
	"io"
	"strings"
)

// State is what a Formatter's Format method is handed: the flags, width and
// precision of the verb being printed, and somewhere to write.
type State interface {
	// Write emits formatted output.
	Write(b []byte) (n int, err error)
	// Width returns the width and whether one was set.
	Width() (wid int, ok bool)
	// Precision returns the precision and whether one was set.
	Precision() (prec int, ok bool)
	// Flag reports whether the flag c, a character, was set.
	Flag(c int) bool
}

// Formatter is implemented by a value that formats itself. Format is called
// for every verb, and its output replaces what ufmt would have printed.
type Formatter interface {
	Format(f State, verb rune)
}

// Stringer is implemented by a value that has a natural string form. It is
// used for %v, %s, %q, %x and %X, and by Print.
type Stringer interface {
	String() string
}

// GoStringer is implemented by a value that has a Go-syntax form, used for %#v.
type GoStringer interface {
	GoString() string
}

// Sprintf formats according to a format specifier and returns the string.
func Sprintf(format string, a ...any) string {
	p := newPrinter()
	p.doPrintf(format, a)
	return string(p.buf)
}

// Appendf formats according to a format specifier and appends the result to b.
func Appendf(b []byte, format string, a ...any) []byte {
	p := newPrinter()
	p.doPrintf(format, a)
	return append(b, p.buf...)
}

// Fprintf formats according to a format specifier and writes to w.
func Fprintf(w io.Writer, format string, a ...any) (n int, err error) {
	p := newPrinter()
	p.doPrintf(format, a)
	return w.Write(p.buf)
}

// Printf formats according to a format specifier and prints the result with
// the print builtin, which is what a test or a filetest captures.
func Printf(format string, a ...any) (n int, err error) {
	return printOut(Sprintf(format, a...))
}

// Sprint formats its operands with %v and returns the string. A space is added
// between two operands when neither is a string.
func Sprint(a ...any) string {
	p := newPrinter()
	p.doPrint(a)
	return string(p.buf)
}

// Append formats its operands as Sprint does and appends the result to b.
func Append(b []byte, a ...any) []byte {
	p := newPrinter()
	p.doPrint(a)
	return append(b, p.buf...)
}

// Fprint formats its operands as Sprint does and writes to w.
func Fprint(w io.Writer, a ...any) (n int, err error) {
	p := newPrinter()
	p.doPrint(a)
	return w.Write(p.buf)
}

// Print formats its operands as Sprint does and prints the result.
func Print(a ...any) (n int, err error) {
	return printOut(Sprint(a...))
}

// Sprintln formats its operands with %v, always separated by a space, and
// appends a newline.
func Sprintln(a ...any) string {
	p := newPrinter()
	p.doPrintln(a)
	return string(p.buf)
}

// Appendln formats its operands as Sprintln does and appends the result to b.
func Appendln(b []byte, a ...any) []byte {
	p := newPrinter()
	p.doPrintln(a)
	return append(b, p.buf...)
}

// Fprintln formats its operands as Sprintln does and writes to w.
func Fprintln(w io.Writer, a ...any) (n int, err error) {
	p := newPrinter()
	p.doPrintln(a)
	return w.Write(p.buf)
}

// Println formats its operands as Sprintln does and prints the result.
func Println(a ...any) (n int, err error) {
	return printOut(Sprintln(a...))
}

func printOut(s string) (int, error) {
	var sb strings.Builder
	n, err := sb.WriteString(s)
	print(sb.String())
	return n, err
}

// Errorf formats according to a format specifier and returns the string as an
// error. Each %w operand must be an error; it is printed as %v and returned by
// the error's Unwrap method, so errors.Is and errors.Unwrap can find it. One %w
// gives an Unwrap() error, several give an Unwrap() []error, as in Go.
func Errorf(format string, a ...any) error {
	p := newPrinter()
	p.wrapErrs = true
	p.doPrintf(format, a)
	s := string(p.buf)

	switch len(p.wrapped) {
	case 0:
		return &errorString{s}
	case 1:
		w := &wrapError{msg: s}
		w.err, _ = a[p.wrapped[0]].(error)
		return w
	default:
		if p.reordered {
			sortInts(p.wrapped)
		}
		var errs []error
		for i, argNum := range p.wrapped {
			if i > 0 && p.wrapped[i-1] == argNum {
				continue
			}
			if e, ok := a[argNum].(error); ok {
				errs = append(errs, e)
			}
		}
		return &wrapErrors{s, errs}
	}
}

type errorString struct {
	s string
}

func (e *errorString) Error() string { return e.s }

type wrapError struct {
	msg string
	err error
}

func (e *wrapError) Error() string { return e.msg }
func (e *wrapError) Unwrap() error { return e.err }

type wrapErrors struct {
	msg  string
	errs []error
}

func (e *wrapErrors) Error() string   { return e.msg }
func (e *wrapErrors) Unwrap() []error { return e.errs }

// sortInts is an insertion sort: the slice holds one entry per %w.
func sortInts(a []int) {
	for i := 1; i < len(a); i++ {
		for j := i; j > 0 && a[j] < a[j-1]; j-- {
			a[j], a[j-1] = a[j-1], a[j]
		}
	}
}

// Package coin is a GRC20 that cannot exist until its author has answered the
// three questions a social app's token usually dodges: what mints it, what
// burns it, and who has a reason to buy it.
//
// # Why a package and not a convention
//
// Every app in the x/social family is asked the same question, "and can it
// have a token", and the honest answer is only yes when all three of those
// have an answer. A token with a mint rule and no sink is a scoreboard with a
// price: supply grows, nothing consumes it, and the number on the leaderboard
// is the whole product. That is the shape a chain-wide measurement keeps
// finding, and it is cheap to avoid, so [New] refuses a [Policy] with a blank
// field rather than letting the omission ship.
//
// The three strings are not validated beyond being non-empty, because no
// package can check that a sink is real. They are a declaration, rendered on
// the realm's own page by [Coin.Render], where being wrong is visible.
//
// # The model
//
//	earned  minted by the app, for the behaviour the app wants more of
//	spent   burned by the app, for the thing holders actually want
//	traded  a plain GRC20 transfer, which is what makes the sink a market
//
// Earning and spending are the app's business and go through [Coin.Earn] and
// [Coin.Spend], which keep running totals so a reader can see the two halves
// against each other. Transfers, approvals and balances are the embedded
// [grc20.Token]'s, unchanged, so wallets and indexers see an ordinary GRC20.
//
// # Usage
//
// A realm holds one Coin and never exports the ledger:
//
//	var points = coin.New("Thread Points", "THREAD", 0, 0, coin.Policy{
//		Mint:  "1 per distinct address that replies to your thread",
//		Sink:  "burned to pin a thread to the top of its page",
//		Buyer: "anyone who wants placement and has not earned it",
//	}, 0, cur)
//
// The trailing `_ int, rlm realm` is the shape a pure package has to use to
// reach the caller's frame: a p/ package may not declare a crossing function,
// so the realm token is threaded as a later parameter, exactly as grc20's own
// tellers do.
package coin

import (
	"gno.land/p/moul/kit/num/v0"
	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/nt/grc20/v0"
	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Policy is the three declarations a Coin cannot be created without.
//
// Each one is a sentence for a human: it is rendered on the issuing realm's
// page and nothing branches on it.
type Policy struct {
	// Mint says what behaviour earns the token, precisely enough that a
	// reader can work out whether they can farm it.
	Mint string

	// Sink says what destroys it. "Nothing" is not an answer; if there is
	// no sink, there is no reason for the token to exist.
	Sink string

	// Buyer says who wants it badly enough to acquire it from someone who
	// earned it. This is the one most often left blank, and the one that
	// decides whether the other two matter.
	Buyer string
}

// Valid reports whether every field is filled in.
func (p Policy) Valid() bool {
	return p.Mint != "" && p.Sink != "" && p.Buyer != ""
}

// Coin is a GRC20 plus the policy it was issued under and the running totals
// of the two flows the policy describes.
type Coin struct {
	tok    *grc20.Token
	led    *grc20.PrivateLedger
	policy Policy

	earned int64 // cumulative minted
	spent  int64 // cumulative burned
}

// New issues the token. It panics when the policy is incomplete, which is the
// whole point of the package: the declaration happens before the first unit
// exists, not in a README written afterwards.
//
// name, symbol, decimals and id are grc20's own; id distinguishes two tokens
// issued by the same realm.
func New(name, symbol string, decimals int, id seqid.ID, policy Policy, _ int, rlm realm) *Coin {
	if !policy.Valid() {
		panic("coin: a token needs a mint rule, a sink and a buyer; one of the three is empty")
	}
	tok, led := grc20.NewToken(name, symbol, decimals, id, rlm)
	return &Coin{tok: tok, led: led, policy: policy}
}

// Token returns the GRC20 itself, for the realm to expose as its read API and
// to register with a token registry.
func (c *Coin) Token() *grc20.Token { return c.tok }

// CallerTeller is the teller that acts as the user who called the realm: it
// moves their own balance and nothing else.
//
// It is exposed, where the ledger is not, because transfer and approve are
// what make the sink a market. Mint and burn stay behind [Coin.Earn] and
// [Coin.Spend] so the mint rule keeps exactly one call site.
func (c *Coin) CallerTeller() grc20.Teller { return c.led.CallerTeller() }

// Policy returns the declarations the token was issued under.
func (c *Coin) Policy() Policy { return c.policy }

// Earn mints amount to addr. The realm calls it from the one place its mint
// rule is implemented, so that rule has exactly one call site.
//
// A non-positive amount is a no-op rather than an abort: a mint rule that
// computes zero (nothing new happened) is a normal outcome and should not
// fail the transaction that discovered it.
func (c *Coin) Earn(to address, amount int64) {
	if amount <= 0 {
		return
	}
	if err := c.led.Mint(to, amount); err != nil {
		panic("coin: mint: " + err.Error())
	}
	c.earned += amount
}

// Spend burns amount from addr, which is how the sink consumes supply.
//
// It aborts when the balance is short, naming both numbers, because the
// caller is a user who is about to be told they cannot afford something.
func (c *Coin) Spend(from address, amount int64) {
	if amount <= 0 {
		panic("coin: spend: amount must be positive")
	}
	if bal := c.tok.BalanceOf(from); bal < amount {
		panic(ufmt.Sprintf("coin: balance %d is short of %d %s", bal, amount, c.tok.GetSymbol()))
	}
	if err := c.led.Burn(from, amount); err != nil {
		panic("coin: burn: " + err.Error())
	}
	c.spent += amount
}

// BalanceOf is the holder's balance.
func (c *Coin) BalanceOf(addr address) int64 { return c.tok.BalanceOf(addr) }

// Supply is what exists right now, that is, earned minus spent.
func (c *Coin) Supply() int64 { return c.tok.TotalSupply() }

// Earned and Spent are the cumulative flows. Their difference is [Coin.Supply]
// and they are kept separately because a sink that never fires is invisible in
// the supply alone: a flat line reads the same as no sink at all.
func (c *Coin) Earned() int64 { return c.earned }

// Spent is the cumulative amount burned through [Coin.Spend].
func (c *Coin) Spent() int64 { return c.spent }

// Holders is how many addresses the ledger knows about.
func (c *Coin) Holders() int { return c.tok.KnownAccounts() }

// Render is the block a realm puts on its own page: the three declarations,
// then the two flows against each other.
//
// The policy strings are escaped: they are constants in practice, but a realm
// could build one from configuration, and this package cannot tell.
func (c *Coin) Render() string {
	out := md.H3(ui.Inline(c.tok.GetName()) + " (" + ui.Inline(c.tok.GetSymbol()) + ")")

	t := ui.NewTable("", "")
	t.Row("earns", ui.Cell(c.policy.Mint))
	t.Row("burns", ui.Cell(c.policy.Sink))
	t.Row("bought by", ui.Cell(c.policy.Buyer))
	out += t.String()

	s := ui.NewTable("supply", "earned", "burned", "holders")
	s.Row(
		num.Dec(c.Supply(), c.tok.GetDecimals()),
		num.Dec(c.earned, c.tok.GetDecimals()),
		num.Dec(c.spent, c.tok.GetDecimals()),
		ufmt.Sprintf("%d", c.Holders()),
	)
	out += s.String()

	return out
}

package coin

import (
	"strings"
	"testing"

	"gno.land/p/nt/seqid/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

var fullPolicy = Policy{
	Mint:  "1 per distinct replier",
	Sink:  "burned to pin a thread",
	Buyer: "anyone who wants placement",
}

// newTestCoin builds a Coin from a test. The same-realm cross promotes the
// test's EOA-origin cur into a code realm frame, which is what grc20.NewToken
// requires: it is the shape grc20's own tests use (vendor/.../token_test.gno).
func newTestCoin(t *testing.T, policy Policy, id seqid.ID, rlm realm) (c *Coin) {
	t.Helper()
	func(cur realm) {
		c = New("Test Points", "TEST", 0, id, policy, 0, cur)
	}(cross(rlm))
	return
}

func TestPolicyValid(t *testing.T) {
	tests := []struct {
		name string
		p    Policy
		want bool
	}{
		{"complete", fullPolicy, true},
		{"no mint rule", Policy{Sink: "s", Buyer: "b"}, false},
		{"no sink", Policy{Mint: "m", Buyer: "b"}, false},
		{"no buyer", Policy{Mint: "m", Sink: "s"}, false},
		{"empty", Policy{}, false},
	}
	for _, tt := range tests {
		uassert.Equal(t, tt.want, tt.p.Valid(), tt.name)
	}
}

// New's refusal is asserted with AbortsContains and not PanicsContains: the
// constructor runs behind a same-realm cross (the frame grc20.NewToken
// requires), and a panic raised across a crossing call is an abort that no
// recover() in the caller can catch.
func TestNewRefusesAnIncompletePolicy(cur realm, t *testing.T) {
	uassert.AbortsContains(t, cur, "mint rule, a sink and a buyer", func() {
		newTestCoin(t, Policy{Mint: "m", Sink: "s"}, 0, cur)
	})
}

func TestEarnAndSpendMoveSupplyInOppositeDirections(cur realm, t *testing.T) {
	c := newTestCoin(t, fullPolicy, 1, cur)
	alice := testutils.TestAddress("alice")

	c.Earn(alice, 10)
	uassert.Equal(t, int64(10), c.BalanceOf(alice))
	uassert.Equal(t, int64(10), c.Supply())

	c.Spend(alice, 4)
	uassert.Equal(t, int64(6), c.BalanceOf(alice))
	uassert.Equal(t, int64(6), c.Supply())

	// The flows stay visible after the fact, which the supply alone cannot
	// show: 6 in supply could be 6 earned and nothing burned.
	uassert.Equal(t, int64(10), c.Earned())
	uassert.Equal(t, int64(4), c.Spent())
}

func TestEarnOfNothingIsANoOp(cur realm, t *testing.T) {
	c := newTestCoin(t, fullPolicy, 2, cur)
	alice := testutils.TestAddress("alice")

	c.Earn(alice, 0)
	c.Earn(alice, -5)
	uassert.Equal(t, int64(0), c.Supply())
	uassert.Equal(t, int64(0), c.Earned())
	uassert.Equal(t, 0, c.Holders())
}

func TestSpendNamesBothNumbersWhenShort(cur realm, t *testing.T) {
	c := newTestCoin(t, fullPolicy, 3, cur)
	alice := testutils.TestAddress("alice")
	c.Earn(alice, 2)

	uassert.PanicsContains(t, cur, "balance 2 is short of 5", func() {
		c.Spend(alice, 5)
	})
	uassert.PanicsContains(t, cur, "must be positive", func() {
		c.Spend(alice, 0)
	})
	uassert.Equal(t, int64(2), c.BalanceOf(alice))
}

func TestRenderCarriesTheThreeDeclarations(cur realm, t *testing.T) {
	c := newTestCoin(t, fullPolicy, 4, cur)
	c.Earn(testutils.TestAddress("alice"), 7)
	c.Spend(testutils.TestAddress("alice"), 3)

	out := c.Render()
	for _, want := range []string{
		"Test Points",
		"TEST",
		fullPolicy.Mint,
		fullPolicy.Sink,
		fullPolicy.Buyer,
	} {
		uassert.True(t, strings.Contains(out, want), "render is missing "+want)
	}
	// 4 in supply, 7 earned, 3 burned, 1 holder.
	uassert.True(t, strings.Contains(out, "| 4 | 7 | 3 | 1 |"), "render is missing the flow row: "+out)
}

func TestTokenIsAnOrdinaryGRC20(cur realm, t *testing.T) {
	c := newTestCoin(t, fullPolicy, 5, cur)
	alice := testutils.TestAddress("alice")
	c.Earn(alice, 3)

	tok := c.Token()
	urequire.False(t, tok == nil, "token should not be nil")
	uassert.Equal(t, "TEST", tok.GetSymbol())
	uassert.Equal(t, int64(3), tok.TotalSupply())
	uassert.Equal(t, int64(3), tok.BalanceOf(alice))
}

// Package crew is small-group coordination as a product rather than as a
// framework: three to fifteen people with a shared pot, a way to decide, and a
// way to leave with their share.
//
// # Why not a DAO framework
//
// A framework asks you to pick a governance module, a voting strategy and a
// treasury adapter before anybody has put in a single ugnot. The targets here
// are real and already exist: a validator set, a working group, a hackathon
// team, a five-person company. They want the thing you can create in one
// transaction. [gno.land/p/moul/grants] and daokit are the framework layer, and
// this package is deliberately underneath them: one call to open a crew, one to
// join it, one to leave with what your shares are worth.
//
// # The model
//
//	Crews     every crew, plus the credit ledger every payout goes through
//	Crew      a name, a creation height, members with shares, a treasury, proposals
//	Proposal  advisory text with a deadline and a share-weighted tally
//
// Shares are the whole design. They are the vote weight and the claim on the
// treasury at the same time, minted by [Crews.Join] and burned by
// [Crews.Ragequit], so leaving is priced by the same number that decides. There
// is no separate token to issue, distribute or forget to make meaningful.
//
// # Rounding, which is the part that has to be right
//
// Every division here rounds DOWN, and both of them therefore round in the
// crew's favour:
//
//   - joining mints amount * totalShares / treasury, so a late joiner buys
//     exactly what they paid for at the CURRENT per-share value and never a
//     share more. Rounding up would hand them a sliver of value the existing
//     members built, which is the whole reason a flat price is wrong here.
//   - ragequitting credits shares * treasury / totalShares, so a leaver takes
//     no more than their slice and the remainder stays with the people who
//     stayed.
//
// The dust that accrues from both is never stranded: the last member to
// ragequit holds every outstanding share, so their MulDiv is exact and the
// treasury empties to the last ugnot. [Crews.Ragequit] has a test for that.
//
// # What v0 deliberately does not do
//
// A proposal is advisory text. Passing one executes nothing, moves nothing and
// binds nothing; it records that the crew agreed by share weight at a point in
// time. Executing a payout is the obvious next step and the one that turns this
// into a treasury contract rather than a notice board.
//
// A vote is weighed at the moment it is cast. A member who votes and then
// ragequits leaves their weight behind in the tally, because unwinding it would
// mean re-weighing every ballot on every share change.
//
// # Errors, not aborts
//
// This is a p/, so it returns errors and declares no crossing function: the
// caller, the height and the amount all arrive as plain arguments and the realm
// that wires it to the chain decides what to abort on.
package crew

import (
	"errors"
	"strings"

	"gno.land/p/moul/kit/store/v0"
	"gno.land/p/moul/xmath/v1"
)

const (
	// MaxMembers is the upper end of "three to fifteen people". It is a
	// product constraint and not a technical one: above it the share math
	// still works and the thing stops being a crew.
	MaxMembers = 15

	// InitialPricePerShare is what a share costs in ugnot before the crew
	// has a treasury to price against: at creation, and again if every
	// member has left. 1000 ugnot makes 1 GNOT worth 1000 shares, which
	// keeps the integer arithmetic far away from both zero and overflow.
	InitialPricePerShare = int64(1000)

	// VoteBlocks is how long a proposal stays open, in blocks.
	VoteBlocks = int64(1000)

	// MaxNameLen and MaxTextLen bound what one call can make the crew's
	// members pay a storage deposit on.
	MaxNameLen = 60
	MaxTextLen = 500

	// ExcerptLen is how much of a proposal a listing shows.
	ExcerptLen = 60
)

// maxInt64 is the largest int64, spelled out because the overflow guards
// compare against it directly.
const maxInt64 = int64(9223372036854775807)

// The errors a caller can get back.
var (
	ErrBadName     = errors.New("crew: name is empty, too long, or has control characters")
	ErrBadText     = errors.New("crew: text is empty, too long, or has control characters")
	ErrBadAmount   = errors.New("crew: amount must be positive")
	ErrNoCrew      = errors.New("crew: no such crew")
	ErrNoProposal  = errors.New("crew: no such proposal")
	ErrNotMember   = errors.New("crew: not a member of this crew")
	ErrIsMember    = errors.New("crew: already a member of this crew")
	ErrFull        = errors.New("crew: the crew is full")
	ErrNoShares    = errors.New("crew: the amount sent buys no whole share")
	ErrVoteClosed  = errors.New("crew: the proposal is no longer open")
	ErrVoteOpen    = errors.New("crew: the proposal is still open")
	ErrNothing     = errors.New("crew: nothing to withdraw")
	ErrWouldExceed = errors.New("crew: the amount would overflow the ledger")
)

// Crew is one group: who is in it, what it holds, and what it is deciding.
type Crew struct {
	Name      string
	CreatedAt int64 // block height
	Treasury  int64 // ugnot, accounted here and held at the realm's address

	// TotalShares is every share outstanding. It is the denominator of both
	// the join price and the ragequit payout, so it is maintained here
	// rather than summed over the members on demand.
	TotalShares int64

	shares    map[string]int64 // address -> shares held
	order     []address        // members in join order, so output never iterates a map
	proposals []store.ID
}

// SharesOf is how many shares who holds, zero when they hold none.
func (c *Crew) SharesOf(who address) int64 {
	if c == nil {
		return 0
	}
	return c.shares[who.String()]
}

// IsMember reports whether who holds any share.
func (c *Crew) IsMember(who address) bool { return c.SharesOf(who) > 0 }

// MemberCount is how many addresses hold shares.
func (c *Crew) MemberCount() int {
	if c == nil {
		return 0
	}
	return len(c.order)
}

// Members returns the members in join order. The slice is a copy, so a caller
// rendering it cannot reorder the crew.
func (c *Crew) Members() []address {
	if c == nil {
		return nil
	}
	out := make([]address, len(c.order))
	copy(out, c.order)
	return out
}

// Proposals returns this crew's proposal ids, oldest first, as a copy.
func (c *Crew) Proposals() []store.ID {
	if c == nil {
		return nil
	}
	out := make([]store.ID, len(c.proposals))
	copy(out, c.proposals)
	return out
}

// ValuePerShare is what one share is worth in ugnot right now, rounded down.
//
// It is a display figure and nothing computes against it: [Crews.Join] and
// [Crews.Ragequit] divide by the real totals, so a crew whose treasury is
// smaller than its share count still prices both correctly while this reads 0.
func (c *Crew) ValuePerShare() int64 {
	if c == nil || c.TotalShares == 0 {
		return 0
	}
	return c.Treasury / c.TotalShares
}

// PricePerShare is what the next share costs a joiner, rounded down, which is
// [Crew.ValuePerShare] except on a crew nobody holds a share in.
func (c *Crew) PricePerShare() int64 {
	if c == nil || c.TotalShares == 0 || c.Treasury == 0 {
		return InitialPricePerShare
	}
	return c.Treasury / c.TotalShares
}

// ballot is one member's vote: which way, and what it weighed when cast.
type ballot struct {
	yes    bool
	weight int64
}

// Proposal is a question put to a crew. v0 proposals are advisory text and
// execute nothing: see the package doc.
type Proposal struct {
	CrewID   store.ID
	Author   address
	Text     string
	OpenedAt int64
	Deadline int64 // OpenedAt + VoteBlocks, exclusive

	// Yes and No are the running share-weighted tally, maintained on every
	// vote so reading it never walks the ballots.
	Yes int64
	No  int64

	Closed bool
	Passed bool

	votes map[string]ballot
}

// Open reports whether the proposal still accepts votes at height now.
func (p *Proposal) Open(now int64) bool {
	return p != nil && !p.Closed && now < p.Deadline
}

// VoteOf reports how who voted and what it weighed, and whether they voted at
// all.
func (p *Proposal) VoteOf(who address) (yes bool, weight int64, voted bool) {
	if p == nil {
		return false, 0, false
	}
	b, ok := p.votes[who.String()]
	return b.yes, b.weight, ok
}

// Voters is how many members have cast a ballot.
func (p *Proposal) Voters() int {
	if p == nil {
		return 0
	}
	return len(p.votes)
}

// Crews holds every crew, every proposal, and the credit ledger each payout
// goes through.
type Crews struct {
	crews *store.Store
	props *store.Store

	credit map[string]int64 // address -> ugnot owed
	owed   int64            // the sum of the above, which the holder must reserve
}

// New returns an empty Crews.
func New() *Crews {
	return &Crews{
		crews:  store.Named("crew"),
		props:  store.Named("proposal"),
		credit: map[string]int64{},
	}
}

// Create opens a crew with founder as its only member, their shares bought out
// of amount at [InitialPricePerShare].
//
// The remainder below one whole share stays in the treasury rather than being
// refunded, which is the same direction every other division here rounds.
func (cs *Crews) Create(name string, founder address, amount, at int64) (store.ID, error) {
	if !ValidName(name) {
		return 0, ErrBadName
	}
	if amount <= 0 {
		return 0, ErrBadAmount
	}
	shares := amount / InitialPricePerShare
	if shares < 1 {
		return 0, ErrNoShares
	}
	c := &Crew{
		Name:        name,
		CreatedAt:   at,
		Treasury:    amount,
		TotalShares: shares,
		shares:      map[string]int64{founder.String(): shares},
		order:       []address{founder},
	}
	return cs.crews.Add(c), nil
}

// Join mints who shares at the crew's CURRENT per-share value and adds amount
// to its treasury.
//
// amount * totalShares / treasury, rounded down. That is the whole anti-dilution
// rule: a crew that turned 10 GNOT into 20 sells the next share for what a share
// is worth now, not for what the founders paid, and the rounding remainder stays
// with the crew rather than with the joiner.
func (cs *Crews) Join(id store.ID, who address, amount int64) (int64, error) {
	c, ok := cs.Get(id)
	if !ok {
		return 0, ErrNoCrew
	}
	if amount <= 0 {
		return 0, ErrBadAmount
	}
	if c.IsMember(who) {
		return 0, ErrIsMember
	}
	if len(c.order) >= MaxMembers {
		return 0, ErrFull
	}
	if c.Treasury > maxInt64-amount {
		return 0, ErrWouldExceed
	}

	var shares int64
	if c.TotalShares == 0 || c.Treasury == 0 {
		// Nobody holds a share, so there is no value to price against and
		// the crew is back at its opening price.
		shares = amount / InitialPricePerShare
	} else {
		shares = xmath.MulDiv(amount, c.TotalShares, c.Treasury)
	}
	if shares < 1 {
		return 0, ErrNoShares
	}
	if c.TotalShares > maxInt64-shares {
		return 0, ErrWouldExceed
	}

	c.shares[who.String()] = shares
	c.order = append(c.order, who)
	c.TotalShares += shares
	c.Treasury += amount
	return shares, nil
}

// Fund adds amount to a crew's treasury and mints nothing.
//
// It is what makes the join price mean anything: a crew whose treasury only
// ever moves with its share count prices every joiner identically forever, and
// the anti-dilution rule in [Crews.Join] would be decorative. Revenue, a grant
// and a member topping the pot up all arrive this way, and every existing share
// is worth more afterwards.
func (cs *Crews) Fund(id store.ID, amount int64) error {
	c, ok := cs.Get(id)
	if !ok {
		return ErrNoCrew
	}
	if amount <= 0 {
		return ErrBadAmount
	}
	if c.Treasury > maxInt64-amount {
		return ErrWouldExceed
	}
	c.Treasury += amount
	return nil
}

// Propose opens an advisory question, open for [VoteBlocks] blocks. Any member
// may propose.
func (cs *Crews) Propose(id store.ID, who address, text string, at int64) (store.ID, error) {
	c, ok := cs.Get(id)
	if !ok {
		return 0, ErrNoCrew
	}
	if !c.IsMember(who) {
		return 0, ErrNotMember
	}
	if !ValidText(text) {
		return 0, ErrBadText
	}
	p := &Proposal{
		CrewID:   id,
		Author:   who,
		Text:     text,
		OpenedAt: at,
		Deadline: at + VoteBlocks,
		votes:    map[string]ballot{},
	}
	pid := cs.props.Add(p)
	c.proposals = append(c.proposals, pid)
	return pid, nil
}

// Vote records who's ballot, weighted by the shares they hold right now.
//
// One ballot per member, changeable while the proposal is open: a second call
// replaces the first, tally and weight both, so changing your mind after buying
// more shares counts the shares you now hold.
func (cs *Crews) Vote(pid store.ID, who address, yes bool, at int64) error {
	p, ok := cs.Proposal(pid)
	if !ok {
		return ErrNoProposal
	}
	if !p.Open(at) {
		return ErrVoteClosed
	}
	c, ok := cs.Get(p.CrewID)
	if !ok {
		return ErrNoCrew
	}
	weight := c.SharesOf(who)
	if weight <= 0 {
		return ErrNotMember
	}

	key := who.String()
	if prev, voted := p.votes[key]; voted {
		if prev.yes {
			p.Yes -= prev.weight
		} else {
			p.No -= prev.weight
		}
	}
	p.votes[key] = ballot{yes: yes, weight: weight}
	if yes {
		p.Yes += weight
	} else {
		p.No += weight
	}
	return nil
}

// Close records a proposal as passed or failed by share weight, once its
// deadline has gone by. Anyone may call it: closing is bookkeeping, not
// authority, and a proposal nobody closes is simply never recorded.
//
// A tie fails. There is no quorum in v0: a crew where one member votes and the
// rest ignore it passes the proposal, which is exactly as advisory as the text
// it carries.
func (cs *Crews) Close(pid store.ID, at int64) (bool, error) {
	p, ok := cs.Proposal(pid)
	if !ok {
		return false, ErrNoProposal
	}
	if p.Closed {
		return p.Passed, ErrVoteClosed
	}
	if at < p.Deadline {
		return false, ErrVoteOpen
	}
	p.Closed = true
	p.Passed = p.Yes > p.No
	return p.Passed, nil
}

// Ragequit burns every share who holds, credits them their pro-rata slice of
// the treasury and removes them from the crew.
//
// shares * treasury / totalShares, rounded down, so the remainder stays with
// the members who stayed. This is what makes a share mean something: the exit
// is priced by the same number that votes, and nobody has to agree to let you
// out.
//
// The payout is credited, never sent. The caller moves the coins after this
// returns, which is the ordering the pull-payment pattern exists for.
func (cs *Crews) Ragequit(id store.ID, who address) (shares, amount int64, err error) {
	c, ok := cs.Get(id)
	if !ok {
		return 0, 0, ErrNoCrew
	}
	shares = c.SharesOf(who)
	if shares <= 0 {
		return 0, 0, ErrNotMember
	}

	amount = xmath.MulDiv(shares, c.Treasury, c.TotalShares)
	c.TotalShares -= shares
	c.Treasury -= amount
	delete(c.shares, who.String())
	c.order = dropAddress(c.order, who)

	if amount > 0 {
		if err := cs.credits(who, amount); err != nil {
			return 0, 0, err
		}
	}
	return shares, amount, nil
}

// credits adds to an address's withdrawable balance.
func (cs *Crews) credits(who address, amount int64) error {
	key := who.String()
	if cs.credit[key] > maxInt64-amount || cs.owed > maxInt64-amount {
		return ErrWouldExceed
	}
	cs.credit[key] += amount
	cs.owed += amount
	return nil
}

// Withdraw zeroes who's credit and returns what they were owed.
//
// The balance is gone from the ledger before this returns, so the caller can
// move the coins afterwards and a reentrant call finds nothing: effects, then
// interactions.
func (cs *Crews) Withdraw(who address) (int64, error) {
	key := who.String()
	amount, ok := cs.credit[key]
	if !ok || amount == 0 {
		return 0, ErrNothing
	}
	delete(cs.credit, key)
	cs.owed -= amount
	return amount, nil
}

// CreditOf is what who can withdraw right now.
func (cs *Crews) CreditOf(who address) int64 { return cs.credit[who.String()] }

// TotalOwed is the sum of every outstanding credit, which is what the holding
// realm must keep in reserve on top of every crew's treasury.
func (cs *Crews) TotalOwed() int64 { return cs.owed }

// Get returns a crew by id.
func (cs *Crews) Get(id store.ID) (*Crew, bool) {
	v, ok := cs.crews.Get(id)
	if !ok {
		return nil, false
	}
	return v.(*Crew), true
}

// Proposal returns a proposal by id.
func (cs *Crews) Proposal(pid store.ID) (*Proposal, bool) {
	v, ok := cs.props.Get(pid)
	if !ok {
		return nil, false
	}
	return v.(*Proposal), true
}

// Len is how many crews exist.
func (cs *Crews) Len() int { return cs.crews.Len() }

// ProposalCount is how many proposals exist, across every crew.
func (cs *Crews) ProposalCount() int { return cs.props.Len() }

// Listing is one row of [Crews.List]: the crew and the id a link needs.
type Listing struct {
	ID   store.ID
	Crew *Crew
}

// List returns up to limit crews, newest first. limit below 1 returns nothing.
func (cs *Crews) List(limit int) []Listing {
	var out []Listing
	for _, e := range cs.crews.PageReverse(1, limit) {
		out = append(out, Listing{ID: e.ID, Crew: e.Value.(*Crew)})
	}
	return out
}

// ValidName reports whether name can be stored: non-empty after trimming,
// within [MaxNameLen], free of control characters including newlines, and
// free of the pipe character.
//
// The pipe is the one restriction that is not obvious, and it is here because
// a name is rendered as the TITLE of a link inside a table cell. md.Link
// escapes its title with the inline-text escaper, which deliberately leaves
// "|" alone because a pipe is markdown-inert outside a table, and wrapping the
// title in ui.Cell on top of that would double-escape and render the
// backslashes. Refusing the character at write time is the only place left
// where the fix is one rule rather than one exception per call site.
//
// A proposal's text has no such restriction: [ValidText] allows a pipe and the
// render escapes it with ui.Cell, because free prose legitimately contains one
// and a name does not.
func ValidName(name string) bool {
	if len(name) > MaxNameLen || strings.TrimSpace(name) == "" {
		return false
	}
	for i := 0; i < len(name); i++ {
		c := name[i]
		if c < 0x20 || c == 0x7f || c == '|' {
			return false
		}
	}
	return true
}

// ValidText reports whether a proposal body can be stored: non-empty after
// trimming, within [MaxTextLen], and free of control characters other than
// newline and tab.
//
// Control characters are refused rather than stripped because the text is shown
// back to its author, and silently rewriting what somebody wrote is worse than
// telling them it was refused. Everything else is allowed and escaped at render
// time: a validator and an escaper protect against different mistakes.
func ValidText(text string) bool {
	if len(text) > MaxTextLen || strings.TrimSpace(text) == "" {
		return false
	}
	for i := 0; i < len(text); i++ {
		c := text[i]
		if c < 0x20 && c != '\n' && c != '\t' || c == 0x7f {
			return false
		}
	}
	return true
}

// dropAddress returns addrs without who, in a freshly allocated slice.
//
// It allocates rather than shortening in place: a slice is one persisted object
// and the storage deposit only comes back when that object is dropped, so
// append(s[:i], s[i+1:]...) would keep the peak allocation charged forever.
func dropAddress(addrs []address, who address) []address {
	out := make([]address, 0, len(addrs))
	for _, a := range addrs {
		if a != who {
			out = append(out, a)
		}
	}
	return out
}

// Package curated is the engine behind a curated list where being on the list
// costs something: anyone may list an entry by locking a deposit, anyone may
// challenge an entry by matching that deposit with a bond, and the loser of the
// challenge pays the winner.
//
// # Why a deposit
//
// A list anybody can write to for free is a list nobody can read, because the
// cheapest way to be on it is to be on it a thousand times. A deposit does not
// make an entry good; it makes a bad entry expensive to leave standing, because
// somebody who disagrees can put the same amount at risk and take yours. The
// list is worth reading in proportion to what it would cost to pollute it.
//
// # The model
//
//	Registry  every entry, plus the credit ledger the payouts land in
//	Entry     a key, a URL, a description, an owner, the deposit, the height
//	          it was listed at, and one of three states
//	Challenge a challenger, a matching bond, a deadline, and the votes
//
// A key is unique while it is on the list ([ValidKey] bounds it to a
// slug), and a removed key is free again: a challenge that wins removes an
// entry, it does not burn the name forever.
//
// # The money, and why nothing is ever sent from here
//
// This package moves no coins. Every payout is a credit in an internal ledger
// that the payee collects with [Registry.Withdraw], which is the pull-payment
// shape: a realm that loops over winners and sends to each one fails entirely
// when one of them cannot be paid, and hands a griefer a cheap denial of
// service. [Registry.Locked] plus [Registry.Owed] is what the holding realm
// must have at its address, and a realm can assert exactly that.
//
// # Voting is sybil-prone, deliberately and visibly
//
// [Registry.Vote] is one address, one vote, unweighted. An address is free, so
// a challenge outcome is a poll of whoever bothered to make keys, not of
// anybody in particular. That is not a gap this package can close: deciding who
// counts as a person is a different problem with a different realm behind it,
// r/moul/x/social/vouch, a sibling in this family. Until a vote is
// gated on a vouched identity, read a resolution as "nobody with a stake
// objected enough", not as a verdict.
//
// # What v0 does not do, in the order it should be fixed
//
//  1. Voters are paid nothing. Voting costs gas and returns nothing, so the
//     only addresses with a reason to vote are the two with money on the
//     outcome. A share of the loser's stake for the winning side is the
//     standard answer and it is the first thing to add.
//  2. There is no application period: [Registry.Apply] lists immediately, so a
//     bad entry is visible until somebody challenges it.
//  3. A challenge cannot be withdrawn, and a vote cannot be changed.
package curated

import (
	"errors"
	"strings"
)

const (
	// MaxKeyLen is the longest key accepted. A key is a name people type and
	// link to, not a payload.
	MaxKeyLen = 64

	// MaxURLLen and MaxDescLen bound what one entry can lock up of somebody
	// else's storage deposit.
	MaxURLLen  = 240
	MaxDescLen = 240

	// MaxEntries bounds the registry so a listing stays predictable in gas.
	MaxEntries = 4096

	// MaxPayees bounds the credit ledger for the same reason.
	MaxPayees = 4096
)

const maxInt64 = int64(9223372036854775807)

// The errors a caller can get back. A p/ returns them; the realm decides to
// abort.
var (
	ErrBadKey         = errors.New("curated: not a key: 1 to 64 bytes of a-z 0-9 - _ . starting alphanumeric")
	ErrBadURL         = errors.New("curated: url is empty, too long, or has a space or a control character")
	ErrBadDescription = errors.New("curated: description is empty, too long, or not a single line")
	ErrTaken          = errors.New("curated: that key is already on the list")
	ErrNoEntry        = errors.New("curated: no such entry")
	ErrWrongDeposit   = errors.New("curated: the deposit must be paid exactly")
	ErrWrongBond      = errors.New("curated: the bond must match the entry's deposit")
	ErrChallenged     = errors.New("curated: that entry is under challenge")
	ErrSelfChallenge  = errors.New("curated: an owner cannot challenge their own entry")
	ErrNoChallenge    = errors.New("curated: that entry is not under challenge")
	ErrVotingClosed   = errors.New("curated: the challenge deadline has passed")
	ErrAlreadyVoted   = errors.New("curated: one address, one vote")
	ErrTooEarly       = errors.New("curated: the challenge is still open")
	ErrNotOwner       = errors.New("curated: only the entry's owner can do that")
	ErrNothingOwed    = errors.New("curated: nothing to withdraw")
	ErrFull           = errors.New("curated: the registry is full")
	ErrOverflow       = errors.New("curated: the credit would overflow")
	ErrBadAmount      = errors.New("curated: amount must be positive")
)

// State is where an entry stands.
type State uint8

const (
	// StateListed is on the list and unchallenged.
	StateListed State = iota

	// StateChallenged is on the list with a challenge open against it. It
	// still renders: a challenge is an objection, not a verdict.
	StateChallenged

	// StateRemoved is off the list, either lost to a challenge or taken down
	// by its own owner. The key is free for anyone to apply for again.
	StateRemoved
)

// String names the state for a reader and for an event.
func (s State) String() string {
	switch s {
	case StateListed:
		return "listed"
	case StateChallenged:
		return "challenged"
	case StateRemoved:
		return "removed"
	default:
		return "unknown"
	}
}

// Challenge is an open objection to one entry.
type Challenge struct {
	Challenger address
	Bond       int64
	Deadline   int64 // block height the voting stops at, exclusive

	// Keep and Remove are the unweighted vote counts. See the package doc on
	// what they are and are not worth.
	Keep   int64
	Remove int64

	// voters is the set of addresses that have voted, so one address votes
	// once. It is unexported: a caller reads [Challenge.Voters].
	voters map[string]bool
}

// Voters is how many distinct addresses have voted.
func (c *Challenge) Voters() int {
	if c == nil {
		return 0
	}
	return len(c.voters)
}

// HasVoted reports whether who has already voted in this challenge.
func (c *Challenge) HasVoted(who address) bool {
	if c == nil {
		return false
	}
	return c.voters[who.String()]
}

// Open reports whether votes are still being taken at height now.
func (c *Challenge) Open(now int64) bool { return c != nil && now < c.Deadline }

// Entry is one row of the list.
type Entry struct {
	Key         string
	URL         string
	Description string
	Owner       address
	Deposit     int64 // what the owner locked to list it
	At          int64 // the block height it was listed at
	State       State

	// challenge is the open objection, or nil. It is cleared on resolution:
	// the outcome is in the entry's state and in the ledger, and keeping a
	// resolved challenge would be a second place to read it from.
	challenge *Challenge
}

// Live reports whether the entry is on the list, challenged or not.
func (e *Entry) Live() bool { return e != nil && e.State != StateRemoved }

// Registry is the whole list: the entries, and the credits waiting to be
// withdrawn.
type Registry struct {
	deposit         int64
	challengeBlocks int64

	entries map[string]*Entry
	order   []string // keys in the order they were first listed

	credits map[string]int64
	owed    int64
	locked  int64
}

// New returns an empty registry where listing costs deposit and a challenge
// runs for challengeBlocks blocks.
//
// Both are fixed for the life of the registry. An entry remembers the deposit
// it actually paid, so a future registry that can reprice itself still charges
// a challenger what the owner of that entry risked, and not today's number.
func New(deposit, challengeBlocks int64) *Registry {
	return &Registry{
		deposit:         deposit,
		challengeBlocks: challengeBlocks,
		entries:         map[string]*Entry{},
		credits:         map[string]int64{},
	}
}

// Deposit is what listing costs.
func (r *Registry) Deposit() int64 { return r.deposit }

// ChallengeBlocks is how long a challenge takes to resolve.
func (r *Registry) ChallengeBlocks() int64 { return r.challengeBlocks }

// Apply lists an entry immediately, in exchange for exactly the deposit.
//
// There is no application period in v0: the entry is on the list the moment the
// deposit is paid, and the check on it is that anybody can challenge it.
//
// A key whose entry was removed is free again, and applying for it writes a
// fresh entry in the same position in the listing order.
func (r *Registry) Apply(key, url, description string, owner address, paid, now int64) error {
	if !ValidKey(key) {
		return ErrBadKey
	}
	if !ValidURL(url) {
		return ErrBadURL
	}
	if !ValidDescription(description) {
		return ErrBadDescription
	}
	if paid != r.deposit {
		return ErrWrongDeposit
	}
	old, seen := r.entries[key]
	if seen && old.Live() {
		return ErrTaken
	}
	if !seen {
		if len(r.order) >= MaxEntries {
			return ErrFull
		}
		r.order = append(r.order, key)
	}
	r.entries[key] = &Entry{
		Key:         key,
		URL:         url,
		Description: description,
		Owner:       owner,
		Deposit:     paid,
		At:          now,
		State:       StateListed,
	}
	r.locked += paid
	return nil
}

// BondFor is what challenging key would cost, and whether it can be challenged
// at all.
//
// The realm reads this BEFORE it reads the envelope, so a caller who attaches
// coins to a challenge of something unchallengeable is refused on the entry and
// not on the amount.
func (r *Registry) BondFor(key string) (int64, bool) {
	e, ok := r.entries[key]
	if !ok || e.State != StateListed {
		return 0, false
	}
	return e.Deposit, true
}

// Challenge opens an objection to an entry, against a bond equal to that
// entry's deposit, and sets the deadline at now + ChallengeBlocks.
//
// An owner may not challenge their own entry. It would cost nothing (a kept
// entry credits its owner the bond, which here is their own) and it would make
// the entry immune to a real challenge for the whole window.
func (r *Registry) Challenge(key string, challenger address, bond, now int64) error {
	e, ok := r.entries[key]
	if !ok || !e.Live() {
		return ErrNoEntry
	}
	if e.State == StateChallenged {
		return ErrChallenged
	}
	if challenger == e.Owner {
		return ErrSelfChallenge
	}
	if bond != e.Deposit {
		return ErrWrongBond
	}
	e.State = StateChallenged
	e.challenge = &Challenge{
		Challenger: challenger,
		Bond:       bond,
		Deadline:   now + r.challengeBlocks,
		voters:     map[string]bool{},
	}
	r.locked += bond
	return nil
}

// Vote records one address's opinion on an open challenge: keep the entry, or
// remove it.
//
// One address, one vote, unweighted, and it cannot be changed. Anyone may vote,
// including the owner and the challenger, because excluding them would only
// move their vote to another address they control. See the package doc: this is
// sybil-prone on purpose rather than by oversight, and gating it is the job of
// the vouch realm.
func (r *Registry) Vote(key string, voter address, keep bool, now int64) error {
	e, ok := r.entries[key]
	if !ok {
		return ErrNoEntry
	}
	c := e.challenge
	if e.State != StateChallenged || c == nil {
		return ErrNoChallenge
	}
	if !c.Open(now) {
		return ErrVotingClosed
	}
	k := voter.String()
	if c.voters[k] {
		return ErrAlreadyVoted
	}
	c.voters[k] = true
	if keep {
		c.Keep++
	} else {
		c.Remove++
	}
	return nil
}

// Outcome is what a resolution decided and who it paid.
type Outcome struct {
	Key    string
	Kept   bool
	Winner address
	Amount int64 // credited to the winner
	Keep   int64
	Remove int64
}

// Resolve closes a challenge whose deadline has passed. Anyone may call it: the
// two parties both have a reason to and neither can stall the other.
//
// A majority of keep votes keeps the entry and credits its owner the
// challenger's bond. Otherwise the entry is removed and the challenger is
// credited the bond plus the deposit.
//
// A TIE KEEPS THE ENTRY, including the tie of nobody voting at all. The
// incumbent paid first and is already at risk, so the burden is on the
// challenger to produce a reason; if ties went the other way, a challenge that
// convinced nobody would still win, and listing anything would be pointless.
// The cost of that choice is the one a challenger signs up for: being wrong
// costs the bond.
func (r *Registry) Resolve(key string, now int64) (Outcome, error) {
	e, ok := r.entries[key]
	if !ok {
		return Outcome{}, ErrNoEntry
	}
	c := e.challenge
	if e.State != StateChallenged || c == nil {
		return Outcome{}, ErrNoChallenge
	}
	if c.Open(now) {
		return Outcome{}, ErrTooEarly
	}

	out := Outcome{Key: key, Kept: c.Keep >= c.Remove, Keep: c.Keep, Remove: c.Remove}
	if out.Kept {
		out.Winner, out.Amount = e.Owner, c.Bond
	} else {
		out.Winner, out.Amount = c.Challenger, c.Bond+e.Deposit
	}

	// Credit first: it is the only step that can fail, and a half-applied
	// resolution would leave an entry with no challenge and nobody paid.
	if err := r.credit(out.Winner, out.Amount); err != nil {
		return Outcome{}, err
	}
	if out.Kept {
		e.State = StateListed
		r.locked -= c.Bond
	} else {
		e.State = StateRemoved
		r.locked -= c.Bond + e.Deposit
	}
	e.challenge = nil
	return out, nil
}

// Unlist takes an owner's own entry down and credits them the deposit back.
//
// It is refused while a challenge is open, which is the whole point of the
// bond: an owner who could walk away mid-challenge would be risking nothing.
func (r *Registry) Unlist(key string, owner address) error {
	e, ok := r.entries[key]
	if !ok || !e.Live() {
		return ErrNoEntry
	}
	if e.Owner != owner {
		return ErrNotOwner
	}
	if e.State == StateChallenged {
		return ErrChallenged
	}
	if err := r.credit(owner, e.Deposit); err != nil {
		return err
	}
	e.State = StateRemoved
	r.locked -= e.Deposit
	return nil
}

// Withdraw zeroes who's credit and returns what they were owed.
//
// The holding realm sends the coins AFTER this returns. That ordering is the
// pattern: the credit is already gone from the ledger when control passes to
// the recipient, so a reentrant withdrawal finds ErrNothingOwed.
func (r *Registry) Withdraw(who address) (int64, error) {
	k := who.String()
	amount := r.credits[k]
	if amount <= 0 {
		return 0, ErrNothingOwed
	}
	delete(r.credits, k) // effects before interactions
	r.owed -= amount
	return amount, nil
}

// credit records that who is owed amount more.
func (r *Registry) credit(who address, amount int64) error {
	if amount <= 0 {
		return ErrBadAmount
	}
	k := who.String()
	have, seen := r.credits[k]
	if !seen && len(r.credits) >= MaxPayees {
		return ErrFull
	}
	if have > maxInt64-amount || r.owed > maxInt64-amount {
		return ErrOverflow
	}
	r.credits[k] = have + amount
	r.owed += amount
	return nil
}

// Get returns an entry by key, whatever its state, and whether it ever existed.
func (r *Registry) Get(key string) (*Entry, bool) {
	e, ok := r.entries[key]
	return e, ok
}

// IsListed reports whether key is on the list right now. A challenged entry is
// still listed.
func (r *Registry) IsListed(key string) bool {
	e, ok := r.entries[key]
	return ok && e.Live()
}

// Count is how many entries are on the list right now.
func (r *Registry) Count() int {
	n := 0
	for _, key := range r.order {
		if r.entries[key].Live() {
			n++
		}
	}
	return n
}

// Records is how many keys the registry has ever held, removed ones included.
func (r *Registry) Records() int { return len(r.order) }

// Listed returns every entry on the list, oldest first.
//
// The order comes from a slice and not from iterating the map, so it is a
// stable sequence a Render can be pinned against rather than an insertion order
// that a delete-and-re-add would reshuffle.
func (r *Registry) Listed() []*Entry {
	out := []*Entry{}
	for _, key := range r.order {
		if e := r.entries[key]; e.Live() {
			out = append(out, e)
		}
	}
	return out
}

// Challenged returns every entry with a challenge open against it, oldest
// listing first.
func (r *Registry) Challenged() []*Entry {
	out := []*Entry{}
	for _, key := range r.order {
		if e := r.entries[key]; e.State == StateChallenged {
			out = append(out, e)
		}
	}
	return out
}

// ChallengeOf returns the open challenge against key, if there is one.
func (r *Registry) ChallengeOf(key string) (*Challenge, bool) {
	e, ok := r.entries[key]
	if !ok || e.challenge == nil {
		return nil, false
	}
	return e.challenge, true
}

// CreditOf is what who can withdraw right now.
func (r *Registry) CreditOf(who address) int64 { return r.credits[who.String()] }

// Owed is every credit not yet withdrawn.
func (r *Registry) Owed() int64 { return r.owed }

// Locked is the deposits behind live entries plus the bonds behind open
// challenges.
//
// Locked plus [Registry.Owed] is what the holding realm must have at its
// address: every ugnot it ever took is either still backing something or
// already assigned to somebody. A realm can assert that equality against its
// own balance, and this package's tests do.
func (r *Registry) Locked() int64 { return r.locked }

// ValidKey reports whether key is usable: 1 to [MaxKeyLen] bytes of lowercase
// ASCII letters, digits, '-', '_' and '.', starting with a letter or a digit.
//
// The leading-alphanumeric rule is what stops "." and "..", and what stops a
// key that reads as punctuation in the list it is shown in. The charset is
// narrow so a key can be typed, linked and compared without surprises; it is
// still escaped at render time, because a validator and an escaper protect
// against different mistakes.
func ValidKey(key string) bool {
	if key == "" || len(key) > MaxKeyLen {
		return false
	}
	if c := key[0]; !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9') {
		return false
	}
	for i := 0; i < len(key); i++ {
		c := key[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9':
		case c == '-' || c == '_' || c == '.':
		default:
			return false
		}
	}
	return true
}

// ValidURL reports whether url can be stored: non-empty, within [MaxURLLen],
// and free of spaces and control characters.
//
// No scheme is required, because a list of on-chain things is the obvious use
// and those have no host. A renderer treats a schemeless URL as a path
// relative to the chain's web root, so an on-chain target is written
// "/r/moul/home" and an off-chain one carries its own "https://".
//
// Nothing here checks that the target exists: a deposit backs the claim that
// the entry is worth listing, not the claim that it resolves.
func ValidURL(url string) bool {
	if url == "" || len(url) > MaxURLLen {
		return false
	}
	for i := 0; i < len(url); i++ {
		if c := url[i]; c <= 0x20 || c == 0x7f {
			return false
		}
	}
	return true
}

// ValidDescription reports whether description can be stored: non-empty after
// trimming, within [MaxDescLen], and a single line.
//
// Newlines and tabs are refused rather than stripped, because a description is
// shown back to the person who wrote it and silently rewriting it is worse than
// telling them it was refused. It lives in a table cell, which a newline would
// break out of and an escaper would then have to repair.
func ValidDescription(description string) bool {
	if len(description) > MaxDescLen || strings.TrimSpace(description) == "" {
		return false
	}
	for i := 0; i < len(description); i++ {
		if c := description[i]; c < 0x20 || c == 0x7f {
			return false
		}
	}
	return true
}

// Package patron is the engine behind recurring support for a builder: a plan
// somebody subscribes to, period after period, paid in ugnot on chain.
//
// # There is no cron on chain, so a renewal is a pull and not a push
//
// Nothing here can charge anybody. The supporter sends another payment and
// their paid-through height moves forward; there is no scheduler, no keeper,
// and no standing authority over anybody's balance. There is no way to write
// one either, because a native coin cannot be pulled at all: a banker may only
// spend its own realm's address, so the inbound path is always the holder
// signing. A reader arriving from web2 expects the opposite, and that is the
// one expectation to unlearn before reading the rest of this package.
//
// # What this adds over a tip jar
//
// A tip jar is one payment and then nothing, and the one-shot version is
// already live at gno.land/r/moul/x/daily/tipjar. The recurrence is the only
// reason this exists: a plan carries a price per period and a period measured
// in BLOCKS, a supporter buys whole periods, and anybody can ask at any height
// whether a given address is still active. It is the one piece of the x/social
// family that produces a recurring write rather than a one-off.
//
// # The model
//
//	Registry  every plan, plus the credit ledger money leaves through
//	Plan      a creator, a title, a description, a price, a period, open or not
//	Payment   what one Subscribe call bought: periods, spent, change, through
//
// # Renewing early never loses time already paid for
//
// [Registry.Subscribe] extends from whichever is LATER, now or the supporter's
// current paid-through height. Renewing two blocks before a lapse adds a whole
// period on top of what is left. Renewing after a lapse starts from now,
// because the gap was never paid for and nothing backdates it.
//
// # The change is credited back, never kept
//
// A payment buys floor(sent / price) whole periods, and the remainder under
// one period is credited to the SUPPORTER's own withdrawable balance. Keeping
// it would be a fee nobody agreed to, and a silent fee is the thing a
// subscription realm must not have. The supporter takes it back through the
// same [Registry.Withdraw] a creator uses.
//
// # Earnings are credited at the moment of payment, not streamed
//
// The creator can withdraw the whole price the instant it is paid. A supporter
// who stops being active is therefore NOT refunded, and no part of a paid
// period is ever returned. That is a real limitation and it is v0 on purpose:
// escrowed streaming, where the creator claims only what has elapsed and the
// supporter can cancel and reclaim the rest, needs a claim schedule and a
// refund path, which is a bigger realm than this one. It is the v1, and it is
// not a line that can be bolted onto this one.
//
// # Money leaves by pull, never by a push loop
//
// Nothing here moves coins. [Registry.Subscribe] credits a
// gno.land/p/moul/x/daily/pullpayment ledger, and [Registry.Withdraw] zeroes a
// credit and reports what was owed so the holding realm can transfer after
// that call, with the balance already gone when control leaves. A realm that
// looped over payees instead would fail entirely on one unpayable address and
// hand a griefer a cheap denial of service.
//
// # A title and a description are attacker-controlled markdown
//
// Both are free text. [ValidTitle] and [ValidDescription] bound them and
// refuse control characters, which is a different protection from escaping and
// not a substitute for it: a realm that renders either one escapes it with
// ui.Inline in prose or ui.Cell in a table cell.
package patron

import (
	"errors"
	"strings"

	"gno.land/p/moul/kit/store/v0"
	"gno.land/p/moul/x/daily/pullpayment/v0"
	"gno.land/p/moul/xmath/v1"
)

const (
	// MaxTitleLen and MaxDescriptionLen bound the two free-text fields. Long
	// enough to say what the plan is, short enough that opening one cannot
	// lock an unbounded storage deposit somebody else is paying for.
	MaxTitleLen       = 80
	MaxDescriptionLen = 500

	// MinPeriodBlocks and MaxPeriodBlocks bound a period both ways. A period
	// of zero blocks is not a subscription, it is a division by zero wearing
	// a price tag. The ceiling is about a year at the five second blocks the
	// test chain runs, past which "recurring" stops meaning anything and the
	// plan is a one-off with extra steps.
	MinPeriodBlocks = int64(10)
	MaxPeriodBlocks = int64(6307200)

	// MinPricePerPeriod is one ugnot, because a free plan is a tip jar
	// (gno.land/r/moul/x/daily/tipjar) and not a subscription: at a price of
	// zero there is nothing to buy a period with and every address would be
	// active forever.
	MinPricePerPeriod = int64(1)

	// MaxPeriodsPerPayment bounds what one payment may buy. It keeps
	// periods * PeriodBlocks inside an int64 by construction rather than by
	// hope, and it stops a single send from parking a paid-through height so
	// far ahead that no later arithmetic on it means anything.
	MaxPeriodsPerPayment = int64(10000)
)

// The errors a caller can get back. A p/ package returns them and the realm
// decides to abort.
var (
	ErrBadTitle          = errors.New("patron: title is empty, too long, or has control characters")
	ErrBadDescription    = errors.New("patron: description is too long or has control characters")
	ErrBadPrice          = errors.New("patron: a plan needs a price of at least one ugnot per period")
	ErrBadPeriod         = errors.New("patron: period out of range")
	ErrNoPlan            = errors.New("patron: no such plan")
	ErrPlanClosed        = errors.New("patron: this plan is closed to new subscriptions")
	ErrNotCreator        = errors.New("patron: only the plan's creator can do that")
	ErrAlreadyOpen       = errors.New("patron: the plan is already open")
	ErrAlreadyClosed     = errors.New("patron: the plan is already closed")
	ErrShortOfOnePeriod  = errors.New("patron: the payment does not cover one whole period")
	ErrTooManyPeriods    = errors.New("patron: one payment cannot buy that many periods")
	ErrNothingToWithdraw = errors.New("patron: nothing to withdraw")
)

// Plan is one creator's recurring support plan.
type Plan struct {
	Creator     address
	Title       string
	Description string

	// PricePerPeriod is what one period costs, in ugnot.
	PricePerPeriod int64

	// PeriodBlocks is how long a period lasts, in blocks. Blocks and not
	// seconds: height is the clock consensus agrees on, and a block timestamp
	// is set by proposers and is not something to build a billing cliff out
	// of at second resolution.
	PeriodBlocks int64

	// Open reports whether the plan takes NEW payments. Closing it never
	// touches a subscription already paid for, which runs to its own
	// paid-through height.
	Open bool

	// Received is the lifetime ugnot this plan credited to its creator.
	Received int64

	// paidThrough is the first height at which a supporter is no longer
	// active. A supporter is active while now < paidThrough, so a period
	// bought at height h ends at h+PeriodBlocks and the holder is inactive
	// at exactly that height.
	paidThrough map[string]int64

	// supporters is every address that has ever paid, in first-payment
	// order. It exists so a listing is deterministic without iterating a map
	// as if insertion order were a sort.
	supporters []address
}

// PaidThrough is the height who stops being active at, or zero if they never
// paid.
func (p *Plan) PaidThrough(who address) int64 {
	if p == nil {
		return 0
	}
	return p.paidThrough[who.String()]
}

// IsActive reports whether who is paid up at height now.
//
// The comparison is strict: a supporter paid through height h is active at
// h-1 and not at h. One rule, applied at both edges, so a period never
// overlaps the next one by a block.
func (p *Plan) IsActive(who address, now int64) bool {
	return p.PaidThrough(who) > now
}

// SupporterCount is how many distinct addresses have ever paid, active or not.
func (p *Plan) SupporterCount() int {
	if p == nil {
		return 0
	}
	return len(p.supporters)
}

// Supporters is every address that has ever paid, in first-payment order.
//
// It returns a copy. Handing out the stored slice would be a live mutation
// handle on realm state, which is the cheapest way for a reader to become a
// writer.
func (p *Plan) Supporters() []address {
	if p == nil {
		return nil
	}
	out := make([]address, len(p.supporters))
	copy(out, p.supporters)
	return out
}

// ActiveCount is how many supporters are paid up at height now.
func (p *Plan) ActiveCount(now int64) int {
	if p == nil {
		return 0
	}
	n := 0
	for _, who := range p.supporters {
		if p.IsActive(who, now) {
			n++
		}
	}
	return n
}

// Payment is what one [Registry.Subscribe] call bought.
type Payment struct {
	// Periods is how many whole periods the payment covered.
	Periods int64

	// Spent is the ugnot those periods cost, credited to the creator.
	Spent int64

	// Change is the remainder under one period, credited back to the
	// supporter rather than kept.
	Change int64

	// PaidThrough is the supporter's new paid-through height.
	PaidThrough int64

	// NewSupporter reports whether this address had never paid this plan
	// before, which is the signal a realm wants for an event or a counter.
	NewSupporter bool
}

// Registry holds every plan and the credit ledger money leaves through.
type Registry struct {
	plans  *store.Store
	ledger *pullpayment.Ledger

	// earned is lifetime ugnot credited per creator, which survives a
	// withdrawal. The ledger only knows what is owed RIGHT NOW, and a page
	// showing a creator zero the moment they cash out would be telling the
	// truth about the wrong question.
	earned map[string]int64
}

// NewRegistry returns an empty registry.
func NewRegistry() *Registry {
	return &Registry{
		plans:  store.Named("plan"),
		ledger: pullpayment.New(),
		earned: map[string]int64{},
	}
}

// Open creates a plan and returns its id. Anyone may open one.
func (r *Registry) Open(creator address, title, description string, pricePerPeriod, periodBlocks int64) (store.ID, error) {
	if !ValidTitle(title) {
		return 0, ErrBadTitle
	}
	if !ValidDescription(description) {
		return 0, ErrBadDescription
	}
	if pricePerPeriod < MinPricePerPeriod {
		return 0, ErrBadPrice
	}
	if periodBlocks < MinPeriodBlocks || periodBlocks > MaxPeriodBlocks {
		return 0, ErrBadPeriod
	}
	return r.plans.Add(&Plan{
		Creator:        creator,
		Title:          title,
		Description:    description,
		PricePerPeriod: pricePerPeriod,
		PeriodBlocks:   periodBlocks,
		Open:           true,
		paidThrough:    map[string]int64{},
	}), nil
}

// Subscribe buys whole periods on a plan with sent ugnot, at height now.
//
// It refuses anything short of one period, buys floor(sent / price) of them,
// and credits the remainder back to the supporter. The extension starts from
// whichever is LATER, now or the supporter's current paid-through height, so
// renewing early never discards time already paid for and renewing after a
// lapse never backdates the gap.
//
// The creator is credited at the moment of payment, not as the periods
// elapse. See the package doc for why that is v0 and what v1 would have to
// carry instead.
func (r *Registry) Subscribe(id store.ID, who address, sent, now int64) (Payment, error) {
	p, ok := r.Get(id)
	if !ok {
		return Payment{}, ErrNoPlan
	}
	if !p.Open {
		return Payment{}, ErrPlanClosed
	}
	if sent < p.PricePerPeriod {
		return Payment{}, ErrShortOfOnePeriod
	}

	// The one rounding decision in this function: periods is floor, so a
	// supporter is never sold a period they did not fully fund, and the
	// remainder is handed back below rather than kept. Neither side keeps a
	// fraction of a period.
	periods := sent / p.PricePerPeriod
	if periods > MaxPeriodsPerPayment {
		return Payment{}, ErrTooManyPeriods
	}
	spent := sent - sent%p.PricePerPeriod
	change := sent - spent

	// spent is an exact whole number of periods, so this division leaves no
	// remainder and there is no second rounding direction to choose. MulDiv
	// is here for the intermediate: spent * PeriodBlocks overflows an int64
	// for a plan priced in whole GNOT with a period measured in months, and
	// the naive product wraps to a plausible-looking height rather than to an
	// obvious one. MulDivUp would be identical on an exact division; MulDiv
	// says plainly that nothing is being rounded up.
	added := xmath.MulDiv(spent, p.PeriodBlocks, p.PricePerPeriod)

	from := now
	if pt := p.PaidThrough(who); pt > from {
		from = pt
	}
	through := from + added

	key := who.String()

	// Both credits happen before the plan is touched, and both can fail: the
	// ledger is bounded and guards its own overflow. A realm calling this
	// aborts on the error, which reverts everything written in the same
	// frame, so a half-applied subscription is not reachable from a crossing
	// call. The ordering is what makes that true for every other caller too.
	if err := r.ledger.Credit(p.Creator.String(), spent); err != nil {
		return Payment{}, err
	}
	if change > 0 {
		if err := r.ledger.Credit(key, change); err != nil {
			return Payment{}, err
		}
	}
	r.earned[p.Creator.String()] += spent

	_, seen := p.paidThrough[key]
	if !seen {
		p.supporters = append(p.supporters, who)
	}
	p.paidThrough[key] = through
	p.Received += spent

	return Payment{
		Periods:      periods,
		Spent:        spent,
		Change:       change,
		PaidThrough:  through,
		NewSupporter: !seen,
	}, nil
}

// Close stops a plan taking new subscriptions. Creator only.
//
// It does not touch anything already paid for: existing supporters run to
// their own paid-through height, which is the only behaviour that does not
// turn closing a plan into taking money back.
func (r *Registry) Close(id store.ID, who address) error {
	p, err := r.ownPlan(id, who)
	if err != nil {
		return err
	}
	if !p.Open {
		return ErrAlreadyClosed
	}
	p.Open = false
	return nil
}

// Reopen lets a closed plan take subscriptions again. Creator only.
func (r *Registry) Reopen(id store.ID, who address) error {
	p, err := r.ownPlan(id, who)
	if err != nil {
		return err
	}
	if p.Open {
		return ErrAlreadyOpen
	}
	p.Open = true
	return nil
}

// ownPlan is the shared lookup plus authority check, so Close and Reopen
// cannot drift apart on who is allowed to call them.
func (r *Registry) ownPlan(id store.ID, who address) (*Plan, error) {
	p, ok := r.Get(id)
	if !ok {
		return nil, ErrNoPlan
	}
	if p.Creator != who {
		return nil, ErrNotCreator
	}
	return p, nil
}

// Withdraw zeroes who's credit and reports what they were owed.
//
// It moves no coins. The holding realm transfers the returned amount AFTER
// this call, which is the whole point of the pattern: the credit is already
// gone from the ledger when control passes to the payee, so a reentrant call
// finds nothing and gets [ErrNothingToWithdraw].
func (r *Registry) Withdraw(who address) (int64, error) {
	amount, err := r.ledger.Withdraw(who.String())
	if err != nil {
		return 0, ErrNothingToWithdraw
	}
	return amount, nil
}

// CreditOf is what addr can withdraw right now: earnings as a creator, change
// as a supporter, or both.
func (r *Registry) CreditOf(addr address) int64 { return r.ledger.Balance(addr.String()) }

// EarnedBy is the lifetime ugnot credited to creator across every plan,
// whether or not it has been withdrawn.
func (r *Registry) EarnedBy(creator address) int64 { return r.earned[creator.String()] }

// TotalOwed is everything the holding realm must keep in reserve.
func (r *Registry) TotalOwed() int64 { return r.ledger.TotalOwed() }

// Get returns a plan by id.
func (r *Registry) Get(id store.ID) (*Plan, bool) {
	v, ok := r.plans.Get(id)
	if !ok {
		return nil, false
	}
	return v.(*Plan), true
}

// Count is how many plans exist.
func (r *Registry) Count() int { return r.plans.Len() }

// Listing is one row of [Registry.List]: the plan and the id a link needs.
type Listing struct {
	ID   store.ID
	Plan *Plan
}

// List returns one page of plans, newest first.
func (r *Registry) List(page, size int) []Listing {
	var out []Listing
	for _, e := range r.plans.PageReverse(page, size) {
		out = append(out, Listing{ID: e.ID, Plan: e.Value.(*Plan)})
	}
	return out
}

// Pages is how many pages of the given size the registry holds.
func (r *Registry) Pages(size int) int { return r.plans.Pages(size) }

// ValidTitle reports whether title can be stored: non-empty after trimming,
// within [MaxTitleLen], and free of control characters including newlines.
//
// A title is one line by construction, so a newline in one is refused rather
// than stripped: silently rewriting what somebody typed is worse than telling
// them it was refused.
func ValidTitle(title string) bool {
	if len(title) > MaxTitleLen || strings.TrimSpace(title) == "" {
		return false
	}
	for i := 0; i < len(title); i++ {
		if c := title[i]; c < 0x20 || c == 0x7f {
			return false
		}
	}
	return true
}

// ValidDescription reports whether description can be stored: within
// [MaxDescriptionLen] and free of control characters other than newline and
// tab. Empty is allowed, because a plan whose title says it all should not
// have to invent prose.
func ValidDescription(description string) bool {
	if len(description) > MaxDescriptionLen {
		return false
	}
	for i := 0; i < len(description); i++ {
		c := description[i]
		if c < 0x20 && c != '\n' && c != '\t' || c == 0x7f {
			return false
		}
	}
	return true
}

// PlanURL is the gnoweb path of one plan on the hosting realm.
func PlanURL(realmPath string, id store.ID) string {
	return RealmURL(realmPath) + ":plan/" + id.String()
}

// RealmURL is the gnoweb path of a realm given as a package path.
//
// The chain domain is the first element of a package path and a gnoweb path is
// the rest of it, so this is a prefix strip and not a hostname this package
// has to know.
func RealmURL(realmPath string) string {
	if i := strings.Index(realmPath, "/"); i >= 0 {
		return realmPath[i:]
	}
	return "/" + realmPath
}

// Package threads is the engine behind an embeddable discussion block: the
// text half of what a reaction bar does, keyed on the PAGE it is shown under
// rather than on the realm that stores it.
//
// # Why not a forum
//
// A forum is a destination, and a destination has to earn its traffic before
// anybody writes the first post. A block does not: it is dropped into pages
// that already have readers, and the discussion attaches to the object it is
// about. One realm holds every thread, every host realm ships the same two
// lines, and no host realm stores anything.
//
// That is the shape the web settled on for comments in 2010, and the same one
// [gno.land/p/moul/reactions] uses for the tally. This package is deliberately
// its neighbour: reactions are a closed palette and need no moderation, text
// needs some, and the two are separate so a realm can take the cheap one alone.
//
// # The model
//
//	Board    every thread, across every page
//	Thread   a root post: page, author, body, height, pin, replies
//	Reply    an author, a body and a height, and nothing else
//
// A thread remembers the set of addresses that have replied to it, which is
// what lets a realm implement "earned by being replied to" without counting
// one person twice. [Board.Reply] reports whether the replier was new, so the
// mint rule has exactly one signal and exactly one call site.
//
// # Ordering, and the pin
//
// [Board.List] returns pinned threads first, then the rest, both newest first,
// which is a partition and not a sort: no comparator, no tie to break, and the
// same input always produces the same page. A pin is an absolute height, so it
// expires on its own and nothing has to be swept.
//
// The realm decides what a pin costs. This package only enforces that a pin
// cannot be moved backwards, so buying one does not shorten somebody else's.
//
// # Page keys and bodies
//
// A page key is a package path, the full one, chain domain included.
// [ValidPage] bounds it to a path-shaped lowercase ASCII string of at most
// [MaxPageLen] bytes, so a stored key can never be a markdown payload. A body
// is bounded by [MaxBodyLen] and rejected when it carries a control character,
// but it is otherwise free text and therefore attacker-controlled markdown:
// everything here escapes it with ui.Inline or ui.Cell, and so must any realm
// that renders one itself.
package threads

import (
	"errors"
	"strconv"
	"strings"

	"gno.land/p/moul/kit/store/v0"
	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/md/v0"
)

const (
	// MaxPageLen is the longest page key accepted, matching
	// gno.land/p/moul/reactions so the two blocks agree on what a page is.
	MaxPageLen = 120

	// MaxBodyLen is the longest post or reply accepted, in bytes. Long
	// enough for a real comment, short enough that one call cannot lock an
	// unbounded storage deposit somebody else is paying for.
	MaxBodyLen = 1000

	// ExcerptLen is how much of a body a listing shows.
	ExcerptLen = 60
)

// The errors a caller can get back. A p/ returns them; the realm decides to
// abort.
var (
	ErrBadPage   = errors.New("threads: not a page key")
	ErrBadBody   = errors.New("threads: body is empty, too long, or has control characters")
	ErrNoThread  = errors.New("threads: no such thread")
	ErrPinIsPast = errors.New("threads: a pin cannot be moved backwards")
)

// Reply is one answer under a thread.
type Reply struct {
	Author address
	Body   string
	At     int64 // block height
}

// Thread is a root post and everything under it.
type Thread struct {
	Page    string
	Author  address
	Body    string
	At      int64 // block height
	Replies []Reply

	// PinnedUntil is the height the thread stops being pinned at. Zero is
	// never pinned, and a past height is an expired pin: nothing has to
	// sweep it.
	PinnedUntil int64

	// repliers is the set of addresses that have replied, so a thread can
	// be scored on people rather than on messages.
	repliers map[string]bool
}

// Pinned reports whether the thread is pinned at height now.
func (t *Thread) Pinned(now int64) bool { return t != nil && t.PinnedUntil > now }

// Repliers is how many distinct addresses have replied.
func (t *Thread) Repliers() int {
	if t == nil {
		return 0
	}
	return len(t.repliers)
}

// HasReplied reports whether who has already replied to this thread.
func (t *Thread) HasReplied(who address) bool {
	if t == nil {
		return false
	}
	return t.repliers[who.String()]
}

// Board holds every thread, indexed by the page it was posted under.
type Board struct {
	threads *store.Store
	pages   map[string][]store.ID // page key -> ids, oldest first
}

// NewBoard returns an empty board.
func NewBoard() *Board {
	return &Board{threads: store.Named("thread"), pages: map[string][]store.ID{}}
}

// Post opens a thread on page and returns its id.
func (b *Board) Post(page string, author address, body string, at int64) (store.ID, error) {
	if !ValidPage(page) {
		return 0, ErrBadPage
	}
	if !ValidBody(body) {
		return 0, ErrBadBody
	}
	id := b.threads.Add(&Thread{
		Page:     page,
		Author:   author,
		Body:     body,
		At:       at,
		repliers: map[string]bool{},
	})
	b.pages[page] = append(b.pages[page], id)
	return id, nil
}

// Reply appends to a thread and reports whether this author had never replied
// to it before.
//
// That boolean is the mint signal: a realm that pays an author for attention
// wants distinct people, not distinct messages, and a thread's own author
// replying to themselves is never new.
func (b *Board) Reply(id store.ID, author address, body string, at int64) (isNewReplier bool, err error) {
	t, ok := b.Get(id)
	if !ok {
		return false, ErrNoThread
	}
	if !ValidBody(body) {
		return false, ErrBadBody
	}
	t.Replies = append(t.Replies, Reply{Author: author, Body: body, At: at})

	key := author.String()
	if author == t.Author || t.repliers[key] {
		return false, nil
	}
	t.repliers[key] = true
	return true, nil
}

// Pin keeps a thread at the top of its page until height until.
//
// It refuses to move a pin backwards, so a cheap pin cannot cut short an
// expensive one, and extends from whichever is later: the current pin or now.
func (b *Board) Pin(id store.ID, until int64) error {
	t, ok := b.Get(id)
	if !ok {
		return ErrNoThread
	}
	if until <= t.PinnedUntil {
		return ErrPinIsPast
	}
	t.PinnedUntil = until
	return nil
}

// Get returns a thread by id.
func (b *Board) Get(id store.ID) (*Thread, bool) {
	v, ok := b.threads.Get(id)
	if !ok {
		return nil, false
	}
	return v.(*Thread), true
}

// Len is how many threads exist, across every page.
func (b *Board) Len() int { return b.threads.Len() }

// Pages is how many pages have ever been posted on.
func (b *Board) Pages() int { return len(b.pages) }

// PageLen is how many threads a page holds.
func (b *Board) PageLen(page string) int { return len(b.pages[page]) }

// Listing is one row of [Board.List]: the thread and the id a link needs.
type Listing struct {
	ID     store.ID
	Thread *Thread
}

// List returns up to limit threads on page: pinned first, then the rest, both
// newest first.
//
// It is a partition and not a sort. There is no comparator and no tie to
// break, so two identical calls always produce the same page, which is what a
// Render needs. limit <= 0 returns everything.
func (b *Board) List(page string, now int64, limit int) []Listing {
	ids := b.pages[page]
	var pinned, rest []Listing
	for i := len(ids) - 1; i >= 0; i-- {
		t, ok := b.Get(ids[i])
		if !ok {
			continue
		}
		item := Listing{ID: ids[i], Thread: t}
		if t.Pinned(now) {
			pinned = append(pinned, item)
		} else {
			rest = append(rest, item)
		}
	}
	out := append(pinned, rest...)
	if limit > 0 && len(out) > limit {
		out = out[:limit]
	}
	return out
}

// Recent returns up to limit threads from every page, newest first. It is what
// the hosting realm's own homepage shows.
func (b *Board) Recent(limit int) []Listing {
	var out []Listing
	for _, e := range b.threads.PageReverse(1, limit) {
		out = append(out, Listing{ID: e.ID, Thread: e.Value.(*Thread)})
	}
	return out
}

// ValidPage reports whether page is a usable page key: path-shaped, lowercase
// ASCII, no leading, trailing or doubled slash, at most [MaxPageLen] bytes.
//
// Same rule as gno.land/p/moul/reactions, deliberately: a realm embedding both
// blocks passes one key to both.
func ValidPage(page string) bool {
	if page == "" || len(page) > MaxPageLen {
		return false
	}
	if strings.HasPrefix(page, "/") || strings.HasSuffix(page, "/") ||
		strings.Contains(page, "//") || !strings.Contains(page, "/") {
		return false
	}
	for i := 0; i < len(page); i++ {
		c := page[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9':
		case c == '/' || c == '.' || c == '-' || c == '_' || c == ':':
		default:
			return false
		}
	}
	return true
}

// ValidBody reports whether body can be stored: non-empty after trimming,
// within [MaxBodyLen], and free of control characters.
//
// Control characters are refused rather than stripped because a body is shown
// back to its author: silently rewriting what somebody wrote is worse than
// telling them it was refused. Everything else is allowed and escaped at
// render time, since a validator and an escaper protect against different
// mistakes.
func ValidBody(body string) bool {
	if len(body) > MaxBodyLen || strings.TrimSpace(body) == "" {
		return false
	}
	for i := 0; i < len(body); i++ {
		c := body[i]
		if c < 0x20 && c != '\n' && c != '\t' || c == 0x7f {
			return false
		}
	}
	return true
}

// Block renders the embeddable widget: the page's threads, then the button
// that opens a new one.
//
// realmPath is the realm that owns Post and Reply, given as the full package
// path from its gnomod.toml module line. It is a parameter and not a constant
// because this package is the engine and not the deployment.
func Block(realmPath, page string, items []Listing, total int, now int64) string {
	out := ""
	if len(items) == 0 {
		out += ui.Empty("No discussion yet.")
	} else {
		t := ui.NewTable("", "#", "thread", "by", "replies")
		for _, it := range items {
			mark := ""
			if it.Thread.Pinned(now) {
				mark = "📌"
			}
			t.Row(
				mark,
				// The link title is the id and never the body. md.Link
				// escapes markdown but NOT a pipe (sanitize.InlineText
				// leaves it; only ui.Cell rewrites it), so a body used as
				// a link title inside a table opens a column.
				md.Link("#"+it.ID.String(), ThreadURL(realmPath, it.ID)),
				// Cut first, escape second: the other order can strand a
				// trailing backslash that escapes the chrome after it.
				ui.Cell(ui.ShortN(it.Thread.Body, ExcerptLen, 0)),
				ui.Addr(it.Thread.Author),
				strconv.Itoa(len(it.Thread.Replies)),
			)
		}
		out += t.String()
	}

	out += "\n" + ui.ActionIn(realmPath, "💬 Post", "Post", "page", page, "body", "")
	if total > len(items) {
		out += " · " + md.Link(
			strconv.Itoa(total)+" threads",
			PageURL(realmPath, page),
		)
	}
	return out + "\n"
}

// ThreadURL is the gnoweb path of one thread on the hosting realm.
func ThreadURL(realmPath string, id store.ID) string {
	return RealmURL(realmPath) + ":thread/" + id.String()
}

// PageURL is the gnoweb path of a page's full thread list.
func PageURL(realmPath, page string) string {
	return RealmURL(realmPath) + ":page/" + page
}

// RealmURL is the gnoweb path of a realm given as a package path.
//
// The chain domain is the first element of a package path and a gnoweb path is
// the rest of it, so this is a prefix strip and not a hostname this package
// has to know.
func RealmURL(realmPath string) string {
	if i := strings.Index(realmPath, "/"); i >= 0 {
		return realmPath[i:]
	}
	return "/" + realmPath
}

// Package vouch is the engine behind a web of trust: one address says it
// stands behind another, in writing, optionally with its own money locked
// against the claim.
//
// # What it is for
//
// It is a sybil gate, and it exists because the apps around it do not have
// one. A realm that mints a point per distinct replier is farmed by two
// addresses replying to each other; a realm that counts one vote per address
// is farmed by holding a hundred addresses. Neither can fix that alone,
// because neither knows anything about the people behind the addresses.
//
// This package knows one thing: who was willing to say, on chain and under
// their own name, that an address is a person they stand behind. A realm asks
// [Graph.IsTrusted] and gates on the answer. That is the whole product, and
// every other read here exists to make that one legible.
//
// # The model
//
//	Graph   every vouch, in both directions, plus the refund ledger
//	Vouch   a directed statement: from, for, reason, bond, heights
//
// A vouch is directed and at most one exists per ordered pair. A second
// [Graph.Record] from the same address to the same target UPDATES the reason
// and ADDS to the bond rather than counting twice, which is what makes the
// score a count of people instead of a count of transactions. An address
// cannot vouch for itself.
//
// # The bond
//
// A vouch may lock coins. The engine only counts them: it takes the amount as
// an argument, tracks who posted how much on whom, and on [Graph.Revoke] moves
// that amount into a withdrawal ledger the voucher pulls from. It moves
// nothing itself. The realm holding the coins performs the transfer AFTER
// [Graph.Withdraw] has zeroed the credit, which is the ordering the
// pull-payment pattern demands.
//
// # No slashing, and why that is the hard part
//
// A bond here is value at risk only in the sense that it is illiquid: it can
// be withdrawn by revoking, and nothing can take it away. That is deliberate
// for a v0, and the missing half is not the accounting.
//
// Slashing needs an arbiter: somebody has to decide that a vouch was a lie.
// Every candidate is a design question with teeth. A DAO vote is a popularity
// contest against whoever is unpopular this month. A challenge market pays
// whoever is loudest and turns the graph into a griefing surface. An oracle is
// one key that can confiscate anyone's money. Shipping any of them by default
// would be shipping the wrong one, so this version ships the part that is
// uncontroversial: who said what, who put money behind it, and the gate that
// reads it.
//
// # Reasons are attacker-controlled markdown
//
// A reason is free text. [ValidReason] bounds it to [MaxReasonLen] bytes on
// one line and refuses control characters, but everything inside that is
// allowed and must be escaped where it is shown: ui.Inline in prose, ui.Cell
// in a table cell.
package vouch

import (
	"errors"
	"strconv"
	"strings"

	"gno.land/p/moul/addrset/v1"
	"gno.land/p/moul/kit/num/v0"
	"gno.land/p/moul/kit/tally/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/x/daily/pullpayment/v0"
)

// MaxReasonLen is the longest reason accepted, in bytes. Long enough to say
// how you know somebody, short enough that one call cannot lock an unbounded
// storage deposit the realm's deployer is paying for.
const MaxReasonLen = 200

const maxInt64 = int64(9223372036854775807)

// The errors a caller can get back. A p/ returns them; the realm decides to
// abort.
var (
	ErrSelfVouch   = errors.New("vouch: an address cannot vouch for itself")
	ErrBadReason   = errors.New("vouch: reason is empty, too long, multi-line, or has control characters")
	ErrBadBond     = errors.New("vouch: a bond cannot be negative")
	ErrNoVouch     = errors.New("vouch: no such vouch")
	ErrNothingOwed = errors.New("vouch: nothing to withdraw")
	ErrOverflow    = errors.New("vouch: bond would overflow")
)

// Vouch is one directed statement of trust.
type Vouch struct {
	From   address
	For    address
	Reason string

	// Bond is the amount locked on this vouch, in the realm's denom. It is
	// the sum of every bond sent with this pair, since a repeated vouch
	// adds to it rather than replacing it.
	Bond int64

	// At is the height the vouch was first made, UpdatedAt the height it
	// last changed. They are equal until the voucher restates it.
	At        int64
	UpdatedAt int64
}

// Graph is the whole web of trust: every vouch, both directions of every
// edge, what is bonded on whom, and what revoking owes back to whom.
type Graph struct {
	edges    map[string]*Vouch       // "from|for" -> the vouch
	inbound  map[string]*addrset.Set // target -> who vouches for them
	outbound map[string]*addrset.Set // voucher -> who they vouch for
	bonded   map[string]int64        // target -> total bonded on them

	// people is every address with at least one inbound vouch, sorted, so
	// a listing never has to iterate a map to build rendered output.
	people addrset.Set

	refunds     *pullpayment.Ledger
	count       int
	totalBonded int64
}

// NewGraph returns an empty graph.
func NewGraph() *Graph {
	return &Graph{
		edges:    map[string]*Vouch{},
		inbound:  map[string]*addrset.Set{},
		outbound: map[string]*addrset.Set{},
		bonded:   map[string]int64{},
		refunds:  pullpayment.New(),
	}
}

// Record writes from's vouch for target and reports whether it replaced one
// that already existed.
//
// A repeated vouch is an update and not a second voice: the reason is
// replaced, the bond is added to the one already posted, and the score does
// not move. bond may be zero, which is the ordinary case.
func (g *Graph) Record(from, target address, reason string, bond, at int64) (updated bool, err error) {
	if from == target {
		return false, ErrSelfVouch
	}
	if !ValidReason(reason) {
		return false, ErrBadReason
	}
	if bond < 0 {
		return false, ErrBadBond
	}
	tk := target.String()
	if g.bonded[tk] > maxInt64-bond || g.totalBonded > maxInt64-bond {
		return false, ErrOverflow
	}

	if v, ok := g.edges[key(from, target)]; ok {
		if v.Bond > maxInt64-bond {
			return false, ErrOverflow
		}
		v.Reason = reason
		v.Bond += bond
		v.UpdatedAt = at
		g.bonded[tk] += bond
		g.totalBonded += bond
		return true, nil
	}

	g.edges[key(from, target)] = &Vouch{
		From:      from,
		For:       target,
		Reason:    reason,
		Bond:      bond,
		At:        at,
		UpdatedAt: at,
	}
	g.set(g.inbound, tk).Add(from)
	g.set(g.outbound, from.String()).Add(target)
	g.people.Add(target)
	g.bonded[tk] += bond
	g.totalBonded += bond
	g.count++
	return false, nil
}

// Revoke removes from's vouch for target and credits the bond back to from,
// returning the amount credited.
//
// The coins are not sent here and this package never holds any: the credit
// waits in the refund ledger until from calls [Graph.Withdraw].
func (g *Graph) Revoke(from, target address) (refund int64, err error) {
	v, ok := g.edges[key(from, target)]
	if !ok {
		return 0, ErrNoVouch
	}
	// Credit first, because it is the only step that can fail. Nothing is
	// mutated until the refund is certain, so a full ledger leaves the
	// graph exactly as it was rather than half revoked.
	if v.Bond > 0 {
		if err := g.refunds.Credit(from.String(), v.Bond); err != nil {
			return 0, err
		}
	}

	delete(g.edges, key(from, target))
	tk, fk := target.String(), from.String()

	if in, ok := g.inbound[tk]; ok {
		in.Remove(from)
		if in.Size() == 0 {
			delete(g.inbound, tk)
			g.people.Remove(target)
		}
	}
	if out, ok := g.outbound[fk]; ok {
		out.Remove(target)
		if out.Size() == 0 {
			delete(g.outbound, fk)
		}
	}

	g.bonded[tk] -= v.Bond
	if g.bonded[tk] == 0 {
		delete(g.bonded, tk)
	}
	g.totalBonded -= v.Bond
	g.count--
	return v.Bond, nil
}

// Withdraw zeroes what the graph owes who and returns it, so the realm can
// send exactly that much.
//
// The credit is gone from the ledger before this returns, which is what makes
// a reentrant call find nothing: the realm transfers after, never before.
func (g *Graph) Withdraw(who address) (int64, error) {
	amount, err := g.refunds.Withdraw(who.String())
	if err != nil {
		return 0, ErrNothingOwed
	}
	return amount, nil
}

// Get returns one vouch.
func (g *Graph) Get(from, target address) (*Vouch, bool) {
	v, ok := g.edges[key(from, target)]
	return v, ok
}

// ScoreOf is how many distinct addresses vouch for addr.
//
// It counts people and not statements: restating a vouch does not raise it,
// and revoking lowers it.
func (g *Graph) ScoreOf(addr address) int {
	if in, ok := g.inbound[addr.String()]; ok {
		return in.Size()
	}
	return 0
}

// BondedFor is the total locked on addr by everyone vouching for them.
func (g *Graph) BondedFor(addr address) int64 { return g.bonded[addr.String()] }

// IsTrusted reports whether addr is vouched for by at least min distinct
// addresses. It is the gate another realm calls, and the reason this package
// exists.
//
// A min below one is raised to one. A gate that lets everybody through is a
// bug at the call site rather than an answer worth returning, and silently
// agreeing with it is how a sybil check ships disabled.
//
// What it cannot tell you is whether those vouchers are distinct PEOPLE. Two
// addresses vouching for each other both reach a score of one for the price of
// two transactions, which is why [Graph.Mutual] is exported and why a gate
// that matters should ask for more than one.
func (g *Graph) IsTrusted(addr address, min int) bool {
	if min < 1 {
		min = 1
	}
	return g.ScoreOf(addr) >= min
}

// VouchedBy is every address that vouches for addr, sorted.
//
// Sorted and not chronological: the set is the storage, the order is a total
// order on the address, and two identical calls therefore render identically.
func (g *Graph) VouchedBy(addr address) []address {
	return collect(g.inbound[addr.String()])
}

// VouchesOf is every address addr vouches for, sorted. It is the other
// direction of [Graph.VouchedBy].
func (g *Graph) VouchesOf(addr address) []address {
	return collect(g.outbound[addr.String()])
}

// Mutual reports whether a and b vouch for each other.
//
// A mutual pair is the cheapest sybil shape there is, so this is here to be
// discounted by a caller that cares, not as a badge.
func (g *Graph) Mutual(a, b address) bool {
	if a == b {
		return false
	}
	_, there := g.edges[key(a, b)]
	_, back := g.edges[key(b, a)]
	return there && back
}

// ReasonFrom is what from wrote about target, or the empty string when there
// is no such vouch. It is raw caller text: escape it where it is shown.
func (g *Graph) ReasonFrom(from, target address) string {
	if v, ok := g.edges[key(from, target)]; ok {
		return v.Reason
	}
	return ""
}

// BondFrom is what from locked on target, or zero.
func (g *Graph) BondFrom(from, target address) int64 {
	if v, ok := g.edges[key(from, target)]; ok {
		return v.Bond
	}
	return 0
}

// Count is how many vouches exist, across everybody.
func (g *Graph) Count() int { return g.count }

// People is how many addresses have at least one vouch for them.
func (g *Graph) People() int { return g.people.Size() }

// Owed is what revoking has credited to addr and nobody has withdrawn yet.
func (g *Graph) Owed(addr address) int64 { return g.refunds.Balance(addr.String()) }

// TotalOwed is every unwithdrawn refund. The realm must hold at least
// TotalOwed plus [Graph.TotalBonded] to be solvent.
func (g *Graph) TotalOwed() int64 { return g.refunds.TotalOwed() }

// TotalBonded is everything locked on every vouch that still stands.
func (g *Graph) TotalBonded() int64 { return g.totalBonded }

// Ranked is one row of [Graph.Leaderboard].
type Ranked struct {
	Addr   address
	Score  int
	Bonded int64
}

// Leaderboard is the most vouched for addresses, highest score first, ties
// broken by address so the order is total and a Render never reshuffles.
//
// limit at or below zero returns nothing.
func (g *Graph) Leaderboard(limit int) []Ranked {
	if limit <= 0 || g.people.Size() == 0 {
		return nil
	}
	entries := make([]tally.Entry, 0, g.people.Size())
	g.people.IterateByOffset(0, g.people.Size(), func(a address) bool {
		entries = append(entries, tally.Entry{Key: a.String(), Score: int64(g.ScoreOf(a))})
		return false
	})
	top := tally.Top(entries, limit)

	out := make([]Ranked, 0, len(top))
	for _, e := range top {
		a := address(e.Key)
		out = append(out, Ranked{Addr: a, Score: int(e.Score), Bonded: g.bonded[e.Key]})
	}
	return out
}

// ValidReason reports whether reason can be stored: non-empty after trimming,
// within [MaxReasonLen], on one line, and free of control characters.
//
// One line is a deliberate bound rather than a rendering workaround. A reason
// is shown in a table cell beside the address it is about, and a writer who
// needs a second paragraph is writing something other than a reason.
//
// Control characters are refused rather than stripped because the text is
// shown back to whoever wrote it, and silently rewriting what somebody said is
// worse than telling them it was refused. Everything else is allowed and
// escaped at render time, since a validator and an escaper protect against
// different mistakes.
func ValidReason(reason string) bool {
	if len(reason) > MaxReasonLen || strings.TrimSpace(reason) == "" {
		return false
	}
	for i := 0; i < len(reason); i++ {
		if c := reason[i]; c < 0x20 || c == 0x7f {
			return false
		}
	}
	return true
}

// Badge is the one-line trust mark, for a realm that wants to show what the
// gate it just called was reading.
//
// It takes the numbers rather than the graph because the realm holding the
// graph is the only one that can read it: everybody else has the two integers
// from a cross-realm call and needs nothing more to render them.
func Badge(realmPath string, addr address, score int, bonded int64) string {
	if score == 0 {
		return md.Link("not vouched for", AddrURL(realmPath, addr))
	}
	word := " vouchers"
	if score == 1 {
		word = " voucher"
	}
	out := "\U0001F91D " + md.Link(strconv.Itoa(score)+word, AddrURL(realmPath, addr))
	if bonded > 0 {
		out += " · " + num.GNOTf(bonded) + " bonded"
	}
	return out
}

// AddrURL is the gnoweb path of one address's page on the hosting realm.
func AddrURL(realmPath string, addr address) string {
	return RealmURL(realmPath) + ":addr/" + addr.String()
}

// RealmURL is the gnoweb path of a realm given as a package path.
//
// The chain domain is the first element of a package path and a gnoweb path is
// the rest of it, so this is a prefix strip and not a hostname this package
// has to know.
func RealmURL(realmPath string) string {
	if i := strings.Index(realmPath, "/"); i >= 0 {
		return realmPath[i:]
	}
	return "/" + realmPath
}

// key is the storage key of one directed edge. Addresses are fixed-length
// bech32, so the separator is belt and braces rather than load-bearing.
func key(from, target address) string { return from.String() + "|" + target.String() }

// set returns the address set stored under k, creating it on first use.
func (g *Graph) set(m map[string]*addrset.Set, k string) *addrset.Set {
	if s, ok := m[k]; ok {
		return s
	}
	s := &addrset.Set{}
	m[k] = s
	return s
}

// collect reads a set out in sorted order.
func collect(s *addrset.Set) []address {
	if s == nil || s.Size() == 0 {
		return nil
	}
	out := make([]address, 0, s.Size())
	s.IterateByOffset(0, s.Size(), func(a address) bool {
		out = append(out, a)
		return false
	})
	return out
}

package collatz

import (
	"chain"
	"sort"
	"strconv"
	"strings"

	"gno.land/p/moul/md/v0"
	"gno.land/p/nt/avl/v0"
)

// selfPath is this realm's own page. A root-relative link resolves against
// the domain, not the realm, so every link back into it names it in full.
const selfPath = "/r/moul/x/daily/collatz/v1"

// maxIters caps the Collatz walk so a hostile / huge input cannot loop
// forever on-chain. No known n stays below this bound and fails to reach 1.
const maxIters = 1000000

// MaxResults bounds the leaderboard's state: anyone may Compute, and each new
// n is a new entry the root page sorts.
const MaxResults = 1000

// maxSeqLen caps how many terms Render("/<n>") will print.
const maxSeqLen = 500

// Result is one recorded submission.
type Result struct {
	N     int64
	Steps int
	Peak  int64
	Who   address
}

// results maps a decimal-string key of N -> Result. avl.Tree keeps a
// deterministic order for iteration inside Render.
var results avl.Tree

// maxOdd is the largest odd term whose successor 3n+1 still fits in an
// int64. Past it the step wraps: 6148914691236517205 maps to exactly 2^64,
// which is 0, and the walk then spins on 0 until maxIters.
const maxOdd = (1<<63 - 1 - 1) / 3

// stopping returns the number of steps to reach 1 and the peak value seen,
// walking the Collatz (hailstone) map. ok is false when a term would overflow
// int64, in which case steps and peak describe the walk up to that term. It
// never mutates state.
func stopping(n int64) (steps int, peak int64, ok bool) {
	peak = n
	cur := n
	for cur != 1 {
		if steps >= maxIters {
			break
		}
		if cur%2 == 0 {
			cur = cur / 2
		} else {
			if cur > maxOdd {
				return steps, peak, false
			}
			cur = 3*cur + 1
		}
		if cur > peak {
			peak = cur
		}
		steps++
	}
	return steps, peak, true
}

// Compute walks the hailstone sequence for n and records the result
// attributed to the caller. It is a crossing (state-mutating) func.
func Compute(cur realm, n int) {
	if !cur.IsCurrent() {
		panic("collatz: spoofed realm")
	}
	caller := cur.Previous().Address()
	if n <= 0 {
		panic("n must be > 0")
	}
	nn := int64(n)
	steps, peak, ok := stopping(nn)
	if !ok {
		// Recording it would put a wrapped walk on the leaderboard, forever.
		panic("collatz: the walk from " + strconv.FormatInt(nn, 10) + " overflows int64")
	}

	res := Result{N: nn, Steps: steps, Peak: peak, Who: caller}
	key := strconv.FormatInt(nn, 10)
	if !results.Has(key) && results.Size() >= MaxResults {
		panic("collatz: the leaderboard is full at " + strconv.Itoa(MaxResults) + " entries")
	}
	results.Set(key, res)

	chain.Emit(
		"Computed",
		"n", key,
		"steps", strconv.Itoa(steps),
		"peak", strconv.FormatInt(peak, 10),
		"who", caller.String(),
	)
}

// byLongest implements sort.Interface, ordering results by steps desc,
// then peak desc, then n asc for stability.
type byLongest []Result

func (b byLongest) Len() int      { return len(b) }
func (b byLongest) Swap(i, j int) { b[i], b[j] = b[j], b[i] }
func (b byLongest) Less(i, j int) bool {
	if b[i].Steps != b[j].Steps {
		return b[i].Steps > b[j].Steps
	}
	if b[i].Peak != b[j].Peak {
		return b[i].Peak > b[j].Peak
	}
	return b[i].N < b[j].N
}

// Render shows the leaderboard at root, or the full hailstone sequence for a
// given n at path "/<n>".
func Render(path string) string {
	p := strings.TrimPrefix(path, "/")
	if p == "" {
		return renderLeaderboard()
	}
	return renderSequence(p)
}

func renderLeaderboard() string {
	all := make([]Result, 0, results.Size())
	results.Iterate("", "", func(_ string, v interface{}) bool {
		all = append(all, v.(Result))
		return false
	})

	var sb strings.Builder
	sb.WriteString("# Collatz Explorer\n\n")
	sb.WriteString("Hailstone-sequence explorer. Call `Compute(n)` to record a run, ")
	sb.WriteString("or view a full sequence at `/<n>`.\n\n")

	if len(all) == 0 {
		sb.WriteString("_No sequences submitted yet._\n")
		return sb.String()
	}

	sort.Stable(byLongest(all))

	sb.WriteString("## Leaderboard — longest sequences\n\n")
	sb.WriteString("| # | n | steps | peak | who |\n")
	sb.WriteString("|---|---|-------|------|-----|\n")
	limit := len(all)
	if limit > 20 {
		limit = 20
	}
	for i := 0; i < limit; i++ {
		r := all[i]
		sb.WriteString("| " + strconv.Itoa(i+1) + " | ")
		sb.WriteString("[" + strconv.FormatInt(r.N, 10) + "](" + selfPath + ":" + strconv.FormatInt(r.N, 10) + ") | ")
		sb.WriteString(strconv.Itoa(r.Steps) + " | ")
		sb.WriteString(strconv.FormatInt(r.Peak, 10) + " | ")
		sb.WriteString(r.Who.String() + " |\n")
	}
	sb.WriteString("\n_" + strconv.Itoa(len(all)) + " sequence(s) recorded._\n")
	return sb.String()
}

func renderSequence(p string) string {
	n, err := strconv.ParseInt(p, 10, 64)
	var sb strings.Builder
	if err != nil || n <= 0 {
		sb.WriteString("# Invalid n\n\n" + md.InlineCode(p) + " is not a positive integer.\n")
		return sb.String()
	}

	sb.WriteString("# Hailstone sequence for " + strconv.FormatInt(n, 10) + "\n\n")

	seq := make([]int64, 0, 64)
	cur := n
	var peak int64 = n
	truncated := false
	overflow := false
	for {
		seq = append(seq, cur)
		if cur == 1 {
			break
		}
		if len(seq) >= maxSeqLen {
			truncated = true
			break
		}
		if cur%2 == 0 {
			cur = cur / 2
		} else {
			if cur > maxOdd {
				overflow = true
				break
			}
			cur = 3*cur + 1
		}
		if cur > peak {
			peak = cur
		}
	}

	parts := make([]string, len(seq))
	for i, v := range seq {
		parts[i] = strconv.FormatInt(v, 10)
	}
	sb.WriteString(strings.Join(parts, " → "))
	sb.WriteString("\n\n")
	sb.WriteString("- steps: " + strconv.Itoa(len(seq)-1) + "\n")
	sb.WriteString("- peak: " + strconv.FormatInt(peak, 10) + "\n")
	if overflow {
		sb.WriteString("\n_Stopped: the next term would overflow int64._\n")
	}
	if truncated {
		sb.WriteString("\n_Sequence truncated at " + strconv.Itoa(maxSeqLen) + " terms._\n")
	}
	return sb.String()
}

package collatz

import (
	"strings"
	"testing"

	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

func TestStopping(t *testing.T) {
	cases := []struct {
		n     int64
		steps int
		peak  int64
	}{
		{1, 0, 1},
		{2, 1, 2},
		{6, 8, 16},
		{7, 16, 52},
		{27, 111, 9232},
	}
	for _, c := range cases {
		steps, peak, _ := stopping(c.n)
		uassert.Equal(t, c.steps, steps)
		uassert.Equal(t, c.peak, peak)
	}
}

func TestComputeAndLeaderboard(cur realm, t *testing.T) {
	addr := testutils.TestAddress("alice")
	testing.SetRealm(testing.NewUserRealm(addr))

	Compute(cross(cur), 27)
	Compute(cross(cur), 6)

	out := Render("")
	uassert.True(t, strings.Contains(out, "Leaderboard"), "has leaderboard")
	uassert.True(t, strings.Contains(out, "9232"), "shows peak of 27")
	// 27 has more steps than 6, so it must appear first (rank 1).
	i27 := strings.Index(out, "[27]")
	i6 := strings.Index(out, "[6]")
	uassert.True(t, i27 >= 0 && i6 >= 0, "both rows present")
	uassert.True(t, i27 < i6, "27 ranked above 6")
}

func TestComputeRejectsNonPositive(cur realm, t *testing.T) {
	addr := testutils.TestAddress("bob")
	testing.SetRealm(testing.NewUserRealm(addr))
	uassert.AbortsWithMessage(t, cur, "n must be > 0", func() {
		Compute(cross(cur), 0)
	})
}

func TestRenderSequence(t *testing.T) {
	out := Render("/6")
	uassert.True(t, strings.Contains(out, "6 → 3 → 10 → 5 → 16 → 8 → 4 → 2 → 1"), "full seq for 6")
	uassert.True(t, strings.Contains(out, "steps: 8"), "reports 8 steps")

	bad := Render("/abc")
	uassert.True(t, strings.Contains(bad, "Invalid"), "rejects non-numeric path")
}

// 3n+1 for this n is exactly 2^64, which wraps to 0. Recording it would put a
// million-step walk on 0 at the top of the leaderboard, forever.
func TestComputeRefusesAnOverflowingWalk(cur realm, t *testing.T) {
	uassert.AbortsContains(t, cur, "overflows int64", func() { Compute(cross(cur), 6148914691236517205) })
	_, _, ok := stopping(27)
	uassert.True(t, ok, "an ordinary walk is unaffected")
	out := Render("/6148914691236517205")
	uassert.True(t, strings.Contains(out, "would overflow int64"), out)
	uassert.False(t, strings.Contains(out, "→ 0"), "no wrapped term rendered")
}

package collatz

import (
	"strconv"
	"testing"

	"gno.land/p/nt/uassert/v0"
)

// Anyone may Compute, and each new n is an entry the root page sorts: the
// leaderboard refuses a new n once it is full, and still updates an old one.
func TestLeaderboardIsBounded(cur realm, t *testing.T) {
	var added []string
	for i := 1; results.Size() < MaxResults; i++ {
		k := strconv.Itoa(1_000_000 + i)
		results.Set(k, Result{N: int64(1_000_000 + i)})
		added = append(added, k)
	}
	// One realm state per package run: leave the board as it was found.
	defer func() {
		for _, k := range added {
			results.Remove(k)
		}
	}()
	uassert.AbortsContains(t, cur, "leaderboard is full", func() { Compute(cross(cur), 999_999_937) })
	Compute(cross(cur), 1_000_001) // an n already recorded is refreshed, not refused
}

