	//
	// ## Your own namespace
	//
	// ```
	// gnokey maketx call -pkgpath gno.land/r/moul/x/plan9/ns/v1 \
	//   -func Exec -args 'bind -ac /srv/dev /dev; echo hi > /tmp/f'
