}

// Package crews is small-group coordination you can create in one
// transaction: three to fifteen people with a shared pot, a way to decide, and
// a way to leave with their share.
//
// It is the chain wiring for [gno.land/p/moul/x/social/crew], which holds the
// share math and the proposal state. This realm reads the caller, reads the
// coins attached to the call, asks the engine, and renders the result.
//
//	Create    pay in, and you are the crew's first member
//	Join      pay in at what a share is worth NOW, not at what it cost them
//	Fund      pay in and mint nothing, so every existing share is worth more
//	Propose   any member opens an advisory question
//	Vote      weighted by the shares you hold, changeable while it is open
//	Close     anyone, once the deadline has gone by
//	Ragequit  burn your shares, be credited your slice, leave
//	Withdraw  collect what you were credited
//
// # The shares are the token
//
// There is no second asset to issue. A share is the vote weight and the claim
// on the treasury at the same moment, minted by paying in and burned by
// leaving, so nothing about it is decorative and nobody has to be persuaded it
// is worth something. v0 keeps the shares as an internal ledger rather than one
// GRC20 per crew, because a GRC20 per crew means a realm per crew. A
// transferable share belongs in [gno.land/p/moul/x/social/coin], the sibling
// that refuses to exist until its mint rule, sink and buyer are declared; this
// realm does not import it.
//
// # The custody caveat, which is real
//
// ONE realm address holds EVERY crew's treasury, with per-crew accounting
// inside it. The chain sees one balance; which crew owns which part of it is a
// number in this realm's state. So a bug in the accounting is a bug across
// crews, not inside one: an arithmetic error that over-credits one crew's
// ragequit pays it out of another crew's money, and nothing at the bank layer
// would refuse that transfer.
//
// The fix is the instance-per-realm pattern (EFFECTIVE_GNO.md section 1.4): one
// realm per crew, each holding its own coins at its own address, with this
// package as the shared engine. That is v1. It is not v0 because deploying a
// realm per crew is a publish per crew, which is the opposite of "create it in
// one transaction", and the whole product claim here is the one transaction.
//
// # Payouts are pulled
//
// Nothing is ever pushed. A ragequit credits an internal ledger and the leaver
// calls [Withdraw] themselves, so one address that cannot be paid cannot wedge
// anybody else, and the credit is zeroed before the coins move.
package crews

import (
	"strconv"

	"chain"
	"chain/banker"
	"chain/runtime"

	"gno.land/p/moul/kit/store/v0"
	"gno.land/p/moul/x/envelope/v0"
	"gno.land/p/moul/x/social/crew/v0"
)

// realmPath is this realm's own path, the one its gnomod.toml module line
// declares. It is written out rather than read from the runtime, because every
// plain read this realm exports reports its CALLER and would build every link
// against the wrong realm.
const realmPath = "gno.land/r/moul/x/social/crews/v0"

// denom is the only coin a crew holds. ugnot and nothing else: a treasury that
// can hold several denominations needs a per-denomination share price, which is
// a different product.
const denom = "ugnot"

// IndexCrews is how many crews the index page lists.
const IndexCrews = 20

// crews holds every crew, every proposal and the credit ledger. A redeploy
// wipes it, which is the trade gnomod.toml's private = true makes: see the
// comment there.
var crews = crew.New()

// Create opens a crew and makes the caller its first member.
//
// Send ugnot with the call: the founder's shares are bought out of it at
// crew.InitialPricePerShare, and the whole amount, remainder included, becomes
// the treasury. Returns the new crew's id.
func Create(cur realm, name string) int64 {
	// Both checks have to be here and not behind a helper. cur.IsCurrent()
	// before cur.Previous() is the realm-token rule; IsUserCall before the
	// envelope read is the payment one, because the envelope reports what
	// the SIGNER attached to the transaction and not what reached this
	// realm. Without it a realm the user called keeps the coins and calls
	// in here as many times as it likes, every call reading the same send.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !cur.Previous().IsUserCall() {
		panic("crews: paying in must be a direct user transaction")
	}
	who := cur.Previous().Address()
	amount := envelope.RequireAtLeast(denom, crew.InitialPricePerShare)

	id, err := crews.Create(name, who, amount, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Create",
		"crew", id.String(),
		"founder", who.String(),
		"amount", strconv.FormatInt(amount, 10),
	)
	return int64(id)
}

// Join mints the caller shares at what a share is worth right now and adds what
// they sent to the treasury. Returns the shares minted.
//
// The price is amount * totalShares / treasury, rounded down, so somebody
// joining a crew that has tripled its money pays three times what the founders
// did. Send at least ValuePerShare ugnot, or there is no whole share to mint.
func Join(cur realm, crewID int64) int64 {
	// The two guards every payable call needs; see Create.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !cur.Previous().IsUserCall() {
		panic("crews: paying in must be a direct user transaction")
	}
	who := cur.Previous().Address()
	id := store.ID(crewID)
	c, ok := crews.Get(id)
	if !ok {
		panic(crew.ErrNoCrew.Error())
	}
	amount := envelope.RequireAtLeast(denom, c.PricePerShare())

	shares, err := crews.Join(id, who, amount)
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Join",
		"crew", id.String(),
		"member", who.String(),
		"amount", strconv.FormatInt(amount, 10),
		"shares", strconv.FormatInt(shares, 10),
	)
	return shares
}

// Fund adds what the caller sent to a crew's treasury and mints nothing, so
// every existing share is worth more afterwards.
//
// It is how revenue, a grant or a member topping the pot up arrives. Anyone may
// fund any crew, member or not: there is no way to refuse a transfer on this
// chain anyway, and pretending otherwise would only move the donation to a bank
// send the realm cannot account for.
func Fund(cur realm, crewID int64) int64 {
	// The two guards every payable call needs; see Create.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !cur.Previous().IsUserCall() {
		panic("crews: paying in must be a direct user transaction")
	}
	who := cur.Previous().Address()
	amount := envelope.RequireAtLeast(denom, 1)

	if err := crews.Fund(store.ID(crewID), amount); err != nil {
		panic(err.Error())
	}
	chain.Emit("Fund",
		"crew", store.ID(crewID).String(),
		"from", who.String(),
		"amount", strconv.FormatInt(amount, 10),
	)
	return amount
}

// Propose opens an advisory question on a crew. Any member may propose, and it
// stays open for crew.VoteBlocks blocks. Returns the proposal's id.
//
// A proposal EXECUTES NOTHING. Passing one records that the crew agreed by
// share weight, and moves no coins, changes no membership and binds no code.
// Executing a payout is the next step and it is not in v0.
func Propose(cur realm, crewID int64, text string) int64 {
	who := caller(cur)
	pid, err := crews.Propose(store.ID(crewID), who, text, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Propose",
		"crew", store.ID(crewID).String(),
		"proposal", pid.String(),
		"author", who.String(),
	)
	return int64(pid)
}

// Vote records the caller's ballot, weighted by the shares they hold at this
// moment. One ballot per member, changeable while the proposal is open.
func Vote(cur realm, proposalID int64, yes bool) {
	who := caller(cur)
	pid := store.ID(proposalID)
	if err := crews.Vote(pid, who, yes, runtime.ChainHeight()); err != nil {
		panic(err.Error())
	}
	chain.Emit("Vote",
		"proposal", pid.String(),
		"voter", who.String(),
		"yes", strconv.FormatBool(yes),
	)
}

// Close records a proposal as passed or failed once its deadline has gone by,
// and returns which. Anyone may call it: closing is bookkeeping, not authority.
func Close(cur realm, proposalID int64) bool {
	pid := store.ID(proposalID)
	passed, err := crews.Close(pid, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Close", "proposal", pid.String(), "passed", strconv.FormatBool(passed))
	return passed
}

// Ragequit burns every share the caller holds, credits them their pro-rata
// slice of the treasury and removes them from the crew. Returns the amount
// credited, which [Withdraw] collects.
//
// Nobody has to agree. That is what makes a share mean something: the exit is
// priced by the same number that votes, and a member outvoted on everything can
// still leave with what they put in plus their part of what the crew built.
func Ragequit(cur realm, crewID int64) int64 {
	who := caller(cur)
	id := store.ID(crewID)
	shares, amount, err := crews.Ragequit(id, who)
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Ragequit",
		"crew", id.String(),
		"member", who.String(),
		"shares", strconv.FormatInt(shares, 10),
		"amount", strconv.FormatInt(amount, 10),
	)
	return amount
}

// Withdraw sends the caller everything they have been credited, and returns it.
//
// The credit is zeroed before the coins move, so a reentrant call finds nothing
// left to take. Nothing in this realm ever pushes value: one address that
// cannot be paid must not be able to wedge everybody else.
func Withdraw(cur realm) int64 {
	who := caller(cur)
	amount, err := crews.Withdraw(who)
	if err != nil {
		panic(err.Error())
	}

	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), who, chain.NewCoins(chain.NewCoin(denom, amount)))

	chain.Emit("Withdraw", "payee", who.String(), "amount", strconv.FormatInt(amount, 10))
	return amount
}

// Get returns a crew's name, the height it was created at, how many members it
// has, its total shares and its treasury in ugnot.
//
// Flat values rather than the crew itself: handing out a pointer to live state
// is a mutation handle nothing checks, and a struct is not something a wallet
// can decode anyway.
func Get(crewID int64) (string, int64, int, int64, int64) {
	c, ok := crews.Get(store.ID(crewID))
	if !ok {
		return "", 0, 0, 0, 0
	}
	return c.Name, c.CreatedAt, c.MemberCount(), c.TotalShares, c.Treasury
}

// Count is how many crews exist.
func Count() int { return crews.Len() }

// SharesOf is how many shares who holds in a crew.
func SharesOf(crewID int64, who address) int64 {
	c, _ := crews.Get(store.ID(crewID))
	return c.SharesOf(who)
}

// MemberCount is how many people are in a crew.
func MemberCount(crewID int64) int {
	c, _ := crews.Get(store.ID(crewID))
	return c.MemberCount()
}

// Treasury is what a crew holds, in ugnot. The coins themselves sit at this
// realm's single address: see the package doc on custody.
func Treasury(crewID int64) int64 {
	c, _ := crews.Get(store.ID(crewID))
	if c == nil {
		return 0
	}
	return c.Treasury
}

// ValuePerShare is what one of a crew's shares is worth in ugnot, rounded down.
func ValuePerShare(crewID int64) int64 {
	c, _ := crews.Get(store.ID(crewID))
	return c.ValuePerShare()
}

// ProposalOf returns a proposal's crew, author, text, deadline and whether it
// has been closed and passed.
func ProposalOf(proposalID int64) (int64, address, string, int64, bool, bool) {
	p, ok := crews.Proposal(store.ID(proposalID))
	if !ok {
		return 0, "", "", 0, false, false
	}
	return int64(p.CrewID), p.Author, p.Text, p.Deadline, p.Closed, p.Passed
}

// Tally is a proposal's share-weighted yes and no.
func Tally(proposalID int64) (int64, int64) {
	p, ok := crews.Proposal(store.ID(proposalID))
	if !ok {
		return 0, 0
	}
	return p.Yes, p.No
}

// CreditOf is what an address can withdraw right now, in ugnot.
func CreditOf(who address) int64 { return crews.CreditOf(who) }

// TotalOwed is every outstanding credit, which is the part of this realm's
// balance that belongs to people who have already left.
func TotalOwed() int64 { return crews.TotalOwed() }

// caller is the address that called us, checked the one way that is safe.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	return cur.Previous().Address()
}

package crews

import (
	"strconv"

	"chain/runtime"

	"gno.land/p/moul/kit/num/v0"
	"gno.land/p/moul/kit/store/v0"
	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/realmpath/v0"
	"gno.land/p/moul/x/social/crew/v0"
	"gno.land/p/moul/xmath/v1"
)

// Render routes three views: the index, one crew, and one proposal.
func Render(path string) string {
	req := realmpath.Parse(path)

	switch req.PathPart(0) {
	case "":
		return renderIndex()
	case "crew":
		return renderCrew(req.PathPart(1))
	case "proposal":
		return renderProposal(req.PathPart(1))
	default:
		return md.H1("Not found") + "No such view: " + ui.Inline(req.Path)
	}
}

func renderIndex() string {
	out := md.H1("Crews")
	out += "Three to fifteen people with a shared pot, a way to decide, and a way to " +
		"leave with their share. One transaction to start one.\n\n"

	t := ui.NewTable("crews", "proposals", "owed to people who left")
	t.Row(
		strconv.Itoa(crews.Len()),
		strconv.Itoa(crews.ProposalCount()),
		num.GNOTf(crews.TotalOwed()),
	)
	out += t.String()

	out += md.H2("The crews")
	out += crewTable(crews.List(IndexCrews))

	out += "\n" + ui.Action("Start a crew", "Create", "name", "") + "\n"

	out += md.H2("How a share works")
	out += md.BulletList([]string{
		"A share is the vote weight and the claim on the treasury at once. There is no second token.",
		"Joining mints shares at what a share is worth NOW: " +
			md.InlineCode("amount * totalShares / treasury") +
			", rounded down, so a late joiner cannot buy into value the others built.",
		"Ragequitting burns every share you hold and credits you " +
			md.InlineCode("shares * treasury / totalShares") +
			", rounded down. Nobody has to agree.",
		"Both round in the crew's favour. The last member out holds every share, " +
			"so the treasury still empties to the last ugnot.",
		"A proposal is advisory text. Passing one records agreement and executes nothing.",
	})

	out += md.H2("Custody")
	out += "One realm address holds every crew's treasury, with per-crew accounting " +
		"inside. A bug in that accounting is a bug across crews, not inside one. " +
		"The fix is one realm per crew, and it is v1.\n"

	return out
}

func renderCrew(raw string) string {
	id, ok := store.ParseID(raw)
	if !ok {
		return md.H1("Crews") + "Not a crew id: " + ui.Inline(raw)
	}
	c, found := crews.Get(id)
	if !found {
		return md.H1("Crews") + "No crew #" + id.String()
	}

	out := md.H1(ui.Inline(c.Name))
	out += md.Italic("crew #"+id.String()+" · opened at block "+
		strconv.FormatInt(c.CreatedAt, 10)) + "\n\n"

	t := ui.NewTable("members", "shares", "treasury", "per share")
	t.Row(
		strconv.Itoa(c.MemberCount())+" of "+strconv.Itoa(crew.MaxMembers),
		strconv.FormatInt(c.TotalShares, 10),
		num.GNOTf(c.Treasury),
		num.GNOTf(c.ValuePerShare()),
	)
	out += t.String()

	out += md.H2("Members")
	if c.MemberCount() == 0 {
		out += ui.Empty("Everybody has left. The next member in pays the opening price again.")
	} else {
		m := ui.NewTable("member", "shares", "weight", "worth")
		for _, who := range c.Members() {
			shares := c.SharesOf(who)
			m.Row(
				ui.Addr(who),
				strconv.FormatInt(shares, 10),
				num.Pct(xmath.MulDiv(shares, 10000, c.TotalShares)),
				num.GNOTf(xmath.MulDiv(shares, c.Treasury, c.TotalShares)),
			)
		}
		out += m.String()
	}

	out += md.H2("Proposals")
	out += proposalTable(c.Proposals())
	out += "\nA proposal is advisory text. Passing one records that the crew agreed " +
		"by share weight, and executes nothing.\n"

	out += "\n" + ui.Join(" · ",
		ui.Action("Join", "Join", "crewID", id.String()),
		ui.Action("Fund", "Fund", "crewID", id.String()),
		ui.Action("Propose", "Propose", "crewID", id.String(), "text", ""),
		ui.Action("Ragequit", "Ragequit", "crewID", id.String()),
	) + "\n"
	return out
}

func renderProposal(raw string) string {
	pid, ok := store.ParseID(raw)
	if !ok {
		return md.H1("Crews") + "Not a proposal id: " + ui.Inline(raw)
	}
	p, found := crews.Proposal(pid)
	if !found {
		return md.H1("Crews") + "No proposal #" + pid.String()
	}

	out := md.H1("Proposal #" + pid.String())
	out += md.Blockquote(ui.Inline(p.Text)) + "\n"

	crewName := "crew #" + p.CrewID.String()
	if c, ok := crews.Get(p.CrewID); ok {
		crewName = c.Name
	}
	out += md.Italic("by "+ui.Addr(p.Author)+" · in "+
		md.Link(ui.ShortN(crewName, crew.ExcerptLen, 0), crewURL(p.CrewID))) + "\n\n"

	now := runtime.ChainHeight()
	t := ui.NewTable("state", "yes", "no", "voters")
	t.Row(
		state(p, now),
		strconv.FormatInt(p.Yes, 10),
		strconv.FormatInt(p.No, 10),
		strconv.Itoa(p.Voters()),
	)
	out += t.String()

	if p.Open(now) {
		out += "\n" + ui.Join(" · ",
			ui.Action("Vote yes", "Vote", "proposalID", pid.String(), "yes", "true"),
			ui.Action("Vote no", "Vote", "proposalID", pid.String(), "yes", "false"),
		) + "\n"
	} else if !p.Closed {
		out += "\n" + ui.Action("Close it", "Close", "proposalID", pid.String()) + "\n"
	}
	return out
}

// crewTable lists crews, newest first.
func crewTable(items []crew.Listing) string {
	t := ui.NewTable("crew", "members", "shares", "treasury")
	for _, it := range items {
		t.Row(
			// ShortN truncates without escaping and md.Link escapes what it
			// is given: ui.Inline here would escape twice and render the
			// backslashes. A pipe is what md.Link's escaper does NOT cover,
			// which is why crew.ValidName refuses one at write time.
			md.Link(ui.ShortN(it.Crew.Name, crew.ExcerptLen, 0), crewURL(it.ID)),
			strconv.Itoa(it.Crew.MemberCount()),
			strconv.FormatInt(it.Crew.TotalShares, 10),
			num.GNOTf(it.Crew.Treasury),
		)
	}
	return t.OrEmpty("No crews yet.")
}

// proposalTable lists a crew's proposals, newest first.
//
// The link title is the id and not the text, which is the opposite of
// crewTable and deliberate: a proposal's text is free prose and may contain a
// pipe, md.Link's escaper leaves pipes alone, and a pipe in a link title inside
// a table cell opens a column. So the chrome carries the link and the prose
// goes through ui.Cell, which is the escaper that knows it is in a table.
func proposalTable(ids []store.ID) string {
	now := runtime.ChainHeight()
	t := ui.NewTable("#", "proposal", "state", "yes", "no")
	for i := len(ids) - 1; i >= 0; i-- {
		p, ok := crews.Proposal(ids[i])
		if !ok {
			continue
		}
		t.Row(
			md.Link("#"+ids[i].String(), proposalURL(ids[i])),
			// Cut on a rune boundary first, escape once after: escaping
			// first and cutting after can strand a lone backslash.
			ui.Cell(ui.ShortN(p.Text, crew.ExcerptLen, 0)),
			state(p, now),
			strconv.FormatInt(p.Yes, 10),
			strconv.FormatInt(p.No, 10),
		)
	}
	return t.OrEmpty("Nothing has been proposed yet.")
}

// state is the one word a proposal is in at height now.
func state(p *crew.Proposal, now int64) string {
	switch {
	case p.Open(now):
		return "open until " + strconv.FormatInt(p.Deadline, 10)
	case !p.Closed:
		return "awaiting a close"
	case p.Passed:
		return "passed"
	default:
		return "failed"
	}
}

// crewURL is the gnoweb path of one crew.
func crewURL(id store.ID) string { return realmURL() + ":crew/" + id.String() }

// proposalURL is the gnoweb path of one proposal.
func proposalURL(id store.ID) string { return realmURL() + ":proposal/" + id.String() }

// realmURL is this realm's gnoweb path. The chain domain is the first element
// of a package path and a gnoweb path is the rest of it, so this is a prefix
// strip and not a hostname the realm has to know.
func realmURL() string {
	for i := 0; i < len(realmPath); i++ {
		if realmPath[i] == '/' {
			return realmPath[i:]
		}
	}
	return "/" + realmPath
}

// Package curated is a list anyone can get onto by locking a deposit, and
// anyone can try to get somebody else off by matching that deposit with a bond.
// The loser of the challenge pays the winner.
//
// It is the registry member of a family of small social apps: a list is the
// thing every other one of them eventually needs, and a list is only worth
// reading if being on it cost something.
//
//	Apply(key, url, description)  -send 1000000ugnot   list it, immediately
//	Challenge(key)                -send <the deposit>  object to it
//	Vote(key, keep)                                    while the window is open
//	Resolve(key)                                       anyone, after it closes
//	Unlist(key)                                        the owner, if unchallenged
//	Withdraw()                                         collect what you won
//
// # Money in, money out
//
// Coins arrive in the envelope of a call and sit at this realm's address. They
// never leave by being pushed: a payout is a credit in a ledger and the payee
// calls [Withdraw] for their own. A realm that looped over winners and sent to
// each one would fail entirely when one of them could not be paid, and would
// hand a griefer a cheap denial of service for the price of one entry.
//
// Every ugnot here is therefore either backing a live entry or an open
// challenge, or already assigned to somebody. The realm's own tests assert
// exactly that against the chain balance.
//
// # Voting is sybil-prone, and the bonds are GNOT
//
// [Vote] is one address, one vote, unweighted, and an address is free. Read a
// resolution as "nobody with a stake objected enough", never as a verdict.
// Gating a vote on something harder to manufacture is a different problem with
// its own realm behind it, r/moul/x/social/vouch, a sibling in this family.
//
// Bonds are GNOT and not a token of this list's own: see the README on why
// that is the only answer available at v0 and what would change it.
//
// # What v0 does not do, in the order it should be fixed
//
//  1. Voters are paid nothing. Voting costs gas and returns nothing, so the
//     only two addresses with a reason to vote are the ones with money on the
//     outcome. A share of the loser's stake for the winning side is the
//     standard answer and the first thing to add.
//  2. There is no application period: [Apply] lists immediately.
//  3. A challenge cannot be withdrawn and a vote cannot be changed.
package curated

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"strconv"

	"gno.land/p/moul/x/envelope/v0"
	cu "gno.land/p/moul/x/social/curated/v0"
)

// realmPath is this realm's own path, the one its gnomod.toml module line
// declares. Render builds its links from it rather than from
// unsafe.CurrentRealm(), which in a plain read reports the CALLER.
const realmPath = "gno.land/r/moul/x/social/curated/v0"

const (
	// Denom is what a deposit and a bond are paid in. Native coins, so the
	// amounts are real to a challenger before this list is worth anything.
	Denom = "ugnot"

	// Deposit is what listing costs, and therefore also what challenging one
	// of today's entries costs. One GNOT: enough to make a thousand junk
	// entries a real expense, cheap enough that one honest entry is not a
	// decision.
	Deposit = int64(1000000)

	// ChallengeBlocks is how long a challenge takes to resolve. Long enough
	// for a reader who is not watching the chain to notice and vote, short
	// enough that an entry is not held hostage.
	ChallengeBlocks = int64(1000)
)

// list is every entry and the credit ledger behind them. A redeploy would wipe
// it while leaving the coins at the address, which is what the note in
// gnomod.toml is about.
var list = cu.New(Deposit, ChallengeBlocks)

// Apply lists an entry under key, in exchange for exactly [Deposit] ugnot.
//
// The entry is on the list the moment this returns: there is no application
// period in v0, and the check on a bad entry is that anybody can challenge it.
// The deposit comes back through [Unlist] and [Withdraw] if nobody ever does.
//
// key is a slug: lowercase ASCII letters, digits, '-', '_' and '.', starting
// alphanumeric. A key whose entry was removed is free to apply for again.
func Apply(cur realm, key, url, description string) {
	// Both checks are inlined rather than hidden behind caller(), and in this
	// order. cur.IsCurrent() before cur.Previous() is the realm-token rule;
	// IsUserCall before the envelope read is the payment one, because the
	// envelope reports what the SIGNER attached to the transaction and not
	// what reached this realm. Without it a realm the user called keeps the
	// coins and calls in here as often as it likes, every call reading the
	// same send: that is r/moul/grant Fund, which recorded 5 donations of
	// 1 GNOT from one 1 GNOT send with nothing in the treasury.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !cur.Previous().IsUserCall() {
		panic("curated: paying in must be a direct user transaction")
	}
	who := cur.Previous().Address()
	paid := envelope.RequireExactly(Denom, Deposit)
	if err := list.Apply(key, url, description, who, paid, runtime.ChainHeight()); err != nil {
		panic(err.Error())
	}
	chain.Emit("Apply", "key", key, "owner", who.String(),
		"deposit", strconv.FormatInt(paid, 10))
}

// Challenge objects to an entry, in exchange for a bond equal to that entry's
// own deposit, and opens a vote that closes [ChallengeBlocks] blocks later.
//
// An owner cannot challenge their own entry: it would cost them nothing and
// would make the entry immune to a real challenge for the whole window.
func Challenge(cur realm, key string) {
	// The two guards every payable call needs, inlined; see Apply.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	if !cur.Previous().IsUserCall() {
		panic("curated: paying in must be a direct user transaction")
	}
	who := cur.Previous().Address()
	// The bond is read before the envelope is, so somebody who attaches coins
	// to a challenge of something unchallengeable is told which of the two is
	// wrong.
	bond, ok := list.BondFor(key)
	if !ok {
		panic("curated: " + key + " is not an entry that can be challenged")
	}
	envelope.RequireExactly(Denom, bond)
	if err := list.Challenge(key, who, bond, runtime.ChainHeight()); err != nil {
		panic(err.Error())
	}
	c, _ := list.ChallengeOf(key)
	chain.Emit("Challenge", "key", key, "by", who.String(),
		"bond", strconv.FormatInt(bond, 10),
		"deadline", strconv.FormatInt(c.Deadline, 10))
}

// Vote takes a side on an open challenge: keep the entry, or remove it.
//
// One address, one vote, unweighted, and it cannot be changed. An address is
// free, so this is cheap to manufacture; see the package doc.
func Vote(cur realm, key string, keep bool) {
	who := caller(cur)
	if err := list.Vote(key, who, keep, runtime.ChainHeight()); err != nil {
		panic(err.Error())
	}
	chain.Emit("Vote", "key", key, "by", who.String(), "keep", strconv.FormatBool(keep))
}

// Resolve closes a challenge whose window has passed. Anyone may call it, so
// neither party can stall the other by sitting still.
//
// A majority of keep votes keeps the entry and credits its owner the bond.
// Otherwise the entry is removed and the challenger is credited the bond plus
// the deposit. A tie, including nobody voting at all, keeps the entry: the
// incumbent is the one already at risk, so a challenge that convinced nobody
// loses, which is what makes being wrong cost something.
func Resolve(cur realm, key string) {
	who := caller(cur)
	out, err := list.Resolve(key, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Resolve", "key", key,
		"kept", strconv.FormatBool(out.Kept),
		"winner", out.Winner.String(),
		"amount", strconv.FormatInt(out.Amount, 10),
		"keep", strconv.FormatInt(out.Keep, 10),
		"remove", strconv.FormatInt(out.Remove, 10),
		"by", who.String())
}

// Unlist takes the caller's own entry off the list and credits them the
// deposit back, which [Withdraw] then pays out.
//
// It is refused while a challenge is open: an owner who could walk away
// mid-challenge would be risking nothing, which is the one thing the deposit
// exists to prevent.
func Unlist(cur realm, key string) {
	who := caller(cur)
	if err := list.Unlist(key, who); err != nil {
		panic(err.Error())
	}
	chain.Emit("Unlist", "key", key, "owner", who.String())
}

// Withdraw pays the caller everything credited to them and returns it.
//
// This is the only way coins leave the realm. The credit is zeroed before the
// transfer, so a reentrant call finds nothing left to take.
func Withdraw(cur realm) int64 {
	who := caller(cur)
	amount, err := list.Withdraw(who)
	if err != nil {
		panic(err.Error())
	}
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), who, chain.NewCoins(chain.NewCoin(Denom, amount)))

	chain.Emit("Withdraw", "to", who.String(), "amount", strconv.FormatInt(amount, 10))
	return amount
}

// Get returns what is known about an entry: its URL, its description, its
// owner, the deposit behind it, the height it was listed at, and its state,
// which is one of "listed", "challenged" or "removed".
//
// A key that was never applied for reads as the zero value with an empty
// state, which is how a caller tells it from a removed one.
func Get(key string) (url, description string, owner address, deposit, at int64, state string) {
	e, ok := list.Get(key)
	if !ok {
		return "", "", "", 0, 0, ""
	}
	return e.URL, e.Description, e.Owner, e.Deposit, e.At, e.State.String()
}

// Count is how many entries are on the list right now. A challenged entry
// counts: a challenge is an objection, not a verdict.
func Count() int { return list.Count() }

// Listed is every key on the list, oldest first.
func Listed() []string {
	entries := list.Listed()
	out := make([]string, 0, len(entries))
	for _, e := range entries {
		out = append(out, e.Key)
	}
	return out
}

// IsListed reports whether key is on the list right now.
func IsListed(key string) bool { return list.IsListed(key) }

// ChallengeOf returns the open challenge against key: who opened it, the bond
// they put up, the height voting closes at, the two vote counts, and whether
// there is one at all.
func ChallengeOf(key string) (challenger address, bond, deadline, keep, remove int64, open bool) {
	c, ok := list.ChallengeOf(key)
	if !ok {
		return "", 0, 0, 0, 0, false
	}
	return c.Challenger, c.Bond, c.Deadline, c.Keep, c.Remove, true
}

// CreditOf is what who can collect with [Withdraw] right now.
func CreditOf(who address) int64 { return list.CreditOf(who) }

// caller is the address that called us, checked the one way that is safe.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	return cur.Previous().Address()
}

package curated

import (
	"strings"
	"testing"

	"chain"
	"chain/banker"
	"chain/runtime"

	cu "gno.land/p/moul/x/social/curated/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

var realmAddr = chain.PackageAddress(realmPath)

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
	carol = testutils.TestAddress("carol")
	dave  = testutils.TestAddress("dave")
)

// reset clears realm state. Realm globals live for the whole test binary, so
// every entry, challenge and credit a later test reads starts here. The BANK
// does not carry over the same way, which is why every balance is asserted in
// the test that issued it.
func reset() {
	list = cu.New(Deposit, ChallengeBlocks)
}

// pay credits the realm the way a real transaction would: the runtime deposits
// the envelope at the realm's address, then OriginSend reports it to the
// crossing function.
func pay(amount int64) {
	testing.IssueCoins(realmAddr, chain.Coins{{Denom, amount}})
	testing.SetOriginSend(chain.Coins{{Denom, amount}})
}

// apply lists an entry as who. It crosses immediately after SetRealm, which is
// what makes the account switch take: a helper that sets the realm and does
// not itself cross is silently ignored.
func apply(cur realm, who address, key, url, description string) {
	pay(Deposit)
	testing.SetRealm(testing.NewUserRealm(who))
	Apply(cross(cur), key, url, description)
}

// challenge objects to an entry as who, bonding what that entry's deposit was.
func challenge(cur realm, who address, key string) {
	_, _, _, bond, _, _ := Get(key)
	pay(bond)
	testing.SetRealm(testing.NewUserRealm(who))
	Challenge(cross(cur), key)
}

// balance is what addr holds on chain right now.
func balance(addr address) int64 {
	return banker.NewReadonlyBanker().GetCoins(addr).AmountOf(Denom)
}

func TestApplyTakesExactlyTheDepositAndListsAtOnce(cur realm, t *testing.T) {
	reset()

	// Underpaying and overpaying are both refused: a realm that silently kept
	// the excess would have invented a fee nobody agreed to.
	pay(Deposit - 1)
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsContains(t, cur, "costs exactly", func() {
		Apply(cross(cur), "gnoswap", "https://gnoswap.io", "an AMM")
	})
	pay(Deposit + 1)
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsContains(t, cur, "costs exactly", func() {
		Apply(cross(cur), "gnoswap", "https://gnoswap.io", "an AMM")
	})
	uassert.Equal(t, 0, Count())

	apply(cur, alice, "gnoswap", "https://gnoswap.io", "an AMM on gno.land")

	url, description, owner, deposit, at, state := Get("gnoswap")
	uassert.Equal(t, "https://gnoswap.io", url)
	uassert.Equal(t, "an AMM on gno.land", description)
	uassert.Equal(t, alice.String(), owner.String())
	uassert.Equal(t, Deposit, deposit)
	uassert.Equal(t, runtime.ChainHeight(), at)
	uassert.Equal(t, "listed", state)

	uassert.True(t, IsListed("gnoswap"))
	uassert.Equal(t, 1, Count())
	urequire.Equal(t, 1, len(Listed()))
	uassert.Equal(t, "gnoswap", Listed()[0])

	// A key that was never applied for reads as the empty state.
	_, _, _, _, _, state = Get("nothing")
	uassert.Equal(t, "", state)
	uassert.False(t, IsListed("nothing"))
}

func TestApplyRefusesAKeyAlreadyOnTheList(cur realm, t *testing.T) {
	reset()
	apply(cur, alice, "gnoswap", "https://gnoswap.io", "an AMM")

	pay(Deposit)
	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsContains(t, cur, "already on the list", func() {
		Apply(cross(cur), "gnoswap", "https://mine.io", "mine now")
	})

	pay(Deposit)
	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsContains(t, cur, "not a key", func() {
		Apply(cross(cur), "GnoSwap", "https://mine.io", "mine now")
	})
	uassert.Equal(t, 1, Count())
}

func TestChallengeMatchesTheDepositAndOpensAVote(cur realm, t *testing.T) {
	reset()
	apply(cur, alice, "gnoswap", "https://gnoswap.io", "an AMM")

	// Not a bond, not an entry: the entry is checked before the money is.
	pay(Deposit)
	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsContains(t, cur, "is not an entry that can be challenged", func() {
		Challenge(cross(cur), "nothing")
	})

	// An owner shielding their own entry would cost them nothing.
	pay(Deposit)
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsContains(t, cur, "cannot challenge their own entry", func() {
		Challenge(cross(cur), "gnoswap")
	})

	opened := runtime.ChainHeight()
	challenge(cur, bob, "gnoswap")

	challenger, bond, deadline, keep, remove, open := ChallengeOf("gnoswap")
	urequire.True(t, open, "the challenge is readable")
	uassert.Equal(t, bob.String(), challenger.String())
	uassert.Equal(t, Deposit, bond)
	uassert.Equal(t, opened+ChallengeBlocks, deadline)
	uassert.Equal(t, int64(0), keep)
	uassert.Equal(t, int64(0), remove)
	uassert.True(t, IsListed("gnoswap"), "a challenge is an objection, not a verdict")

	// One address, one vote, and only while the window is open.
	testing.SetRealm(testing.NewUserRealm(carol))
	Vote(cross(cur), "gnoswap", false)
	testing.SetRealm(testing.NewUserRealm(carol))
	uassert.AbortsContains(t, cur, "one address, one vote", func() {
		Vote(cross(cur), "gnoswap", true)
	})

	testing.SkipHeights(ChallengeBlocks)
	testing.SetRealm(testing.NewUserRealm(dave))
	uassert.AbortsContains(t, cur, "deadline has passed", func() {
		Vote(cross(cur), "gnoswap", true)
	})
}

// The full round, with the coins checked against the chain rather than against
// the realm's own books.
func TestResolveRemovesAnEntryAndPaysTheChallenger(cur realm, t *testing.T) {
	reset()
	apply(cur, alice, "gnoswap", "https://gnoswap.io", "an AMM")
	challenge(cur, bob, "gnoswap")
	uassert.Equal(t, 2*Deposit, balance(realmAddr), "both stakes are at the realm")

	testing.SetRealm(testing.NewUserRealm(carol))
	Vote(cross(cur), "gnoswap", false)
	testing.SetRealm(testing.NewUserRealm(dave))
	Vote(cross(cur), "gnoswap", false)

	testing.SetRealm(testing.NewUserRealm(carol))
	uassert.AbortsContains(t, cur, "still open", func() { Resolve(cross(cur), "gnoswap") })

	testing.SkipHeights(ChallengeBlocks)
	// Anyone may settle it, including somebody with nothing on the outcome.
	testing.SetRealm(testing.NewUserRealm(carol))
	Resolve(cross(cur), "gnoswap")

	uassert.False(t, IsListed("gnoswap"))
	uassert.Equal(t, 0, Count())
	uassert.Equal(t, 2*Deposit, CreditOf(bob), "the bond back, plus alice's deposit")
	uassert.Equal(t, int64(0), CreditOf(alice))
	uassert.Equal(t, int64(0), CreditOf(carol), "voters are paid nothing in v0")
	uassert.Equal(t, 2*Deposit, balance(realmAddr), "credited is not sent")

	before := balance(bob)
	testing.SetRealm(testing.NewUserRealm(bob))
	got := Withdraw(cross(cur))
	uassert.Equal(t, 2*Deposit, got)
	uassert.Equal(t, before+2*Deposit, balance(bob), "the coins actually arrived")
	uassert.Equal(t, int64(0), balance(realmAddr), "and the realm kept nothing")

	// A second call, which is what a reentrant one would be, finds nothing.
	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsContains(t, cur, "nothing to withdraw", func() { Withdraw(cross(cur)) })
}

func TestATieKeepsTheEntryAndPaysTheOwner(cur realm, t *testing.T) {
	reset()
	apply(cur, alice, "gnoswap", "https://gnoswap.io", "an AMM")
	challenge(cur, bob, "gnoswap")

	testing.SetRealm(testing.NewUserRealm(carol))
	Vote(cross(cur), "gnoswap", true)
	testing.SetRealm(testing.NewUserRealm(dave))
	Vote(cross(cur), "gnoswap", false)

	testing.SkipHeights(ChallengeBlocks)
	testing.SetRealm(testing.NewUserRealm(bob))
	Resolve(cross(cur), "gnoswap")

	uassert.True(t, IsListed("gnoswap"), "the incumbent wins ties")
	uassert.Equal(t, Deposit, CreditOf(alice), "and takes the challenger's bond")
	uassert.Equal(t, int64(0), CreditOf(bob))

	// Her own deposit is still locked behind the entry, so only the bond is
	// collectable until she unlists.
	before := balance(alice)
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.Equal(t, Deposit, Withdraw(cross(cur)))
	uassert.Equal(t, before+Deposit, balance(alice))
	uassert.Equal(t, Deposit, balance(realmAddr), "the deposit stays behind the entry")
}

// Nobody voting is a tie too, which is the common case and the one that
// decides whether a challenge is cheap. It is not: it costs the bond.
func TestAChallengeNobodyVotedOnLoses(cur realm, t *testing.T) {
	reset()
	apply(cur, alice, "gnoswap", "https://gnoswap.io", "an AMM")
	challenge(cur, bob, "gnoswap")

	testing.SkipHeights(ChallengeBlocks)
	testing.SetRealm(testing.NewUserRealm(bob))
	Resolve(cross(cur), "gnoswap")

	uassert.True(t, IsListed("gnoswap"))
	uassert.Equal(t, Deposit, CreditOf(alice))
	uassert.Equal(t, int64(0), CreditOf(bob), "being wrong costs the bond")
}

func TestUnlistIsTheOwnersAndNotWhileChallenged(cur realm, t *testing.T) {
	reset()
	apply(cur, alice, "gnoswap", "https://gnoswap.io", "an AMM")

	testing.SetRealm(testing.NewUserRealm(bob))
	uassert.AbortsContains(t, cur, "only the entry's owner", func() {
		Unlist(cross(cur), "gnoswap")
	})

	challenge(cur, bob, "gnoswap")
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsContains(t, cur, "under challenge", func() {
		Unlist(cross(cur), "gnoswap")
	})
	uassert.Equal(t, int64(0), CreditOf(alice), "she cannot walk away mid-challenge")

	testing.SkipHeights(ChallengeBlocks)
	testing.SetRealm(testing.NewUserRealm(alice))
	Resolve(cross(cur), "gnoswap")
	testing.SetRealm(testing.NewUserRealm(alice))
	Unlist(cross(cur), "gnoswap")

	uassert.False(t, IsListed("gnoswap"))
	uassert.Equal(t, 2*Deposit, CreditOf(alice), "the bond she won, and her deposit back")

	// The key is free again, and re-listing it costs a fresh deposit.
	apply(cur, bob, "gnoswap", "https://mine.io", "mine now")
	_, _, owner, _, _, state := Get("gnoswap")
	uassert.Equal(t, bob.String(), owner.String())
	uassert.Equal(t, "listed", state)
}

// The realm holds exactly what it is accountable for, at every step: a stake
// behind something live, or a credit somebody has not collected yet.
func TestTheRealmHoldsExactlyWhatItOwes(cur realm, t *testing.T) {
	reset()
	check := func(step string) {
		t.Helper()
		uassert.Equal(t, list.Locked()+list.Owed(), balance(realmAddr), step)
	}
	check("empty")

	apply(cur, alice, "one", "https://1.io", "first")
	check("after a listing")

	apply(cur, bob, "two", "https://2.io", "second")
	check("after a second listing")

	challenge(cur, bob, "one")
	check("after a challenge")

	testing.SetRealm(testing.NewUserRealm(carol))
	Vote(cross(cur), "one", false)
	check("after a vote")

	testing.SkipHeights(ChallengeBlocks)
	testing.SetRealm(testing.NewUserRealm(carol))
	Resolve(cross(cur), "one")
	check("after a resolution")

	testing.SetRealm(testing.NewUserRealm(bob))
	Withdraw(cross(cur))
	check("after the winner collected")

	testing.SetRealm(testing.NewUserRealm(bob))
	Unlist(cross(cur), "two")
	check("after an unlisting")

	testing.SetRealm(testing.NewUserRealm(bob))
	Withdraw(cross(cur))
	check("after the deposit came back")
	uassert.Equal(t, int64(0), balance(realmAddr), "and the realm is empty again")
}

// A URL is caller-supplied too, and it is the one string that reaches the
// renderer as a link target rather than as text.
func TestAPipeInAUrlCannotOpenAColumn(cur realm, t *testing.T) {
	reset()
	apply(cur, alice, "weird", "https://x.io/a|b", "a url with a pipe in it")

	index := Render("")
	uassert.False(t, strings.Contains(index, "https://x.io/a|b"),
		"the raw pipe would open a column: "+index)
	uassert.True(t, strings.Contains(index, "https://x.io/a%7Cb"),
		"the link sanitizer percent-encodes it: "+index)
}

// TestRender uses uassert rather than an Example because every view contains
// consecutive blank lines, which gno collapses inside an // Output: block.
func TestRender(cur realm, t *testing.T) {
	reset()
	apply(cur, alice, "gnoswap", "https://gnoswap.io/pools?a=1", "an AMM | with [a link](x)")

	index := Render("")
	uassert.True(t, strings.Contains(index, "# Curated"), index)
	uassert.True(t, strings.Contains(index, "| 1 | 0 |"), "one listed, none challenged: "+index)
	uassert.True(t, strings.Contains(index, "func=Apply"), "the index offers the transaction")
	uassert.True(t, strings.Contains(index, "Voters are paid nothing"), "the index says what v0 does not do")
	uassert.True(t, strings.Contains(index, "an AMM \\| with \\[a link\\]\\(x\\)"),
		"a pipe in a description cannot open a column, and its markdown is inert: "+index)

	entry := Render("entry/gnoswap")
	uassert.True(t, strings.Contains(entry, "# gnoswap"), entry)
	uassert.True(t, strings.Contains(entry, "an AMM | with \\[a link\\]\\(x\\)"),
		"the description is escaped in prose too, where a pipe is not special: "+entry)
	uassert.True(t, strings.Contains(entry, "func=Challenge"))
	uassert.True(t, strings.Contains(entry, "func=Unlist"))

	// Under challenge the page offers the two votes instead.
	challenge(cur, bob, "gnoswap")
	entry = Render("entry/gnoswap")
	uassert.True(t, strings.Contains(entry, "## Under challenge"), entry)
	uassert.True(t, strings.Contains(entry, "keep=true"), entry)
	uassert.True(t, strings.Contains(entry, "keep=false"), entry)
	uassert.False(t, strings.Contains(entry, "func=Unlist"), "an owner cannot walk away here either")
	uassert.True(t, strings.Contains(Render(""), "## Open challenges"))

	testing.SetRealm(testing.NewUserRealm(carol))
	Vote(cross(cur), "gnoswap", false)
	testing.SetRealm(testing.NewUserRealm(dave))
	Vote(cross(cur), "gnoswap", false)

	// Past the deadline it offers the settlement instead of the votes.
	testing.SkipHeights(ChallengeBlocks)
	entry = Render("entry/gnoswap")
	uassert.True(t, strings.Contains(entry, "func=Resolve"), entry)
	uassert.False(t, strings.Contains(entry, "keep=true"), "voting is over: "+entry)

	// Removed, the key is advertised as free again.
	testing.SetRealm(testing.NewUserRealm(bob))
	Resolve(cross(cur), "gnoswap")

	entry = Render("entry/gnoswap")
	uassert.True(t, strings.Contains(entry, "free to apply for again"), entry)
	uassert.True(t, strings.Contains(Render(""), "Nothing is on the list yet."))

	uassert.Equal(t, "# Curated\nNo entry named nope", Render("entry/nope"))
	uassert.True(t, strings.HasPrefix(Render("elsewhere"), "# Not found"))
}

// A realm that forwards a user's call must not be able to spend the user's
// envelope as if it were its own. OriginSend reports what the SIGNER attached
// to the transaction, so without the IsUserCall guard a realm that received
// one GNOT could call in here repeatedly, each call reading the same send and
// listing another entry for free. That is r/moul/grant Fund, and gnovet's
// origin-send-unguarded rule caught this exact shape here in CI after the
// local gate had passed.
func TestOnlyAUserCanPayIn(cur realm, t *testing.T) {
	reset()

	pay(Deposit)
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/g1relay/forwarder"))
	uassert.AbortsContains(t, cur, "must be a direct user transaction", func() {
		Apply(cross(cur), "relayed", "/r/x", "paid with somebody else's coins")
	})
	uassert.Equal(t, 0, Count(), "nothing was listed")

	apply(cur, alice, "real", "/r/real", "a real entry")

	pay(Deposit)
	testing.SetRealm(testing.NewCodeRealm("gno.land/r/g1relay/forwarder"))
	uassert.AbortsContains(t, cur, "must be a direct user transaction", func() {
		Challenge(cross(cur), "real")
	})
	_, _, _, _, _, open := ChallengeOf("real")
	uassert.False(t, open, "no challenge was opened")
}

package curated

import (
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/p/moul/kit/num/v0"
	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/realmpath/v0"
	"gno.land/p/moul/txlink/v0"
	cu "gno.land/p/moul/x/social/curated/v0"
)

// Render routes two views: the list itself, and one entry.
//
// A key never contains a slash, so "entry/<key>" is a prefix strip rather than
// a path element that would have to be rejoined.
func Render(path string) string {
	req := realmpath.Parse(path)

	switch {
	case strings.HasPrefix(req.Path, "entry/"):
		return renderEntry(strings.TrimPrefix(req.Path, "entry/"))
	case req.Path == "":
		return renderIndex()
	default:
		return md.H1("Not found") + "No such view: " + ui.Inline(req.Path)
	}
}

func renderIndex() string {
	out := md.H1("Curated")
	out += "A list you pay to be on, and can be paid for getting somebody off. " +
		"The deposit does not make an entry good: it makes a bad one expensive " +
		"to leave standing, because anybody who disagrees can put the same " +
		"amount at risk and take it.\n\n"

	open := list.Challenged()

	t := ui.NewTable("on the list", "open challenges", "deposit", "window", "locked", "credited")
	t.Row(
		strconv.Itoa(list.Count()),
		strconv.Itoa(len(open)),
		num.GNOTf(Deposit),
		strconv.FormatInt(ChallengeBlocks, 10)+" blocks",
		num.GNOTf(list.Locked()),
		num.GNOTf(list.Owed()),
	)
	out += t.String()

	out += md.H2("The list")
	out += listing(list.Listed())
	out += "\n" + md.Link("➕ Apply for "+num.GNOTf(Deposit), applyURL()) + "\n"

	if len(open) > 0 {
		out += md.H2("Open challenges")
		out += challengeTable(open)
	}

	out += md.H2("How it works")
	out += md.BulletList([]string{
		"**Apply** locks " + num.GNOTf(Deposit) + " and lists the entry immediately. " +
			"There is no application period in v0.",
		"**Challenge** matches that entry's deposit with a bond and opens a vote " +
			"for " + strconv.FormatInt(ChallengeBlocks, 10) + " blocks. An owner cannot challenge their own entry.",
		"**Vote** is one address, one vote, unweighted. An address is free, so read " +
			"a resolution as nobody with a stake objecting, never as a verdict.",
		"**Resolve** can be called by anyone once the window closes. A majority to " +
			"keep credits the owner the bond; otherwise the challenger takes the bond " +
			"and the deposit. A tie keeps the entry, so a challenge that convinced " +
			"nobody loses its bond.",
		"**Voters are paid nothing** in v0, which is the first thing to fix: the only " +
			"two addresses with a reason to vote are the ones with money on the outcome.",
		"**Nothing is ever sent to you.** Every payout is a credit, and " +
			md.InlineCode("Withdraw()") + " collects it.",
	})

	return out
}

func renderEntry(key string) string {
	e, ok := list.Get(key)
	if !ok {
		return md.H1("Curated") + "No entry named " + ui.Inline(key)
	}

	out := md.H1(ui.Inline(e.Key))
	out += md.Blockquote(ui.Inline(e.Description)) + "\n"
	// ShortN truncates without escaping and md.Link escapes what it is given:
	// ui.Inline here would escape twice and render the backslashes.
	out += md.Link(ui.ShortN(e.URL, 60, 0), e.URL) + "\n\n"

	t := ui.NewTable("owner", "deposit", "listed at", "state")
	t.Row(
		ui.Addr(e.Owner),
		num.GNOTf(e.Deposit),
		"block "+strconv.FormatInt(e.At, 10),
		e.State.String(),
	)
	out += t.String()

	c, challenged := list.ChallengeOf(e.Key)
	switch {
	case challenged:
		out += md.H2("Under challenge")
		out += challengeTable([]*cu.Entry{e})
		if c.Open(runtime.ChainHeight()) {
			out += "\n" + ui.Action("👍 Keep", "Vote", "key", e.Key, "keep", "true") +
				" · " + ui.Action("👎 Remove", "Vote", "key", e.Key, "keep", "false") + "\n"
		} else {
			out += "\n" + ui.Action("⚖️ Resolve", "Resolve", "key", e.Key) +
				" · the window has closed and anyone can settle it\n"
		}
	case e.Live():
		out += "\n" + md.Link("🚩 Challenge for "+num.GNOTf(e.Deposit), challengeURL(e.Key, e.Deposit)) +
			" · " + ui.Action("🗑 Unlist", "Unlist", "key", e.Key) + "\n"
	default:
		out += "\n" + ui.Empty("Off the list. The key is free to apply for again.")
		out += md.Link("➕ Apply for "+num.GNOTf(Deposit), applyURL()) + "\n"
	}

	return out
}

// listing renders the entries as the list itself: the key links to its page,
// the description links to the thing it describes.
func listing(entries []*cu.Entry) string {
	if len(entries) == 0 {
		return ui.Empty("Nothing is on the list yet.")
	}
	t := ui.NewTable("key", "what", "link", "owner", "since", "state")
	for _, e := range entries {
		mark := ""
		if e.State == cu.StateChallenged {
			mark = " 🚩"
		}
		t.Row(
			// A key is charset-validated, so md.Link's escaping is the whole
			// story for it. A description is not: md.Link escapes markdown
			// but NOT the pipe, which in a cell would open a column, so the
			// description is never a link title here. Cut first with ShortN,
			// which does not escape, then escape once with ui.Cell.
			md.Link(ui.ShortN(e.Key, 32, 0), entryURL(e.Key)),
			ui.Cell(ui.ShortN(e.Description, 48, 0)),
			md.Link("↗", e.URL),
			ui.Addr(e.Owner),
			"block "+strconv.FormatInt(e.At, 10),
			e.State.String()+mark,
		)
	}
	return t.String()
}

// challengeTable renders the open challenge against each of entries. An entry
// with none is skipped rather than shown blank.
func challengeTable(entries []*cu.Entry) string {
	t := ui.NewTable("entry", "challenger", "bond", "keep", "remove", "voting closes")
	now := runtime.ChainHeight()
	for _, e := range entries {
		c, ok := list.ChallengeOf(e.Key)
		if !ok {
			continue
		}
		closes := "block " + strconv.FormatInt(c.Deadline, 10)
		if !c.Open(now) {
			closes = "closed, awaiting `Resolve`"
		}
		t.Row(
			md.Link(ui.ShortN(e.Key, 32, 0), entryURL(e.Key)),
			ui.Addr(c.Challenger),
			num.GNOTf(c.Bond),
			strconv.FormatInt(c.Keep, 10),
			strconv.FormatInt(c.Remove, 10),
			closes,
		)
	}
	return t.OrEmpty("No challenge is open.")
}

// entryURL is the gnoweb path of one entry's page.
//
// The chain domain is the first element of a package path and a gnoweb path is
// the rest of it, so this is a prefix strip and not a hostname to hardcode.
func entryURL(key string) string {
	path := realmPath
	if i := strings.Index(path, "/"); i >= 0 {
		path = path[i:]
	}
	return path + ":entry/" + key
}

// applyURL is the Apply form with the deposit already attached, so a reader
// never has to work out what -send should say.
func applyURL() string {
	return txlink.NewLink("Apply").SetSend(send(Deposit)).URL()
}

// challengeURL is the same for Challenge, carrying that entry's own bond.
func challengeURL(key string, bond int64) string {
	return txlink.NewLink("Challenge").AddArgs("key", key).SetSend(send(bond)).URL()
}

func send(amount int64) string { return strconv.FormatInt(amount, 10) + Denom }

// Package patron is recurring support for a builder, on chain.
//
// A creator opens a plan with a price per period and a period measured in
// blocks. A supporter attaches ugnot to [Subscribe] and buys whole periods of
// it. Anybody can ask at any height whether a given address is still active,
// which is the one question a tip cannot answer.
//
// # There is no cron on chain, so a renewal is a pull and not a push
//
// Nothing in this realm can charge anybody. A renewal happens because the
// supporter sends another payment, never because a timer fired: there is no
// scheduler here, and there is no way to write one, since a native coin
// cannot be pulled at all. A reader arriving from web2 expects a standing
// mandate on a card and there is nothing of the kind, anywhere on this chain.
//
// # What this adds over the tip jar
//
// gno.land/r/moul/x/daily/tipjar is the one-shot version and is already live:
// one payment, a leaderboard, and then nothing. The recurrence is the whole
// difference. A plan has a price and a period, a payment buys whole periods
// of it, renewing early never discards time already paid for, and the realm
// answers "is this address active right now" at any height. It is the one app
// in the x/social family that produces a recurring write rather than a
// one-off.
//
// # Earnings are credited at payment time, not streamed
//
// The creator can withdraw the full price the instant it is paid. A supporter
// who stops being active is NOT refunded, and no part of a paid period ever
// comes back. That is a deliberate v0 limitation: escrowed streaming, where
// the creator claims only what has elapsed and the supporter cancels and
// reclaims the rest, needs a claim schedule and a refund path, and that is a
// larger realm than this one rather than a flag on it.
//
// # Money leaves by pull
//
// Both halves of what this realm owes, a creator's earnings and a supporter's
// change, land in one credit ledger and leave through [Withdraw]. The credit
// is zeroed before any coin moves, and the realm never loops over payees: one
// unpayable address would otherwise fail the whole batch and hand a griefer a
// cheap denial of service.
//
// # v0 ships no token
//
// Deliberately, and the README says why: a creator coin minted per period
// paid is easy, and the sink is not, because what it would be redeemed for is
// a promise made off chain.
package patron

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"strconv"

	"gno.land/p/moul/kit/store/v0"
	"gno.land/p/moul/x/envelope/v0"
	pt "gno.land/p/moul/x/social/patron/v0"
)

// realmPath is this realm's own path, the one its gnomod.toml module line
// declares. It is written out rather than read from the frame, because a
// plain read exported by a realm reports the CALLER and would build every
// link against whoever asked.
const realmPath = "gno.land/r/moul/x/social/patron/v0"

// denom is the only coin this realm handles.
const denom = "ugnot"

// plans holds every plan and the credit ledger. A redeploy wipes it, which is
// the trade `private = true` makes: see gnomod.toml.
var plans = pt.NewRegistry()

// Open creates a plan and returns its id. Anyone may open one, and opening
// one costs nothing beyond gas and the storage deposit.
//
// pricePerPeriod is in ugnot and must be at least one: a free plan is a tip
// jar, not a subscription. periodBlocks is a period in BLOCKS, bounded both
// ways by the engine, because height is the clock consensus agrees on and a
// block timestamp is not something to build a billing cliff out of.
func Open(cur realm, title, description string, pricePerPeriod, periodBlocks int64) int64 {
	who := caller(cur)
	id, err := plans.Open(who, title, description, pricePerPeriod, periodBlocks)
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Open",
		"id", id.String(),
		"creator", who.String(),
		"price", strconv.FormatInt(pricePerPeriod, 10),
		"period", strconv.FormatInt(periodBlocks, 10))
	return int64(id)
}

// Subscribe buys whole periods on a plan with the ugnot attached to the call,
// and returns the caller's new paid-through height.
//
// Attach the coins with -send: a payment short of one period is refused, and
// the remainder under one period is credited back to the caller rather than
// kept, so an overpayment is change and never a silent fee. Take it back with
// [Withdraw].
//
// # It has to be called directly by a user, and that is not a style choice
//
// The envelope is what the SIGNER attached to the transaction. A realm the
// user called has already received those coins itself, and could then call in
// here as many times as it liked against one payment, so the caller is
// checked before the envelope is read. The same property means a realm cannot
// forward an envelope it was handed (`NewBanker` requires the previous frame
// to be a user call), and that `maketx run` cannot reach this function at all,
// because a run script is itself a code realm. Use `maketx call -send`.
func Subscribe(cur realm, planID int64) int64 {
	// The frame is read here rather than through caller(), because this
	// function asks the previous frame two questions and the order of them is
	// the whole guard: is the token live, is the caller a user, and only then
	// what did they send.
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("patron: Subscribe must be called directly by a user with maketx call -send, " +
			"not through another realm and not from maketx run")
	}
	who := prev.Address()

	id := store.ID(planID)
	p := mustGet(id)
	if !p.Open {
		panic(pt.ErrPlanClosed.Error())
	}

	// RequireAtLeast names both numbers when the envelope falls short, which
	// is the difference between a caller fixing their command and a caller
	// opening their wallet.
	sent := envelope.RequireAtLeast(denom, p.PricePerPeriod)

	pay, err := plans.Subscribe(id, who, sent, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Subscribe",
		"id", id.String(),
		"supporter", who.String(),
		"periods", strconv.FormatInt(pay.Periods, 10),
		"spent", strconv.FormatInt(pay.Spent, 10),
		"change", strconv.FormatInt(pay.Change, 10),
		"paidThrough", strconv.FormatInt(pay.PaidThrough, 10))
	return pay.PaidThrough
}

// Close stops a plan taking new subscriptions. Creator only.
//
// Everything already paid for runs to its own paid-through height. Closing a
// plan is not a way to take a period back.
func Close(cur realm, planID int64) {
	who := caller(cur)
	id := store.ID(planID)
	if err := plans.Close(id, who); err != nil {
		panic(err.Error())
	}
	chain.Emit("Close", "id", id.String(), "by", who.String())
}

// Reopen lets a closed plan take subscriptions again. Creator only.
func Reopen(cur realm, planID int64) {
	who := caller(cur)
	id := store.ID(planID)
	if err := plans.Reopen(id, who); err != nil {
		panic(err.Error())
	}
	chain.Emit("Reopen", "id", id.String(), "by", who.String())
}

// Withdraw pays the caller everything this realm owes them and returns the
// amount: a creator's earnings, a supporter's change, or both at once.
//
// The credit is zeroed by the engine before a coin moves, so a recipient that
// calls straight back in finds nothing left to take.
func Withdraw(cur realm) int64 {
	who := caller(cur)
	amount, err := plans.Withdraw(who)
	if err != nil {
		panic(err.Error())
	}
	banker.NewBanker(banker.BankerTypeRealmSend, cur).SendCoins(
		cur.Address(), who, chain.NewCoins(chain.NewCoin(denom, amount)))
	chain.Emit("Withdraw", "to", who.String(), "amount", strconv.FormatInt(amount, 10))
	return amount
}

// Get returns a plan's fields.
//
// It returns a tuple rather than the stored record: handing out a pointer to
// realm state is a live mutation handle, and this realm is private, so an
// importer retaining one of its objects would be a runtime panic rather than
// a design debate.
func Get(planID int64) (creator address, title, description string, pricePerPeriod, periodBlocks int64, open bool) {
	p := mustGet(store.ID(planID))
	return p.Creator, p.Title, p.Description, p.PricePerPeriod, p.PeriodBlocks, p.Open
}

// Count is how many plans exist.
func Count() int { return plans.Count() }

// IsActive reports whether who is paid up on this plan at the current height.
//
// Active means now < paidThrough, strictly: an address paid through height h
// is active at h-1 and not at h.
func IsActive(planID int64, who address) bool {
	return mustGet(store.ID(planID)).IsActive(who, runtime.ChainHeight())
}

// PaidThrough is the height who stops being active at on this plan, or zero
// if they never paid.
func PaidThrough(planID int64, who address) int64 {
	return mustGet(store.ID(planID)).PaidThrough(who)
}

// SupporterCount is how many distinct addresses have ever paid this plan,
// active or not.
func SupporterCount(planID int64) int {
	return mustGet(store.ID(planID)).SupporterCount()
}

// Supporters is every address that has ever paid this plan, in first-payment
// order. It is a copy, not the stored slice.
func Supporters(planID int64) []address {
	return mustGet(store.ID(planID)).Supporters()
}

// EarnedBy is the lifetime ugnot credited to creator across every plan,
// whether or not it has been withdrawn.
func EarnedBy(creator address) int64 { return plans.EarnedBy(creator) }

// CreditOf is what addr can withdraw right now.
func CreditOf(addr address) int64 { return plans.CreditOf(addr) }

// TotalOwed is everything this realm owes, which is what it must keep in
// reserve at its own address.
func TotalOwed() int64 { return plans.TotalOwed() }

// mustGet reads a plan or aborts naming it.
func mustGet(id store.ID) *pt.Plan {
	p, ok := plans.Get(id)
	if !ok {
		panic("patron: plan #" + id.String() + " not found")
	}
	return p
}

// caller is the address that called us, checked the one way that is safe.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	return cur.Previous().Address()
}

package patron

import (
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/p/moul/kit/num/v0"
	"gno.land/p/moul/kit/store/v0"
	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/realmpath/v0"
	"gno.land/p/moul/txlink/v0"
	pt "gno.land/p/moul/x/social/patron/v0"
)

// pageSize is how many plans the index lists at once.
const pageSize = 20

// titleWidth is how much of a plan's title a listing shows.
const titleWidth = 40

// Render routes two views: the index and one plan.
func Render(path string) string {
	req := realmpath.Parse(path)

	switch {
	case strings.HasPrefix(req.Path, "plan/"):
		return renderPlan(strings.TrimPrefix(req.Path, "plan/"))
	case req.Path == "":
		return renderIndex(req)
	default:
		return md.H1("Not found") + "No such view: " + ui.Inline(req.Path)
	}
}

func renderIndex(req *realmpath.Request) string {
	now := runtime.ChainHeight()

	out := md.H1("Patron")
	out += "Recurring support for a builder. A creator opens a plan with a price per " +
		"period and a period measured in blocks, and a supporter buys whole periods of " +
		"it with " + md.InlineCode("ugnot") + ".\n\n"
	out += md.Blockquote("There is no cron on chain, so a renewal is a pull and not a " +
		"push: nothing here can charge anybody. A supporter renews by paying again, and " +
		"renewing early never loses time already paid for.") + "\n"

	stats := ui.NewTable("plans", "owed to creators and supporters", "block")
	stats.Row(
		strconv.Itoa(plans.Count()),
		num.GNOTf(plans.TotalOwed()),
		strconv.FormatInt(now, 10),
	)
	out += stats.String()

	out += md.H2("Plans")
	out += planTable(plans.List(pageNum(req), pageSize), now)

	out += "\n" + ui.Action("➕ Open a plan", "Open",
		"title", "", "description", "", "pricePerPeriod", "", "periodBlocks", "") +
		" · " + ui.Action("💰 Withdraw what I am owed", "Withdraw") + "\n"

	out += md.H2("What it does not do")
	out += md.BulletList([]string{
		"**It does not charge anybody.** A renewal is a payment the supporter signs.",
		"**It does not stream.** A creator is credited the whole price at the moment " +
			"it is paid, so a supporter who stops being active is not refunded and no " +
			"part of a paid period comes back. Escrowed streaming needs a claim " +
			"schedule and a refund path, which is the v1.",
		"**It does not issue a token.** Minting a creator coin per period paid is " +
			"easy; the sink is not, because what it would be redeemed for is a promise " +
			"made off chain.",
	})

	return out
}

func renderPlan(raw string) string {
	id, ok := store.ParseID(raw)
	if !ok {
		return md.H1("Patron") + "Not a plan id: " + ui.Inline(raw)
	}
	p, found := plans.Get(id)
	if !found {
		return md.H1("Patron") + "No plan #" + id.String()
	}
	now := runtime.ChainHeight()

	out := md.H1("Plan #" + id.String() + ": " + ui.Inline(p.Title))
	if p.Description != "" {
		out += md.Blockquote(ui.Inline(p.Description)) + "\n"
	}

	status := "open"
	if !p.Open {
		status = "closed to new subscriptions"
	}
	facts := ui.NewTable("creator", "price per period", "period", "status")
	facts.Row(
		ui.Addr(p.Creator),
		num.GNOTf(p.PricePerPeriod),
		strconv.FormatInt(p.PeriodBlocks, 10)+" blocks",
		status,
	)
	out += facts.String()

	if p.Open {
		// The link carries the send amount, so the price is not something a
		// supporter has to copy out of the table and retype.
		out += md.Link(
			"💜 Support for one period ("+num.GNOTf(p.PricePerPeriod)+")",
			txlink.Realm(realmPath).NewLink("Subscribe").
				AddArgs("planID", id.String()).
				SetSend(strconv.FormatInt(p.PricePerPeriod, 10)+denom).
				URL(),
		) + "\n\n"
		out += "Paying " + md.InlineCode("n") + " times the price buys " +
			md.InlineCode("n") + " periods at once. Anything left over under one " +
			"period is credited back to you, not kept: take it with " +
			md.InlineCode("Withdraw") + ".\n"
	} else {
		out += ui.Empty("This plan takes no new subscriptions. Anything already paid " +
			"for runs to its own block.")
	}

	out += md.H2("Supporters")
	out += supporterTable(p, now)

	out += md.H2("Creator")
	out += "Earned across every plan: " + md.Bold(num.GNOTf(plans.EarnedBy(p.Creator))) +
		" · withdrawable now: " + md.Bold(num.GNOTf(plans.CreditOf(p.Creator))) + "\n\n"
	out += ui.Action("🚪 Close", "Close", "planID", id.String()) +
		" · " + ui.Action("🔓 Reopen", "Reopen", "planID", id.String()) +
		" · " + ui.Action("💰 Withdraw", "Withdraw") + "\n\n"
	out += md.Link("← every plan", pt.RealmURL(realmPath)) + "\n"

	return out
}

// planTable lists plans.
//
// The link text is the plan NUMBER and not its title, which is the one thing
// to copy from here. md.Link escapes its text with the inline escaper, and the
// inline escaper does not touch a pipe, because a pipe means nothing in a
// sentence: a user title carried inside a link inside a table cell therefore
// still opens a column. So the title gets its own cell and goes through
// ui.Cell, which is the escaper that knows it is in a table. It is truncated
// first with ui.ShortN, which does not escape, so the cut can never strand a
// backslash that the escaper had just inserted.
func planTable(items []pt.Listing, now int64) string {
	t := ui.NewTable("#", "plan", "creator", "per period", "period", "supporters", "")
	for _, it := range items {
		mark := "🟢"
		if !it.Plan.Open {
			mark = "🔒"
		}
		t.Row(
			md.Link(it.ID.String(), pt.PlanURL(realmPath, it.ID)),
			ui.Cell(ui.ShortN(it.Plan.Title, titleWidth, 0)),
			ui.Addr(it.Plan.Creator),
			num.GNOTf(it.Plan.PricePerPeriod),
			strconv.FormatInt(it.Plan.PeriodBlocks, 10)+" blocks",
			strconv.Itoa(it.Plan.ActiveCount(now))+" of "+strconv.Itoa(it.Plan.SupporterCount()),
			mark,
		)
	}
	return t.OrEmpty("No plans yet.")
}

func supporterTable(p *pt.Plan, now int64) string {
	t := ui.NewTable("supporter", "paid through block", "active")
	for _, who := range p.Supporters() {
		active := "no"
		if p.IsActive(who, now) {
			active = "yes"
		}
		t.Row(ui.Addr(who), strconv.FormatInt(p.PaidThrough(who), 10), active)
	}
	return t.OrEmpty("Nobody supports this plan yet.")
}

// pageNum reads ?page= and falls back to the first page for anything it
// cannot read, which is the only answer a Render can give: there is nobody to
// report an error to.
func pageNum(req *realmpath.Request) int {
	n, err := strconv.Atoi(req.Query.Get("page"))
	if err != nil || n < 1 {
		return 1
	}
	return n
}

package threads

import (
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/p/moul/kit/store/v0"
	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/realmpath/v0"
	th "gno.land/p/moul/x/social/threads/v0"
)

// Render routes three views: the realm's own index, one page's threads, and
// one thread.
//
// A page key contains slashes, so "page/<key>" is split on the prefix rather
// than by path element: realmpath gives the parts, and rejoining them would
// only be a way to get it wrong.
func Render(path string) string {
	req := realmpath.Parse(path)

	switch {
	case strings.HasPrefix(req.Path, "page/"):
		return renderPage(strings.TrimPrefix(req.Path, "page/"))
	case strings.HasPrefix(req.Path, "thread/"):
		return renderThread(strings.TrimPrefix(req.Path, "thread/"))
	case req.Path == "":
		return renderIndex()
	default:
		return md.H1("Not found") + "No such view: " + ui.Inline(req.Path)
	}
}

func renderIndex() string {
	out := md.H1("Threads")
	out += "A discussion block any realm can embed, keyed on the page it appears on.\n\n"

	t := ui.NewTable("threads", "pages", "THREAD supply")
	t.Row(strconv.Itoa(board.Len()), strconv.Itoa(board.Pages()), strconv.FormatInt(points.Supply(), 10))
	out += t.String()

	out += md.H2("Recent, across every page")
	out += listing(board.Recent(20), true)

	out += md.H2("The token")
	out += points.Render()

	out += md.H2("Embedding it")
	out += "Two lines in the host realm, and it stores nothing:\n\n"
	out += md.LanguageCodeBlock("go", `import "`+realmPath+`"

func Render(path string) string {
	return body + threads.RenderBlock()
}`)
	out += "The page key is the host realm's own path, read off the call. " +
		md.InlineCode("RenderBlockFor(page)") + " names one explicitly.\n"

	return out
}

func renderPage(page string) string {
	if !th.ValidPage(page) {
		return md.H1("Threads") + "Not a page key: " + ui.Inline(page)
	}
	out := md.H1("Threads on " + ui.Inline(page))
	out += md.Link("the page itself", th.RealmURL(page)) + "\n\n"
	out += listing(board.List(page, runtime.ChainHeight(), 0), false)
	out += "\n" + ui.Action("💬 Post here", "Post", "page", page, "body", "") + "\n"
	return out
}

func renderThread(raw string) string {
	id, ok := store.ParseID(raw)
	if !ok {
		return md.H1("Threads") + "Not a thread id: " + ui.Inline(raw)
	}
	t, found := board.Get(id)
	if !found {
		return md.H1("Threads") + "No thread #" + id.String()
	}

	out := md.H1("Thread #" + id.String())
	out += md.Blockquote(ui.Inline(t.Body)) + "\n"
	out += md.Italic("by "+ui.Addr(t.Author)+" · on "+
		md.Link(t.Page, th.PageURL(realmPath, t.Page))+
		" · "+strconv.Itoa(t.Repliers())+" earned") + "\n\n"

	if t.PinnedUntil > runtime.ChainHeight() {
		out += "📌 pinned until block " + strconv.FormatInt(t.PinnedUntil, 10) + "\n\n"
	}

	out += md.H2("Replies")
	if len(t.Replies) == 0 {
		out += ui.Empty("Nobody has replied yet.")
	} else {
		r := ui.NewTable("by", "said", "block")
		for _, rep := range t.Replies {
			r.Row(ui.Addr(rep.Author), ui.Cell(rep.Body), strconv.FormatInt(rep.At, 10))
		}
		out += r.String()
	}

	out += "\n" + ui.Action("💬 Reply", "Reply", "threadID", id.String(), "body", "") +
		" · " + ui.Action("📌 Boost", "Boost", "threadID", id.String()) + "\n"
	return out
}

// listing renders a set of threads. withPage adds the page column, which the
// index needs and a page view would only repeat.
func listing(items []th.Listing, withPage bool) string {
	if len(items) == 0 {
		return ui.Empty("No threads yet.")
	}
	headers := []string{"", "#", "thread", "by", "replies"}
	if withPage {
		headers = append(headers, "page")
	}
	t := ui.NewTable(headers...)
	now := runtime.ChainHeight()
	for _, it := range items {
		mark := ""
		if it.Thread.Pinned(now) {
			mark = "📌"
		}
		cells := []string{
			mark,
			// The link title is the id, never the body: md.Link escapes
			// markdown but not a pipe, and a pipe in a table cell opens a
			// column. ui.Cell is the only thing that rewrites it.
			md.Link("#"+it.ID.String(), th.ThreadURL(realmPath, it.ID)),
			ui.Cell(ui.ShortN(it.Thread.Body, th.ExcerptLen, 0)),
			ui.Addr(it.Thread.Author),
			strconv.Itoa(len(it.Thread.Replies)),
		}
		if withPage {
			cells = append(cells, ui.Cell(it.Thread.Page))
		}
		t.Row(cells...)
	}
	return t.String()
}

// Package threads is a discussion block any realm can embed, keyed on the page
// it appears on rather than on the realm that stores it.
//
// It is the text half of gno.land/r/moul/reactions: the same embed shape, the
// same page keys, two lines in the host realm.
//
//	import "gno.land/r/moul/x/social/threads/v0"
//
//	func Render(path string) string {
//		return body + threads.RenderBlock()
//	}
//
// [RenderBlock] takes no argument because it does not need one: a plain read
// exported by a realm and called by another opens no realm frame, so
// unsafe.CurrentRealm() inside it reports the CALLER. The host realm's own
// path is the page key, and nothing has to be configured or registered.
// [RenderBlockFor] is the explicit form, for a realm that renders more than
// one page or already holds its path as a constant.
//
// # The token, and the three things it has to answer
//
// THREAD exists because placement is the one thing a discussion has that
// people want and cannot all have at once.
//
//	mint   1 THREAD to a thread's author, the first time each distinct
//	       address replies to it. People, not messages, and never yourself.
//	sink   [Boost] burns PinCost THREAD to pin a thread to the top of its
//	       page for PinBlocks blocks. That is the only thing that removes
//	       supply, and the only thing the token does.
//	buyer  anyone who wants placement and has not earned it. They have to
//	       acquire THREAD from someone who did, with [Transfer], which is
//	       what makes attention a market rather than a scoreboard.
//
// It is farmable, and saying so is cheaper than pretending otherwise: two
// addresses replying to each other mint one THREAD each per thread. The fix is
// a gate on who counts as a replier, which belongs in a vouching realm and not
// here; until then the cost of farming is one transaction per point and the
// benefit is capped by what a pin is worth.
package threads

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"

	"gno.land/p/moul/kit/store/v0"
	sc "gno.land/p/moul/x/social/coin/v0"
	th "gno.land/p/moul/x/social/threads/v0"
	"gno.land/r/nt/grc20reg/v0"
)

// realmPath is this realm's own path, the one its gnomod.toml module line
// declares. It is written out rather than read from unsafe.CurrentRealm(),
// which reports the CALLER in every plain read this realm exports and would
// therefore build every link against whichever realm embedded the block.
const realmPath = "gno.land/r/moul/x/social/threads/v0"

const (
	// EarnPerReplier is minted to a thread's author the first time each
	// distinct address replies to it.
	EarnPerReplier = int64(1)

	// PinCost is burned by Boost, and PinBlocks is how long the pin lasts.
	// A pin extends from whichever is later, now or the current pin, so
	// buying one never shortens somebody else's.
	PinCost   = int64(10)
	PinBlocks = int64(1000)

	// BlockThreads is how many threads an embedded block shows before it
	// turns into a link to the full page.
	BlockThreads = 5
)

var (
	// board holds every thread. A redeploy would wipe it, which is why this
	// realm is not private (see gnomod.toml).
	board = th.NewBoard()

	// points is the THREAD ledger. The Coin is unexported on purpose: it
	// carries unrestricted mint and burn, and an exported pointer to it
	// would hand both to any importer.
	points *sc.Coin

	// tokenKey is the r/nt/grc20reg lookup key, which is how a realm that
	// does not import this one refers to THREAD.
	tokenKey string
)

// tokenPolicy is the three declarations THREAD is issued under. It is a var
// and not three literals inside init so that the tests, which rebuild the
// ledger between cases, issue the same token the chain holds.
var tokenPolicy = sc.Policy{
	Mint:  "1 to a thread's author per distinct address that replies to it",
	Sink:  "burned by Boost to pin a thread to the top of its page",
	Buyer: "anyone who wants placement and has not earned it",
}

func init(cur realm) {
	points = sc.New("Thread Points", "THREAD", 0, 0, tokenPolicy, 0, cur)
	tokenKey = grc20reg.Register(cross(cur), points.Token(), "thread")
}

// Post opens a thread under page.
//
// page is a package path, the full one: "gno.land/r/moul/home". It does not
// have to be a realm that embeds the block, and nothing checks that it exists.
// A page is just a name, which is what lets a realm key discussion on
// something finer than itself.
func Post(cur realm, page, body string) int64 {
	who := caller(cur)
	id, err := board.Post(page, who, body, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Post", "id", id.String(), "page", page, "author", who.String())
	return int64(id)
}

// Reply appends to a thread.
//
// The first time each distinct address replies to a given thread, its author
// earns EarnPerReplier. Replying again earns nothing, and replying to your own
// thread never earns anything.
func Reply(cur realm, threadID int64, body string) {
	who := caller(cur)
	id := store.ID(threadID)
	isNew, err := board.Reply(id, who, body, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Reply", "id", id.String(), "author", who.String())

	if isNew {
		t, _ := board.Get(id)
		points.Earn(t.Author, EarnPerReplier)
		chain.Emit("Earn", "id", id.String(), "author", t.Author.String())
	}
}

// Boost burns PinCost THREAD from the caller and pins the thread to the top of
// its page for PinBlocks blocks.
//
// Anyone may boost anyone's thread. The pin is on the thread and not on the
// buyer, so the thing being sold is placement and not authorship.
func Boost(cur realm, threadID int64) {
	who := caller(cur)
	id := store.ID(threadID)
	t, ok := board.Get(id)
	if !ok {
		panic(th.ErrNoThread.Error())
	}

	now := runtime.ChainHeight()
	from := now
	if t.PinnedUntil > from {
		from = t.PinnedUntil
	}
	// Charge first, pin second. The chain would revert both on an abort, so
	// the order is invisible on mainnet and load-bearing everywhere else: a
	// test, a filetest and any future caller that recovers see a refused
	// boost that pinned nothing.
	points.Spend(who, PinCost)
	if err := board.Pin(id, from+PinBlocks); err != nil {
		panic(err.Error())
	}
	chain.Emit("Boost", "id", id.String(), "by", who.String(),
		"until", strconv.FormatInt(from+PinBlocks, 10))
}

// Transfer moves the caller's own THREAD. It is what makes the sink a market:
// somebody who wants a pin and has written nothing has to buy from an author.
func Transfer(cur realm, to address, amount int64) {
	if err := points.CallerTeller().Transfer(0, cur, to, amount); err != nil {
		panic(err.Error())
	}
}

// Approve lets spender draw amount of the caller's THREAD.
func Approve(cur realm, spender address, amount int64) {
	if err := points.CallerTeller().Approve(0, cur, spender, amount); err != nil {
		panic(err.Error())
	}
}

// TransferFrom spends an allowance the caller was granted.
func TransferFrom(cur realm, from, to address, amount int64) {
	if err := points.CallerTeller().TransferFrom(0, cur, from, to, amount); err != nil {
		panic(err.Error())
	}
}

// RenderBlock returns the block for the realm CALLING it, which is the form a
// host realm embeds.
//
// It has no cur realm parameter on purpose. A plain read is borrowed: gno
// opens no realm frame for it, so unsafe.CurrentRealm() reports the caller's
// path and the block keys itself with no argument. Adding a cur realm here
// would silently reverse that and key every embed to this realm instead.
func RenderBlock() string {
	return blockFor(unsafe.CurrentRealm().PkgPath())
}

// RenderBlockFor is [RenderBlock] for a named page. Use it from a crossing
// function, where there is no caller to read off the stack, or when one realm
// renders several pages.
func RenderBlockFor(page string) string { return blockFor(page) }

// blockFor is the shared body, so no exported read of this realm calls another
// and picks up the wrong path.
func blockFor(page string) string {
	now := runtime.ChainHeight()
	return th.Block(realmPath, page, board.List(page, now, BlockThreads), board.PageLen(page), now)
}

// Count is how many threads a page holds.
func Count(page string) int { return board.PageLen(page) }

// Total is how many threads exist, across every page.
func Total() int { return board.Len() }

// Pages is how many pages have ever been posted on.
func Pages() int { return board.Pages() }

// Repliers is how many distinct addresses have replied to a thread, which is
// also how much its author has earned from it.
func Repliers(threadID int64) int {
	t, _ := board.Get(store.ID(threadID))
	return t.Repliers()
}

// PinnedUntil is the height a thread stops being pinned at, or 0.
func PinnedUntil(threadID int64) int64 {
	t, ok := board.Get(store.ID(threadID))
	if !ok {
		return 0
	}
	return t.PinnedUntil
}

// BalanceOf is an address's THREAD balance.
func BalanceOf(owner address) int64 { return points.BalanceOf(owner) }

// Allowance is what owner let spender draw.
func Allowance(owner, spender address) int64 {
	return points.Token().Allowance(owner, spender)
}

// TotalSupply is the THREAD in existence: everything earned, less everything
// burned by Boost.
func TotalSupply() int64 { return points.Supply() }

// TokenKey is the r/nt/grc20reg key for THREAD.
func TokenKey() string { return tokenKey }

// caller is the address that called us, checked the one way that is safe.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	return cur.Previous().Address()
}

package threads

import (
	"strconv"
	"strings"
	"testing"

	sc "gno.land/p/moul/x/social/coin/v0"
	th "gno.land/p/moul/x/social/threads/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
	"gno.land/p/nt/urequire/v0"
)

const homePage = "gno.land/r/moul/home"

var (
	alice = testutils.TestAddress("alice")
	bob   = testutils.TestAddress("bob")
	carol = testutils.TestAddress("carol")
)

// reset clears realm state. Realm globals live for the whole test binary, so
// everything a later test reads, including the ledger, starts here.
//
// The ledger is rebuilt through a same-realm cross because grc20.NewToken
// needs a code-realm frame, which a test's EOA-origin cur is not. It is NOT
// re-registered with grc20reg: the registry is another realm and its entry
// survives this one's state.
func reset(cur realm) {
	board = th.NewBoard()
	func(cur realm) { // the name is forced: a realm argument must be called cur
		points = sc.New("Thread Points", "THREAD", 0, 0, tokenPolicy, 0, cur)
	}(cross(cur))
}

// earn gives who n THREAD the only way the realm allows: n distinct addresses
// replying to a thread they wrote.
func earn(cur realm, t *testing.T, who address, n int) int64 {
	t.Helper()
	testing.SetRealm(testing.NewUserRealm(who))
	id := Post(cross(cur), homePage, "a thread by "+who.String())
	for i := 0; i < n; i++ {
		testing.SetRealm(testing.NewUserRealm(testutils.TestAddress("replier" + strconv.Itoa(i))))
		Reply(cross(cur), id, "hello")
	}
	return id
}

func TestAnAuthorEarnsPeopleAndNotMessages(cur realm, t *testing.T) {
	reset(cur)

	testing.SetRealm(testing.NewUserRealm(alice))
	id := Post(cross(cur), homePage, "first thread")
	uassert.Equal(t, int64(0), BalanceOf(alice), "writing earns nothing on its own")

	testing.SetRealm(testing.NewUserRealm(bob))
	Reply(cross(cur), id, "nice")
	uassert.Equal(t, int64(1), BalanceOf(alice))

	testing.SetRealm(testing.NewUserRealm(bob))
	Reply(cross(cur), id, "still me")
	uassert.Equal(t, int64(1), BalanceOf(alice), "one person is one point, however much they say")

	testing.SetRealm(testing.NewUserRealm(alice))
	Reply(cross(cur), id, "thanks")
	uassert.Equal(t, int64(1), BalanceOf(alice), "replying to yourself is not an audience")

	testing.SetRealm(testing.NewUserRealm(carol))
	Reply(cross(cur), id, "hi")
	uassert.Equal(t, int64(2), BalanceOf(alice))

	uassert.Equal(t, 2, Repliers(id))
	uassert.Equal(t, int64(2), TotalSupply())
	uassert.Equal(t, int64(0), BalanceOf(bob), "a replier earns nothing")
}

func TestBoostIsTheOnlyThingThatBurns(cur realm, t *testing.T) {
	reset(cur)
	id := earn(cur, t, alice, 10)
	urequire.Equal(t, int64(10), BalanceOf(alice))

	testing.SetRealm(testing.NewUserRealm(alice))
	Boost(cross(cur), id)

	uassert.Equal(t, int64(0), BalanceOf(alice))
	uassert.Equal(t, int64(0), TotalSupply(), "the sink removes supply, it does not move it")
	uassert.Equal(t, int64(123+PinBlocks), PinnedUntil(id), "tests start at height 123")
}

func TestBoostRefusesWhatTheCallerCannotAfford(cur realm, t *testing.T) {
	reset(cur)
	id := earn(cur, t, alice, 1)

	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsContains(t, cur, "balance 1 is short of 10", func() {
		Boost(cross(cur), id)
	})
	uassert.Equal(t, int64(0), PinnedUntil(id), "a refused boost pins nothing")
	uassert.Equal(t, int64(1), BalanceOf(alice))
}

// A second boost extends from the current pin, not from now, so the thread
// never loses time it was already paid for.
func TestASecondBoostExtendsRatherThanRestarts(cur realm, t *testing.T) {
	reset(cur)
	id := earn(cur, t, alice, 20)

	testing.SetRealm(testing.NewUserRealm(alice))
	Boost(cross(cur), id)
	first := PinnedUntil(id)

	testing.SetRealm(testing.NewUserRealm(alice))
	Boost(cross(cur), id)
	uassert.Equal(t, first+PinBlocks, PinnedUntil(id))
	uassert.Equal(t, int64(0), BalanceOf(alice))
}

// Anyone may boost anyone's thread, and the buyer has to get THREAD from
// somebody who earned it. That is the whole market.
func TestPlacementIsBoughtFromAnEarner(cur realm, t *testing.T) {
	reset(cur)
	id := earn(cur, t, alice, 10)

	testing.SetRealm(testing.NewUserRealm(alice))
	Transfer(cross(cur), bob, 10)
	uassert.Equal(t, int64(0), BalanceOf(alice))
	uassert.Equal(t, int64(10), BalanceOf(bob))

	testing.SetRealm(testing.NewUserRealm(bob))
	Boost(cross(cur), id)
	uassert.True(t, PinnedUntil(id) > 0, "bob pinned alice's thread")
	uassert.Equal(t, int64(0), TotalSupply())
}

func TestPostRefusals(cur realm, t *testing.T) {
	reset(cur)
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsContains(t, cur, "not a page key", func() {
		Post(cross(cur), "nopath", "body")
	})
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsContains(t, cur, "body is empty", func() {
		Post(cross(cur), homePage, "   ")
	})
	testing.SetRealm(testing.NewUserRealm(alice))
	uassert.AbortsContains(t, cur, "no such thread", func() {
		Reply(cross(cur), 99, "into the void")
	})
	uassert.Equal(t, 0, Total())
}

func TestCountsAreScopedToTheirPage(cur realm, t *testing.T) {
	reset(cur)
	testing.SetRealm(testing.NewUserRealm(alice))
	Post(cross(cur), homePage, "on home")
	testing.SetRealm(testing.NewUserRealm(alice))
	Post(cross(cur), "gno.land/r/moul/blog", "on the blog")

	uassert.Equal(t, 1, Count(homePage))
	uassert.Equal(t, 0, Count("gno.land/r/nobody/here"))
	uassert.Equal(t, 2, Total())
	uassert.Equal(t, 2, Pages())
}

// RenderBlockFor is the embed, and it escapes what it shows: a raw pipe in a
// body would otherwise open a column in the host realm's page.
func TestRenderBlockForEscapesTheBody(cur realm, t *testing.T) {
	reset(cur)
	testing.SetRealm(testing.NewUserRealm(alice))
	Post(cross(cur), homePage, "a | pipe")

	got := RenderBlockFor(homePage)
	uassert.True(t, strings.Contains(got, "func=Post"), "the block offers the transaction: "+got)
	uassert.True(t, strings.Contains(got, `| a \| pipe |`),
		"the body cell escapes the pipe rather than opening a column: "+got)
	uassert.False(t, strings.Contains(got, "| a | pipe"), "no raw pipe survives: "+got)
	uassert.True(t, strings.Contains(RenderBlockFor("gno.land/r/nobody/here"), "No discussion yet."))
}

// TestRender uses uassert rather than an Example because every view contains
// consecutive blank lines, which gno collapses inside an // Output: block.
func TestRender(cur realm, t *testing.T) {
	reset(cur)
	testing.SetRealm(testing.NewUserRealm(alice))
	id := Post(cross(cur), homePage, "a thread about [links](x)")
	testing.SetRealm(testing.NewUserRealm(bob))
	Reply(cross(cur), id, "a reply with a | pipe")

	index := Render("")
	uassert.True(t, strings.Contains(index, "| 1 | 1 | 1 |"), "threads, pages, supply: "+index)
	uassert.True(t, strings.Contains(index, tokenPolicy.Sink), "the index declares the sink")
	uassert.True(t, strings.Contains(index, `import "`+realmPath+`"`), "the index is the embed doc")

	page := Render("page/" + homePage)
	uassert.True(t, strings.Contains(page, "/r/moul/home"), "it links the page itself: "+page)
	uassert.True(t, strings.Contains(page, "func=Post"))

	sid := strconv.FormatInt(id, 10)
	thread := Render("thread/" + sid)
	uassert.True(t, strings.Contains(thread, "# Thread #"+sid))
	uassert.True(t, strings.Contains(thread, "a thread about \\[links\\]\\(x\\)"),
		"the body is escaped where it is shown: "+thread)
	uassert.True(t, strings.Contains(thread, "a reply with a \\| pipe"),
		"a reply cell cannot open a column: "+thread)
	uassert.True(t, strings.Contains(thread, "func=Boost"))

	uassert.Equal(t, "# Threads\nNo thread #4242", Render("thread/4242"))
	uassert.Equal(t, "# Threads\nNot a thread id: nope", Render("thread/nope"))
	uassert.Equal(t, "# Threads\nNot a page key: nope", Render("page/nope"))
	uassert.True(t, strings.HasPrefix(Render("elsewhere"), "# Not found"))
}

func TestTokenIsDiscoverableWithoutImportingThisRealm(t *testing.T) {
	uassert.True(t, strings.HasSuffix(TokenKey(), ".THREAD"), TokenKey())
	uassert.True(t, strings.Contains(TokenKey(), realmPath), TokenKey())
}

package vouch

import (
	"strconv"

	"gno.land/p/moul/kit/num/v0"
	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/realmpath/v0"
	vo "gno.land/p/moul/x/social/vouch/v0"
)

// Render routes two views: the realm's own index, and one address's page.
//
// An address carries no slash, so the per-address route is a path element and
// not a prefix strip.
func Render(path string) string {
	req := realmpath.Parse(path)

	switch req.PathPart(0) {
	case "":
		return renderIndex()
	case "addr":
		return renderAddr(req.PathPart(1))
	default:
		return md.H1("Not found") + "No such view: " + ui.Inline(req.Path)
	}
}

func renderIndex() string {
	out := md.H1("Vouch")
	out += "A web of trust other realms gate on. One address vouches for another, " +
		"in writing, optionally with GNOT locked behind it.\n\n"

	t := ui.NewTable("vouches", "people vouched for", "bonded", "awaiting withdrawal")
	t.Row(
		strconv.Itoa(graph.Count()),
		strconv.Itoa(graph.People()),
		num.GNOTf(graph.TotalBonded()),
		num.GNOTf(graph.TotalOwed()),
	)
	out += t.String()

	out += md.H2("Most vouched for")
	out += board()

	out += md.H2("The gate")
	out += "One line in the realm that wants it, and it costs no transaction:\n\n"
	out += md.LanguageCodeBlock("go", `import "`+realmPath+`"

if !vouch.IsTrusted(addr, 2) {
	panic("get two people to vouch for you first")
}`)
	out += md.Italic("A score counts distinct vouchers, so restating a vouch does not " +
		"raise it and revoking lowers it. It does not count distinct people: a pair " +
		"vouching for each other both reach one, which is why a real gate asks for " +
		"more.") + "\n\n"

	out += md.H2("Take part")
	out += ui.Action("\U0001F91D Vouch", "Vouch", "target", "", "reason", "") +
		" · " + ui.Action("\U0001F4B0 Withdraw a refunded bond", "Withdraw") + "\n\n"
	out += md.Italic("Coins sent with Vouch are locked as a bond on that vouch and come " +
		"back when you revoke it. There is no slashing: deciding that a vouch was a lie " +
		"needs an arbiter, and choosing one is the whole design question.") + "\n"

	return out
}

func board() string {
	rows := graph.Leaderboard(BoardSize)
	if len(rows) == 0 {
		return ui.Empty("Nobody has been vouched for yet.")
	}
	t := ui.NewTable("", "address", "vouchers", "bonded")
	for i, r := range rows {
		t.Row(
			ui.Podium(i),
			md.Link(ui.AddrText(r.Addr), vo.AddrURL(realmPath, r.Addr)),
			strconv.Itoa(r.Score),
			num.GNOTf(r.Bonded),
		)
	}
	return t.String()
}

func renderAddr(raw string) string {
	addr := address(raw)
	if !addr.IsValid() {
		return md.H1("Vouch") + "Not an address: " + ui.Inline(raw)
	}

	out := md.H1("Vouch for " + ui.AddrText(addr))
	out += ui.AddrFull(addr) + "\n\n"

	score := graph.ScoreOf(addr)
	t := ui.NewTable("vouchers", "bonded on them", "trusted at 2", "awaiting withdrawal")
	t.Row(
		strconv.Itoa(score),
		num.GNOTf(graph.BondedFor(addr)),
		yesno(graph.IsTrusted(addr, 2)),
		num.GNOTf(graph.Owed(addr)),
	)
	out += t.String()

	out += md.H2("Vouched for by")
	out += inbound(addr)

	out += md.H2("Vouches for")
	out += outbound(addr)

	out += "\n" + ui.Action("\U0001F91D Vouch for this address", "Vouch",
		"target", addr.String(), "reason", "") +
		" · " + ui.Action("\U0000274C Revoke mine", "Revoke", "target", addr.String()) + "\n"
	return out
}

func inbound(addr address) string {
	from := graph.VouchedBy(addr)
	if len(from) == 0 {
		return ui.Empty("Nobody vouches for this address.")
	}
	t := ui.NewTable("voucher", "reason", "bond", "mutual", "since")
	for _, f := range from {
		v, ok := graph.Get(f, addr)
		if !ok {
			continue
		}
		t.Row(
			md.Link(ui.AddrText(f), vo.AddrURL(realmPath, f)),
			ui.Cell(v.Reason),
			num.GNOTf(v.Bond),
			yesno(graph.Mutual(f, addr)),
			strconv.FormatInt(v.At, 10),
		)
	}
	return t.String()
}

func outbound(addr address) string {
	to := graph.VouchesOf(addr)
	if len(to) == 0 {
		return ui.Empty("This address vouches for nobody.")
	}
	t := ui.NewTable("for", "reason", "bond", "their vouchers")
	for _, target := range to {
		v, ok := graph.Get(addr, target)
		if !ok {
			continue
		}
		t.Row(
			md.Link(ui.AddrText(target), vo.AddrURL(realmPath, target)),
			ui.Cell(v.Reason),
			num.GNOTf(v.Bond),
			strconv.Itoa(graph.ScoreOf(target)),
		)
	}
	return t.String()
}

func yesno(b bool) string {
	if b {
		return "yes"
	}
	return "no"
}

// Package vouch is a web of trust other realms can gate on: one address
// vouches for another, in writing, optionally with GNOT locked behind it.
//
// The one call that matters is a plain read:
//
//	import "gno.land/r/moul/x/social/vouch/v0"
//
//	func Claim(cur realm) {
//		if !vouch.IsTrusted(cur.Previous().Address(), 2) {
//			panic("get two people to vouch for you first")
//		}
//		…
//	}
//
// [IsTrusted] takes no cur realm on purpose. A read with no realm token is
// borrowed: gno opens no realm frame for it, so it costs the caller nothing
// beyond the read and cannot be tricked into acting as anybody. Nothing here
// branches on who is asking, and no read in this realm ever will: the answer
// to "is this address trusted" must not depend on who wants to know.
//
// # What it does, and what it refuses to do
//
// [Vouch] is payable. Any coins sent with it are locked as a bond on that
// vouch, which is the voucher putting their own money where their claim is. A
// bond is optional and zero is the ordinary case. [Revoke] takes the vouch
// back and credits the bond to the voucher, who collects it with [Withdraw].
//
// There is no slashing in v0 and that is the interesting half. Slashing needs
// an arbiter, somebody who decides a vouch was a lie, and every candidate is
// a design question rather than a feature: a DAO vote is a popularity contest,
// a challenge market pays whoever is loudest, an oracle is one key that can
// confiscate anybody's money. The bond is still worth having without it,
// because an illiquid deposit is a cost a hundred throwaway addresses cannot
// all pay at once.
//
// # No token
//
// This realm issues none, deliberately. A transferable vouch is a bought
// reputation, and the moment a vouch can be sold the score stops measuring
// what it says it measures. The bond is GNOT: value at risk, without being a
// market in trust itself. The README says what would change the answer.
package vouch

import (
	"chain"
	"chain/banker"
	"chain/runtime"
	"strconv"

	"gno.land/p/moul/x/envelope/v0"
	vo "gno.land/p/moul/x/social/vouch/v0"
)

// realmPath is this realm's own path, the one its gnomod.toml module line
// declares. It is written out rather than read from the frame, because every
// read this realm exports is borrowed and would report whichever realm called
// it, building every link against somebody else's page.
const realmPath = "gno.land/r/moul/x/social/vouch/v0"

// denom is the only coin a bond can be posted in.
const denom = "ugnot"

// BoardSize is how many addresses the index page ranks.
const BoardSize = 10

// graph holds every vouch and the refund ledger. A redeploy would wipe it
// while leaving the bonded coins at this address, which is why this realm is
// not private (see gnomod.toml).
var graph = vo.NewGraph()

// Vouch records that the caller stands behind target, for the stated reason.
//
// It is payable: coins sent with the call are locked as a bond on this vouch
// and are returned by [Revoke], never by anything else. Sending nothing is
// fine and is the ordinary case.
//
// Vouching again for the same address UPDATES the reason and ADDS to the
// bond. It does not count twice: the score this realm exists to publish is a
// count of people, so a second transaction from the same address buys
// precisely nothing. Vouching for yourself is refused.
func Vouch(cur realm, target address, reason string) {
	who, userCall := caller(cur)
	bond := bondOf(userCall)

	updated, err := graph.Record(who, target, reason, bond, runtime.ChainHeight())
	if err != nil {
		panic(err.Error())
	}
	event := "Vouch"
	if updated {
		event = "Revouch"
	}
	chain.Emit(event, "from", who.String(), "for", target.String(),
		"bond", strconv.FormatInt(bond, 10))
}

// Revoke withdraws the caller's vouch for target and credits any bond back to
// them. The coins do not move here: call [Withdraw] to collect them.
//
// Splitting it in two is the pull-payment pattern. A realm that sent on revoke
// would be handing control to the recipient in the middle of its own state
// change, and a recipient that refuses the coins could make revoking
// impossible.
func Revoke(cur realm, target address) int64 {
	who, _ := caller(cur)
	refund, err := graph.Revoke(who, target)
	if err != nil {
		panic(err.Error())
	}
	chain.Emit("Revoke", "from", who.String(), "for", target.String(),
		"refund", strconv.FormatInt(refund, 10))
	return refund
}

// Withdraw pays the caller every bond their revoked vouches freed, and
// returns the amount sent.
//
// The credit is zeroed before the coins leave, so a recipient that calls
// straight back in finds nothing to take.
func Withdraw(cur realm) int64 {
	who, _ := caller(cur)
	amount, err := graph.Withdraw(who)
	if err != nil {
		panic(err.Error())
	}
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), who, chain.NewCoins(chain.NewCoin(denom, amount)))
	chain.Emit("Withdraw", "to", who.String(), "amount", strconv.FormatInt(amount, 10))
	return amount
}

// IsTrusted reports whether addr is vouched for by at least min distinct
// addresses. This is the gate, and it is one line at the call site.
//
// A min below one is read as one: a gate that lets everybody through is a bug
// in the caller rather than an answer this realm will agree to.
//
// It cannot tell you that the vouchers are distinct people. Two addresses
// vouching for each other both reach a score of one, which [Mutual] exposes
// and which is the reason to ask for more than one.
func IsTrusted(addr address, min int) bool { return graph.IsTrusted(addr, min) }

// ScoreOf is how many distinct addresses vouch for addr.
func ScoreOf(addr address) int { return graph.ScoreOf(addr) }

// BondedFor is the total ugnot locked on addr by everyone vouching for them.
func BondedFor(addr address) int64 { return graph.BondedFor(addr) }

// VouchedBy is every address that vouches for addr, sorted.
func VouchedBy(addr address) []address { return graph.VouchedBy(addr) }

// VouchesOf is every address addr vouches for, sorted.
func VouchesOf(addr address) []address { return graph.VouchesOf(addr) }

// Mutual reports whether a and b vouch for each other, which is the cheapest
// sybil shape and therefore worth discounting.
func Mutual(a, b address) bool { return graph.Mutual(a, b) }

// ReasonFrom is what from wrote about target, or the empty string. It is raw
// caller text: escape it before rendering it anywhere.
func ReasonFrom(from, target address) string { return graph.ReasonFrom(from, target) }

// BondFrom is what from locked on target, or zero.
func BondFrom(from, target address) int64 { return graph.BondFrom(from, target) }

// Count is how many vouches exist.
func Count() int { return graph.Count() }

// People is how many addresses have at least one vouch for them.
func People() int { return graph.People() }

// Owed is what addr can collect with [Withdraw].
func Owed(addr address) int64 { return graph.Owed(addr) }

// TotalBonded is everything locked on vouches that still stand.
func TotalBonded() int64 { return graph.TotalBonded() }

// TotalOwed is every revoked bond nobody has collected yet. This realm holds
// TotalBonded plus TotalOwed on behalf of other people.
func TotalOwed() int64 { return graph.TotalOwed() }

// Badge is the one-line trust mark for addr, for a host realm that wants to
// show what its gate just read. Like [IsTrusted] it is a borrowed read and
// takes no realm token.
func Badge(addr address) string {
	return vo.Badge(realmPath, addr, graph.ScoreOf(addr), graph.BondedFor(addr))
}

// bondOf reads the coins attached to this call, and only when the chain
// credited them to THIS realm.
//
// The envelope is the transaction's, not the frame's: a realm that was itself
// paid and then calls here would report coins sitting at its own address, and
// crediting them would let it bond money this realm never received. A realm
// may vouch, with no bond; a realm may not vouch while holding somebody's
// payment, and saying so loudly beats silently reading the bond as zero.
//
// It takes the answer rather than the frame because a realm argument in this
// package must be named cur, which would make this a crossing function.
func bondOf(userCall bool) int64 {
	if userCall {
		return envelope.Amount(denom)
	}
	if !envelope.IsEmpty() {
		panic("a realm cannot forward a bond: those coins were credited to the realm the user paid, not to this one")
	}
	return 0
}

// caller is the address that called us, checked the one way that is safe,
// plus whether it reached us as a direct user transaction.
//
// Both come from here so the realm reads cur.Previous() in exactly one place,
// the one guarded by cur.IsCurrent().
func caller(cur realm) (who address, userCall bool) {
	if !cur.IsCurrent() {
		panic("spoofed realm: cur is not the live crossing frame")
	}
	prev := cur.Previous()
	return prev.Address(), prev.IsUserCall()
}

package zones

import (
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/moul/kit/ui/v0"
	"gno.land/p/moul/md/v0"
	"gno.land/p/moul/realmpath/v0"
	"gno.land/p/moul/zones/v0"
)

// realmURL is this realm as gnoweb serves it. Absolute, because the path ends in
// /v0 and a relative link would resolve against the parent directory. Not
// derived at runtime: a Render has no cur, and CurrentRealm there is the caller.
// TestRealmURLMatchesTheModule pins it to the module line.
const realmURL = "/r/moul/zones/v0"

// pkgPath is this realm's package path, for the action links.
const pkgPath = "gno.land" + realmURL

// action is a call link to a function of THIS realm, named explicitly.
//
// Not ui.Action: that resolves its target through unsafe.CurrentRealm, which in
// a borrowed Render is the caller, so a realm embedding this page would get
// links that call its own functions. filetests/z_borrowed_render_filetest.gno
// pins it from a caller realm, the only place the difference shows.
func action(title, fn string, args ...string) string {
	return ui.ActionIn(pkgPath, title, fn, args...)
}

// PageSize is how many rows any table here shows at once. Every list is
// paginated and every page reads only its own records, because vm/qrender is
// gas-metered (3B per query) and a Render that outgrows it stops answering
// instead of slowing down. At the caps a page reads its 25 records, one lookup
// per URL it may mark flagged (each row's main RPC on the index; the zone's
// RPC and gnoweb on its page), the zone serving this chain for the printed
// command, the curators, and a few index nodes. Escaping free text is
// what dominates: about 97k gas a character on a node, so a page of full-length
// fields costs on the order of a billion, still under the ceiling.
const PageSize = 25

// Render is the whole public surface, three pages: the zone list (official,
// or retired with ?status=retired), one zone (?kind= narrows its endpoints),
// and the proposals (pending, or rejected with ?status=rejected). Every list
// takes ?page=.
func Render(path string) string {
	req := realmpath.Parse(path)
	// Exact paths only: a page that also answers zone/x/approved-by-gno-core
	// lends its content to whatever the extra segment claims.
	parts := len(req.PathParts())
	switch req.PathPart(0) {
	case "":
		if parts <= 1 {
			return renderIndex(req)
		}
	case "zone":
		if parts == 2 {
			return renderZone(req.PathPart(1), req)
		}
	case "proposals":
		if parts == 1 {
			return renderProposals(req)
		}
	}
	return notFound("No such page.")
}

func renderIndex(req *realmpath.Request) string {
	status, heading := zones.Approved, "Official"
	switch req.Query.Get("status") {
	case "", "approved":
	case "retired":
		status, heading = zones.Retired, "Retired"
	default:
		return notFound("No such list.")
	}
	query := ""
	if status == zones.Retired {
		query = "status=retired&"
	}
	table, pages := zoneTable(status, req, "")

	links := []string{}
	if status == zones.Retired {
		links = append(links, md.Link("official zones", realmURL))
	} else if n := reg.ZoneCount(zones.Retired); n > 0 {
		links = append(links, md.Link(strconv.Itoa(n)+" retired zone(s)", realmURL+":?status=retired"))
	}
	links = append(links,
		md.Link(strconv.Itoa(reg.ZoneCount(zones.Pending))+" proposal(s) waiting for review", realmURL+":proposals"))
	// Offered only while it can succeed: a link certain to fail is a dead end,
	// and the note says which cap is full (not what would free it: that
	// depends on who acts, and what frees one cap can fill another). A
	// full review queue still takes a curator's proposal, so the link stays,
	// labelled for them.
	propose := func(title string) string {
		return action(title, "ProposeZone",
			"slug", "", "chainID", "", "title", "", "description", "", "kind", "testnet",
			"gnowebURL", "", "rpcURL", "", "genesisURL", "")
	}
	switch {
	case reg.Live() >= zones.MaxZones:
		links = append(links, "the registry is full at "+strconv.Itoa(zones.MaxZones)+" live zones")
	case reg.Live() >= zones.MaxZones-zones.ReservedForReviewers:
		links = append(links, "the registry's last "+strconv.Itoa(zones.ReservedForReviewers)+" places are kept for curators",
			propose("Propose a zone (curators only)"))
	case reg.ZoneCount(zones.Pending) >= zones.MaxPending:
		links = append(links, "the review queue is full at "+strconv.Itoa(zones.MaxPending)+" proposals",
			propose("Propose a zone (curators only, while full)"))
	default:
		links = append(links, propose("Propose a zone"))
	}

	return ui.Join("\n",
		md.H1("Zones"),
		para("A curated registry of gno.land networks and the endpoints that reach them. "+
			"Anybody can propose a zone, and register endpoints on an official one; a curator approves, "+
			"rejects or retires a zone and verifies or flags its endpoints, and every rejection, "+
			"retirement and flag says why, in public."),
		md.H2(heading),
		table,
		pager("", query, pageNum(req, pages), pages),
		para(strings.Join(links, " · ")),
		md.H2("Read it from a node"),
		para("Every list is a plain function, so a node operator or a script can ask for it directly. "+
			"An empty kind or status matches anything."),
		md.CodeBlock(queryCommand(`ListAddresses("`+exampleSlug()+`", "peer", "verified")`)),
		md.BulletList([]string{
			md.InlineCode(`ListZones(status, kind)`) + ": `approved` is the official list",
			md.InlineCode(`GetZone(slug)`),
			md.InlineCode(`ListEndpoints(slug, kind, status)`) + ": kind is rpc, gnoweb, seed, peer, indexer, faucet or explorer",
			md.InlineCode(`ListAddresses(slug, kind, status)`) + ": the same, reduced to what a config file wants",
		}),
		para("Curated by "+curatorList()+"."),
	)
}

// zoneTable renders one page of the zones with that status, and returns how
// many pages there are.
func zoneTable(status zones.Status, req *realmpath.Request, empty string) (string, int) {
	pages := pageCount(reg.ZoneCount(status))
	var t *ui.Table
	switch status {
	case zones.Approved:
		t = ui.NewTable("zone", "chain id", "kind", "rpc", "endpoints")
	case zones.Pending:
		t = ui.NewTable("zone", "chain id", "kind", "proposed by", "review")
	case zones.Rejected:
		t = ui.NewTable("zone", "chain id", "proposed by", "why", "")
	default:
		t = ui.NewTable("zone", "chain id", "proposed by", "why")
	}
	for _, z := range reg.ZonePage(status, pageNum(req, pages), PageSize) {
		switch status {
		case zones.Approved:
			verified, total := reg.Count(z.Slug)
			t.Row(zoneLink(z), md.InlineCode(z.ChainID), string(z.Kind), md.InlineCode(z.RPCURL)+rpcFlag(z),
				strconv.Itoa(verified)+" verified of "+strconv.Itoa(total))
		case zones.Pending:
			// Review on the zone page, which shows what is being approved; the
			// Approve link there carries the revision it was rendered from.
			t.Row(zoneLink(z), md.InlineCode(z.ChainID), string(z.Kind), ui.AddrFull(z.Proposer),
				md.Link("review", realmURL+":zone/"+z.Slug))
		case zones.Rejected:
			t.Row(zoneLink(z), md.InlineCode(z.ChainID), ui.AddrFull(z.Proposer), cell(z.Reason),
				action("Remove", "RemoveZone", "slug", z.Slug, "revision", revStr(z)))
		default:
			t.Row(zoneLink(z), md.InlineCode(z.ChainID), ui.AddrFull(z.Proposer), cell(z.Reason))
		}
	}
	if empty == "" {
		empty = "No " + string(status) + " zone yet."
	}
	return t.OrEmpty(empty), pages
}

func renderZone(slug string, req *realmpath.Request) string {
	z, ok := reg.Zone(slug)
	if !ok {
		return notFound("No such zone.")
	}
	kind := zones.EndpointKind(req.Query.Get("kind"))
	if kind != "" && !isKind(kind) {
		return notFound("No such endpoint kind.")
	}

	facts := []string{
		md.Bold("chain id") + ": " + md.InlineCode(z.ChainID),
		md.Bold("kind") + ": " + string(z.Kind),
		md.Bold("rpc") + ": " + md.InlineCode(z.RPCURL) + rpcFlag(z),
	}
	if z.GnowebURL != "" {
		facts = append(facts, md.Bold("gnoweb")+": "+urlFact(z, zones.Gnoweb, z.GnowebURL))
	}
	if z.GenesisURL != "" {
		facts = append(facts, md.Bold("genesis")+": "+urlFact(z, "", z.GenesisURL))
	}
	// Addresses in full, here and on every page: an 8+4 shortening is about 50
	// bits, within reach of a vanity grinder who wants to look like a curator.
	facts = append(facts, md.Bold("proposed")+" by "+ui.AddrFull(z.Proposer)+" at block "+strconv.FormatInt(z.ProposedAt, 10))
	if z.EditedBy != "" {
		facts = append(facts, md.Bold("edited")+" by "+ui.AddrFull(z.EditedBy)+" at block "+strconv.FormatInt(z.EditedAt, 10))
	}
	facts = append(facts, md.Bold("revision")+": "+strconv.FormatInt(z.Revision, 10))
	if z.Reviewed() {
		facts = append(facts, md.Bold("last reviewed")+" "+reviewText(z.ReviewedBy, z.ReviewedAt, z.Reason))
	}

	parts := []string{
		md.H1(prose(z.Title)),
		para(statusBadge(z.Status) + " · " + md.InlineCode(z.Slug)),
	}
	if z.Description != "" {
		parts = append(parts, para(prose(z.Description)))
	}
	parts = append(parts, md.BulletList(facts), md.H2("Endpoints"))

	// One link per kind the zone has, from the index counts: no endpoint is
	// read to draw them.
	base := realmURL + ":zone/" + z.Slug
	kinds := []string{}
	if all := reg.EndpointCount(z.Slug, ""); all > 0 {
		kinds = append(kinds, kindLink("all", base, all, kind == ""))
		for _, k := range zones.EndpointKinds() {
			if n := reg.EndpointCount(z.Slug, k); n > 0 {
				kinds = append(kinds, kindLink(string(k), base+"?kind="+string(k), n, kind == k))
			}
		}
		parts = append(parts, para(strings.Join(kinds, " · ")))
	}

	pages := pageCount(reg.EndpointCount(z.Slug, kind))
	// The revision column is what a verdict or a removal names; a verification
	// also names the zone's revision, shown above.
	t := ui.NewTable("#", "revision", "kind", "address", "label", "status", "registered by")
	for _, e := range reg.EndpointPage(z.Slug, kind, pageNum(req, pages), PageSize) {
		t.Row(
			strconv.FormatInt(e.ID, 10),
			strconv.FormatInt(e.Revision, 10),
			string(e.Kind),
			md.InlineCode(e.Address),
			cell(e.Label),
			endpointStatus(e),
			ui.AddrFull(e.Registrant),
		)
	}
	query := ""
	if kind != "" {
		query = "kind=" + string(kind) + "&"
	}
	empty := "No endpoint registered yet."
	if kind != "" {
		empty = "No " + string(kind) + " endpoint registered yet."
	}
	parts = append(parts, t.OrEmpty(empty), pager("zone/"+z.Slug, query, pageNum(req, pages), pages))

	actions := []string{}
	open := z.Status == zones.Approved || z.Status == zones.Pending
	switch {
	case open && reg.EndpointCount(z.Slug, "") >= zones.MaxEndpointsPerZone:
		actions = append(actions, "endpoints are full at "+strconv.Itoa(zones.MaxEndpointsPerZone))
	case open && reg.EndpointCount(z.Slug, "") >= zones.MaxEndpointsPerZone-zones.ReservedForReviewers:
		actions = append(actions, "the last "+strconv.Itoa(zones.ReservedForReviewers)+" endpoint places are kept for curators",
			action("Register an endpoint (curators only)", "RegisterEndpoint",
				"slug", z.Slug, "kind", "rpc", "addr", "", "label", ""))
	case open && reg.Awaiting(z.Slug) >= zones.MaxUnverifiedPerZone:
		actions = append(actions, "the review queue is full at "+strconv.Itoa(zones.MaxUnverifiedPerZone)+" endpoints awaiting review",
			action("Register an endpoint (curators only, while full)", "RegisterEndpoint",
				"slug", z.Slug, "kind", "rpc", "addr", "", "label", ""))
	case z.Status == zones.Approved:
		actions = append(actions, action("Register an endpoint", "RegisterEndpoint",
			"slug", z.Slug, "kind", "rpc", "addr", "", "label", ""))
	case z.Status == zones.Pending && !curators.Has(z.Proposer) && reg.OwnerCount(z.Slug, z.Proposer) >= zones.MaxEndpointsPerAddress:
		// On a pending zone the proposer is the one gated registrant.
		actions = append(actions, "the proposer has registered "+strconv.Itoa(zones.MaxEndpointsPerAddress)+" endpoints here, the limit per address",
			action("Register an endpoint (curators only)", "RegisterEndpoint",
				"slug", z.Slug, "kind", "rpc", "addr", "", "label", ""))
	case z.Status == zones.Pending:
		actions = append(actions, action("Register an endpoint (proposer or curator)", "RegisterEndpoint",
			"slug", z.Slug, "kind", "rpc", "addr", "", "label", ""))
	}
	// A flood clears in one call, on any zone the call takes (a rejected or
	// retired zone's records are a curator's to remove too). The call reaches
	// every page and every kind, so it is offered only on the unfiltered view,
	// only while it would clear something (the clearable count, no endpoint
	// read), labelled with its real scope, and bounded in time: an endpoint
	// registered after this page was rendered has a later revision and is kept.
	if n := reg.Clearable(z.Slug); kind == "" && n > 0 {
		actions = append(actions, action("Clear "+strconv.Itoa(n)+" never-reviewed endpoint(s) registered through the review queue, all pages and kinds (curators only)", "ClearUnreviewed",
			"slug", z.Slug, "throughRevision", strconv.FormatInt(reg.Revision(), 10)))
	}
	// Every decision carries the revision this page was rendered from, so acting
	// on what you read here fails if the zone changed after you read it.
	rev := revStr(z)
	approve := action("Approve revision "+rev, "ApproveZone", "slug", z.Slug, "revision", rev, "reason", "")
	remove := action("Remove", "RemoveZone", "slug", z.Slug, "revision", rev)
	switch z.Status {
	case zones.Pending:
		actions = append(actions, approve,
			action("Reject", "RejectZone", "slug", z.Slug, "revision", rev, "reason", ""), remove)
		if reg.ZoneCount(zones.Rejected) >= zones.MaxRejected {
			actions = append(actions, "rejecting it drops the zone rejected longest ago, endpoints and all")
		}
	case zones.Approved:
		actions = append(actions, action("Retire", "RetireZone", "slug", z.Slug, "revision", rev, "reason", ""))
		if reg.ZoneCount(zones.Retired) >= zones.MaxRetired {
			actions = append(actions, "retiring it drops the zone retired longest ago, endpoints and all")
		}
	case zones.Rejected, zones.Retired:
		// Back into the live registry only while it has room.
		if reg.Live() < zones.MaxZones {
			actions = append(actions, approve)
		} else {
			actions = append(actions, "approving it waits for a free place: the registry is full at "+strconv.Itoa(zones.MaxZones)+" live zones")
		}
		if z.Status == zones.Rejected {
			actions = append(actions, remove)
		}
	}
	parts = append(parts,
		para(strings.Join(actions, " · ")),
		md.CodeBlock(queryCommand(`GetZone("`+z.Slug+`")`)),
		para(md.Link("All zones", realmURL)),
	)
	return ui.Join("\n", parts...)
}

func renderProposals(req *realmpath.Request) string {
	status, heading, other := zones.Pending, "Pending", ""
	switch req.Query.Get("status") {
	case "", "pending":
		if n := reg.ZoneCount(zones.Rejected); n > 0 {
			other = md.Link(strconv.Itoa(n)+" rejected", realmURL+":proposals?status=rejected")
		}
	case "rejected":
		status, heading = zones.Rejected, "Rejected"
		other = md.Link("pending", realmURL+":proposals")
	default:
		return notFound("No such list.")
	}
	query := ""
	if status == zones.Rejected {
		query = "status=rejected&"
	}
	empty := "Nothing waiting for review."
	if status == zones.Rejected {
		empty = "Nothing rejected."
	}
	table, pages := zoneTable(status, req, empty)
	links := []string{}
	if other != "" {
		links = append(links, other)
	}
	links = append(links, md.Link("All zones", realmURL))
	return ui.Join("\n",
		md.H1("Proposals"),
		para("Zones somebody proposed and no curator has approved. Only an approved zone is official."),
		md.H2(heading),
		table,
		pager("proposals", query, pageNum(req, pages), pages),
		para(strings.Join(links, " · ")),
	)
}

// pageCount is how many pages n rows make, at least one.
func pageCount(n int) int {
	pages := n / PageSize
	if n%PageSize != 0 {
		pages++
	}
	if pages < 1 {
		pages = 1
	}
	return pages
}

// pageNum reads ?page= and clamps it into 1..pages: it is a reader's input,
// and ?page=-1 must not render a footer saying "page -1 of 2".
func pageNum(req *realmpath.Request, pages int) int {
	page := 1
	raw := req.Query.Get("page")
	if n, err := strconv.Atoi(raw); err == nil {
		page = n
	} else if digits := strings.TrimPrefix(raw, "+"); digits != "" && strings.Trim(digits, "0123456789") == "" {
		// All digits and still unparseable: a positive number past int. It is
		// past the last page too, so it lands there, as any big number does.
		page = pages
	}
	if page < 1 {
		page = 1
	}
	if page > pages {
		page = pages
	}
	return page
}

// pager links the neighbouring pages of a list, keeping the list's other query
// parameters (query ends in "&" when not empty). One page needs no pager.
func pager(path, query string, page, pages int) string {
	if pages < 2 {
		return ""
	}
	link := func(n int) string { return realmURL + ":" + path + "?" + query + "page=" + strconv.Itoa(n) }
	out := ""
	if page > 1 {
		out += md.Link("previous", link(page-1)) + " · "
	}
	out += "page " + strconv.Itoa(page) + " of " + strconv.Itoa(pages)
	if page < pages {
		out += " · " + md.Link("next", link(page+1))
	}
	return para(out)
}

func kindLink(label, url string, n int, current bool) string {
	text := label + " (" + strconv.Itoa(n) + ")"
	if current {
		return md.Bold(text)
	}
	return md.Link(text, url)
}

func notFound(msg string) string { return md.H1("Not found") + ui.Empty(msg) }

// queryCommand is the gnokey line that evaluates call against this realm.
//
// The remote is looked up in the registry itself, by the chain id this realm is
// running on, so the command a reader copies points at the chain they are
// reading. A chain the registry does not list gets no -remote, rather than a
// guessed one, and so does a chain id two approved zones share (every gnodev
// is "dev"): picking one would be the same guess.
//
// A reader pastes this into a shell, so the remote must never carry shell
// syntax. Two layers make sure: the main RPC is validated down to
// <scheme>://<host>[:<port>], host [A-Za-z0-9.-] and port digits, which leaves
// nothing a shell reads as syntax; and it is single-quoted anyway, a quote being
// the one character no URL here can contain, so a later, wider validator does
// not reopen it. The call is built from charset-checked slugs and literals.
func queryCommand(call string) string {
	remote := ""
	if z, ok := reg.SoleApproved(runtime.ChainID()); ok && !rpcFlagged(z) {
		// Not one the same page flags: printing a remote the endpoint table says
		// not to use would contradict the page.
		remote = " -remote '" + z.RPCURL + "'"
	}
	return "gnokey query vm/qeval" + remote + " -data '" + pkgPath + "." + call + "'"
}

// exampleSlug is the zone the index's example asks for peers of: the one
// serving the chain this page is read on, when there is exactly one and it
// lists a peer, else onyx (one zone and an index count read).
func exampleSlug() string {
	if z, ok := reg.SoleApproved(runtime.ChainID()); ok && reg.EndpointCount(z.Slug, zones.Peer) > 0 {
		return z.Slug
	}
	return "onyx"
}

// para is one paragraph as a Join part. Not md.Paragraph, whose trailing blank
// line plus Join's separator makes two in a row, which an example cannot pin.
func para(s string) string { return s + "\n" }

// zoneLink is a zone's title linking to its page, for a TABLE cell. Built by
// hand rather than with md.Link, whose text escape is for prose and leaves a
// pipe literal, so a title like "Alice|official" would open a column in every
// zone table. ui.Cell escapes the pipe too; the destination is a constant plus
// a slug checked to [a-z0-9-] at write time.
func zoneLink(z zones.Zone) string {
	return "[" + cell(z.Title) + "](" + realmURL + ":zone/" + z.Slug + ")"
}

// urlFact shows a zone's URL as its own text, never behind a label, so a
// reader sees where it goes: a proposal's "genesis.json" link could otherwise
// open anything, a pre-filled transaction form included, right under the
// Approve button. Only an approved zone's URLs are links; a proposal's are
// code, to copy and check, not to click.
//
// A URL the zone also lists, under the kind it is shown as, as a flagged
// endpoint is code and marked, never a link: the page does not offer what its
// own endpoint table says not to use. kind is what the URL is shown as, ""
// for the genesis URL, which no endpoint kind lists (flaggedAs).
func urlFact(z zones.Zone, kind zones.EndpointKind, url string) string {
	if kind != "" && flaggedAs(z, kind, url) {
		return md.InlineCode(url) + " ⚠️ flagged"
	}
	if z.Status == zones.Approved {
		return md.Link(url, url)
	}
	return md.InlineCode(url)
}

// prose and cell escape a caller's free text for a sentence and a table cell,
// plus what ui.Inline and ui.Cell leave alone: gnoweb turns an @name, and a
// bare g1 address after a space or at the start, into a user-profile link with
// an icon, so "run by @gnocore" or "run by g1…" would vouch for an account the
// registrant chose.
func prose(s string) string { return escapeMentions(ui.Inline(s)) }

func cell(s string) string { return escapeMentions(ui.Cell(s)) }

// escapeMentions backslash-escapes every @, and writes the 1 of every g1 as a
// character reference. It runs after ui.Inline or ui.Cell, which escape every
// & the caller typed, so the only reference in the output is this one; goldmark
// decodes it back to "1" after the mention parser has looked and not matched.
//
// One pass, and none at all when there is nothing to escape: it runs on every
// free-text field of every page.
func escapeMentions(s string) string {
	if !strings.Contains(s, "@") && !strings.Contains(s, "g1") {
		return s
	}
	// Copy the runs between matches in one piece each: a byte at a time costs a
	// native call per byte, every page, on text a stranger chose.
	var b strings.Builder
	n, last := len(s), 0
	for i := 0; i < n; i++ {
		switch {
		case s[i] == '@':
			b.WriteString(s[last:i])
			b.WriteString("\\@")
			last = i + 1
		case s[i] == 'g' && i+1 < n && s[i+1] == '1':
			b.WriteString(s[last:i])
			b.WriteString("g&#49;")
			i++
			last = i + 1
		}
	}
	b.WriteString(s[last:])
	return b.String()
}

// rpcFlag marks a zone's main RPC when the endpoint table flags it, so the
// table, the zone page and the printed command never disagree.
func rpcFlag(z zones.Zone) string {
	if rpcFlagged(z) {
		return " ⚠️ flagged"
	}
	return ""
}

func rpcFlagged(z zones.Zone) bool { return flaggedAs(z, zones.RPC, z.RPCURL) }

// flaggedAs reports whether a URL the page shows as a kind (the main RPC as
// rpc, the gnoweb URL as gnoweb) is listed under that kind and flagged. Only
// that kind's verdict counts. A listing under another kind is anybody's to
// make on an approved zone, so letting its flag mark the zone's own URL would
// let a stranger's mis-kinded entry, flagged as mis-kinded, mark an official
// URL; a curator who means the zone's URL flags it under its own kind. The
// lookup compares in Canonical form, which reads an rpc tcp:// as the http://
// gnokey dials, so either spelling finds the other.
func flaggedAs(z zones.Zone, shown zones.EndpointKind, url string) bool {
	e, ok := reg.EndpointByAddress(z.Slug, shown, url)
	return ok && e.Status == zones.Flagged
}

func revStr(z zones.Zone) string { return strconv.FormatInt(z.Revision, 10) }

func isKind(k zones.EndpointKind) bool {
	for _, x := range zones.EndpointKinds() {
		if k == x {
			return true
		}
	}
	return false
}

func statusBadge(s zones.Status) string {
	switch s {
	case zones.Approved:
		return "✅ " + md.Bold("official")
	case zones.Pending:
		return "⏳ " + md.Bold("pending review")
	case zones.Rejected:
		return "❌ " + md.Bold("rejected")
	case zones.Retired:
		return "⏹️ " + md.Bold("retired")
	}
	return string(s)
}

func endpointStatus(e zones.Endpoint) string {
	s := ""
	switch e.Status {
	case zones.Verified:
		s = "✅ verified"
	case zones.Flagged:
		s = "⚠️ flagged"
	default:
		s = "unverified"
	}
	if e.Reason != "" {
		s += ": " + cell(e.Reason)
	}
	if e.ReviewedBy != "" {
		s += " (" + ui.AddrFull(e.ReviewedBy) + ", block " + strconv.FormatInt(e.ReviewedAt, 10) + ")"
	}
	return s
}

func reviewText(by address, at int64, reason string) string {
	s := "by " + ui.AddrFull(by) + " at block " + strconv.FormatInt(at, 10)
	if reason != "" {
		s += ": " + prose(reason)
	}
	return s
}

func curatorList() string {
	out := []string{}
	for _, a := range Curators() {
		out = append(out, ui.AddrFull(a))
	}
	return strings.Join(out, ", ")
}

