// seed files every seed through the same Registry methods a caller's
// transaction goes through (the gated ones, so a seeded endpoint is not
// Exempt; each is ruled on at once, so none is clearable), so a seed that
// would fail validation fails the deploy instead of shipping a zone no later
// edit could reproduce.
func seed() {
	at := runtime.ChainHeight()
	for _, s := range seeds() {
		must(reg.Propose(Admin, at, s.slug, s.info))
		must(reg.ReviewZone(s.slug, zones.Approved, mustZone(s.slug).Revision, Admin, at, seedReason))
		for _, e := range s.endpoints {
			k, err := zones.ParseEndpointKind(e[0])
			must(err)
			id, err := reg.Register(Admin, at, s.slug, k, e[1], e[2])
			must(err)
			ep, _ := reg.Endpoint(id)
			zrev := mustZone(s.slug).Revision // the approval moved it
			if s.failed == "" {
				must(reg.ReviewEndpoint(id, zones.Verified, zrev, ep.Revision, Admin, at, seedReason))
			} else {
				must(reg.ReviewEndpoint(id, zones.Flagged, zrev, ep.Revision, Admin, at, s.failed))
			}
		}
	}
}

